window.KB_V2={"schema":2,"updated":"2026-10-30","evidence":{"established":{"ar":"علم ثابت","en":"Established science"},"consensus":{"ar":"إجماع مهني","en":"Professional consensus"},"estimate":{"ar":"تقدير عمل","en":"Working estimate"}},"sources":[{"id":"S1","type":"textbook","cite":"Figoni, P. (2011). How Baking Works: Exploring the Fundamentals of Baking Science, 3rd ed. Hoboken, NJ: John Wiley & Sons."},{"id":"S2","type":"textbook","cite":"McGee, H. (2004). On Food and Cooking: The Science and Lore of the Kitchen, revised ed. New York: Scribner."},{"id":"S3","type":"textbook","cite":"Cauvain, S. P., & Young, L. S. (2006). Baked Products: Science, Technology and Practice. Oxford: Blackwell Publishing."},{"id":"S4","type":"textbook","cite":"Greweling, P. P. (2013). Chocolates and Confections: Formula, Theory, and Technique for the Artisan Confectioner, 2nd ed. Hoboken, NJ: John Wiley & Sons."},{"id":"S5","type":"textbook","cite":"Beckett, S. T. (Ed.) (2009). Industrial Chocolate Manufacture and Use, 4th ed. Chichester: Wiley-Blackwell."},{"id":"S6","type":"regulation","cite":"U.S. Food and Drug Administration (2022). Food Code 2022, section 3-501.14 Cooling."},{"id":"S7","type":"textbook","cite":"Delcour, J. A., & Hoseney, R. C. (2010). Principles of Cereal Science and Technology, 3rd ed. St. Paul, MN: AACC International."},{"id":"S8","type":"textbook","cite":"Hartel, R. W., von Elbe, J. H., & Hofberger, R. (2018). Confectionery Science and Technology. Cham: Springer."},{"id":"S9","type":"regulation","cite":"Codex Alimentarius (1971, amended 2018). Standard for Butter, CXS 279-1971. Rome: FAO/WHO."}],"problems":[{"id":"pastry-cream-grainy","category":"custard","status":"draft","reviewedBy":null,"severity":"medium","rescuable":true,"symptom":{"ar":"الكريمة باتسيير محببة أو فيها حبيبات","en":"Pastry cream is grainy or has bits in it","syn":{"ar":["كريم باتسيير محبب","الكاسترد فيه كتل","الكريمة مقطّعة","فيها حبوب","كريمة محببة","الكريمة فيها قطع بيض"],"en":["grainy pastry cream","lumpy creme patissiere","curdled custard","pastry cream has bits","pastry cream not smooth"]}},"see":{"ar":"حبيبات صغيرة تبين بالعين أو تحسها على اللسان، وغالباً الكريمة باهتة وما تلمع.","en":"Small grains you can see or feel on the tongue, often with a dull surface."},"questions":[{"id":"when","ar":"متى ظهرت الحبيبات؟","en":"When did the grains appear?","options":[{"id":"cook","ar":"أثناء الطبخ","en":"While cooking"},{"id":"chill","ar":"بعد التبريد","en":"After chilling"},{"id":"beat","ar":"بعد ما خفقتها باردة أو أضفت لها شي","en":"After beating it cold or adding something"}]},{"id":"boil","ar":"هل غلت الكريمة وفقّعت دقيقة على الأقل بعد ما ثخنت؟","en":"Did it bubble for at least a minute after thickening?","options":[{"id":"yes","ar":"نعم","en":"Yes"},{"id":"no","ar":"لا، أو ما أدري","en":"No, or not sure"}]},{"id":"strain","ar":"هل صفّيت الكريمة وهي حارة؟","en":"Did you strain it hot?","options":[{"id":"yes","ar":"نعم، بمصفاة ناعمة","en":"Yes, through a fine sieve"},{"id":"no","ar":"لا","en":"No"}]}],"causes":[{"id":"yolk-scramble","kind":"process","prior":1,"evidence":"established","src":["S2","S1"],"title":{"ar":"تخثّر الصفار","en":"The yolk scrambled"},"why":{"ar":"بروتينات الصفار تتجمد بين 62 و70°م تقريباً. إذا سخن القاع أو الزوايا قبل ما يثخن النشا، يتجمد الصفار هناك كحبيبات. السكر والنشا يرفعان حرارة التجمد ويحميان الصفار، فالوصفة القليلة فيهما أقل تسامحاً.","en":"Yolk proteins set at roughly 62–70 °C. If the bottom or corners overheat before the starch thickens, the yolk sets there as grains. Sugar and starch raise the setting temperature and protect the yolk, so a recipe low in both is less forgiving."},"rule":{"feat":"thickPct","when":"below","range":{"default":[4,7]},"evidence":"estimate","src":["S2"],"note":{"ar":"نسبة النشا للكريمة باتسيير بالنشا: نطاق عمل من وصفات مهنية شائعة، يحتاج اعتماد مراجع.","en":"Starch level for cornstarch pastry cream: a working range from common professional formulas, pending review."}},"answers":{"when":{"cook":2,"chill":-1,"beat":-2},"strain":{"no":1}},"fixes":[{"type":"process","evidence":"consensus","src":["S1"],"ar":"اسكب ثلث الحليب الحار على الصفار والسكر مع الخفق، ثم أرجع الكل للقدر. اخفق بلا توقف ووصّل للقاع والزوايا على نار متوسطة، واستعمل قدراً سميك القاع.","en":"Pour a third of the hot milk onto the yolks and sugar while whisking, then return everything to the pan. Whisk non-stop, reaching the bottom and corners, on medium heat in a heavy-based pan.","tradeoff":{"ar":"يزيد وقت الطبخ دقيقة أو دقيقتين، وما يغيّر الطعم.","en":"Adds a minute or two of cooking; no change in taste."}},{"type":"recipe","evidence":"estimate","src":["S2"],"ar":"ارفع النشا إلى حوالي 4.5% من وزن الكريمة ليحمي الصفار.","en":"Raise the starch to about 4.5% of the cream weight so it protects the yolk.","op":{"op":"reach","role":"starch","feat":"thickPct","target":4.5},"tradeoff":{"ar":"نشا أكثر يعطي قواماً أثقل ولمعة أقل، وتتماسك الكريمة أكثر بعد التبريد.","en":"More starch gives a heavier, less glossy cream that sets firmer after chilling."}}],"verify":{"ar":"في الدفعة الجاية اخفق بلا توقف وقِس الحرارة. إذا طلعت الكريمة ناعمة قبل التصفية، فالسبب كان التخثّر.","en":"Next batch, whisk non-stop and watch the temperature. If the cream is smooth before straining, scrambling was the cause."}},{"id":"starch-undercooked","kind":"process","prior":0,"evidence":"established","src":["S2","S7"],"title":{"ar":"النشا ما انطبخ كفاية","en":"The starch was undercooked"},"why":{"ar":"نشا الذرة ما ينتفخ كاملاً إلا قرب الغليان. ويحتاج يفقّع دقيقة إلى دقيقتين عشان ينتفخ كاملاً ويوقف إنزيم الأميليز اللي في الصفار. النشا غير المطبوخ يعطي ملمساً ترابياً، والإنزيم يخلي الكريمة ترتخي بعد يوم.","en":"Cornstarch only swells fully near the boil. It needs to bubble for one to two minutes to swell completely and to stop the amylase in yolk. Undercooked starch feels gritty, and the enzyme thins the cream a day later."},"answers":{"boil":{"no":3,"yes":-2},"when":{"cook":1}},"fixes":[{"type":"process","evidence":"established","src":["S2"],"ar":"بعد ما تثخن، خلها تفقّع بهدوء دقيقة إلى دقيقتين مع الخفق.","en":"Once thick, let it bubble gently for one to two minutes while whisking.","tradeoff":{"ar":"يتبخر شوي ماء فيصير القوام أثقل قليلاً.","en":"A little water evaporates, so it thickens slightly more."}}],"verify":{"ar":"ذُق: ما يبقى طعم نشا ولا ملمس ترابي. وبعد 24 ساعة في الثلاجة ما ترتخي.","en":"Taste: no starchy taste or gritty feel. After 24 hours chilled it does not thin out."}},{"id":"not-strained","kind":"process","prior":0,"evidence":"consensus","src":["S1"],"title":{"ar":"ما انصفّت","en":"It was not strained"},"why":{"ar":"خيوط البيض والقشرة اللي تتكوّن على القاع وأي حبة متجمدة تبقى كنقاط واضحة. التصفية وهي حارة تشيلها.","en":"Egg strands, the skin that forms on the base and any set bits stay as visible specks. Straining while hot removes them."},"answers":{"strain":{"no":2,"yes":-2},"when":{"cook":1}},"fixes":[{"type":"process","evidence":"consensus","src":["S1"],"ar":"صفّ الكريمة وهي حارة مباشرة في وعاء نظيف بمصفاة ناعمة.","en":"Strain the cream while hot straight into a clean container through a fine sieve.","tradeoff":{"ar":"تفقد 1 إلى 2% من الوزن في المصفاة.","en":"You lose 1–2% of the weight in the sieve."}}],"verify":{"ar":"صفّ نصف الدفعة ولا تصفّ الثاني وقارن: إذا الفرق واضح، فهذا هو السبب.","en":"Strain half the batch and not the other half, then compare. A clear difference confirms the cause."}},{"id":"gel-broken","kind":"process","prior":0,"evidence":"established","src":["S1","S7"],"title":{"ar":"جل النشا تكسّر بعد التبريد","en":"The cold starch gel broke"},"why":{"ar":"جل نشا الذرة بعد ما يبرد يصير هشاً. الخفق القوي أو إضافة زبدة باردة أو سائل يكسره إلى كتل صغيرة. ومع يوم أو يومين في الثلاجة يرجع النشا يتبلور فيطرد ماء ويبين مقطّعاً.","en":"A cooled cornstarch gel is short and brittle. Hard beating or adding cold butter or liquid breaks it into small curds. After a day or two chilled the starch re-crystallises, weeps and looks curdled."},"answers":{"when":{"beat":3,"chill":2,"cook":-2}},"fixes":[{"type":"process","evidence":"consensus","src":["S1"],"ar":"نعّمها بهدوء بالمضرب المسطح أو مرّرها من المصفاة بدل الخفق القوي. أضف الزبدة والكريمة ما زالت دافئة (40 إلى 50°م تقريباً).","en":"Smooth it gently with a paddle or press it through a sieve instead of beating hard. Add butter while the cream is still warm (about 40–50 °C).","tradeoff":{"ar":"تنعيم أخف يعني قواماً أثقل قليلاً.","en":"Gentler smoothing leaves it slightly heavier."}}],"verify":{"ar":"خذ عيّنة باردة ونعّمها بالملعقة. إذا رجعت ناعمة، فالسبب كان تكسير الجل.","en":"Take a cold sample and smooth it with a spoon. If it turns smooth again, the broken gel was the cause."}},{"id":"flour-thickener","kind":"formula","prior":0,"evidence":"established","src":["S1","S2"],"title":{"ar":"التكثيف بالدقيق بدل النشا","en":"Thickened with flour instead of starch"},"why":{"ar":"دقيق القمح فيه بروتين مع النشا، فيعطي قواماً أعتم وأكثف وأقل نعومة. نشا الذرة يعطي كريمة أنعم وألمع.","en":"Wheat flour carries protein along with starch, so it gives a duller, pastier, less smooth texture. Cornstarch gives a smoother, glossier cream."},"rule":{"feat":"flourThick","when":"above","range":{"default":[0,0.5]},"evidence":"consensus","src":["S1"]},"answers":{"when":{"cook":1}},"fixes":[{"type":"recipe","evidence":"consensus","src":["S2"],"ar":"بدّل الدقيق بنشا ذرة بنصف وزنه تقريباً، لأن قوة تكثيف النشا تقارب ضعف الدقيق.","en":"Replace the flour with about half its weight of cornstarch; starch has roughly twice the thickening power of flour.","op":{"op":"swap","from":"flour","to":"starch","factor":0.5,"name":{"ar":"نشا ذرة","en":"Cornstarch"},"comp":{"w":0.12}},"tradeoff":{"ar":"أنعم وألمع، لكن الجل أقصر وما يتحمل التجميد.","en":"Smoother and glossier, but a shorter gel that does not tolerate freezing."}}],"verify":{"ar":"اطبخ دفعتين صغيرتين، وحدة بالدقيق ووحدة بالنشا، وقارن اللمعة والنعومة.","en":"Cook two small batches, one with flour and one with starch, and compare gloss and smoothness."}}],"rescue":{"ar":["إذا الحبيبات من تخثّر خفيف: صفّها وهي حارة، واخلطها بالبلندر 20 إلى 30 ثانية.","إذا فيها قطع بيض واضحة أو ريحة كبريت، لا تستعملها في منتج للبيع."],"en":["If the grains are light scrambling, strain it hot and blend it with a stick blender for 20–30 seconds.","If there are clear egg pieces or a sulphur smell, do not use it in a product for sale."],"safety":{"ar":"برّد الكريمة بسرعة: غطّها بغلاف ملامس للسطح وانقلها للثلاجة. المرجع: من 57 إلى 21°م خلال ساعتين، ثم إلى 5°م خلال 4 ساعات إضافية.","en":"Cool the cream fast: cover with film touching the surface and refrigerate. Reference: from 57 to 21 °C within 2 hours, then to 5 °C within a further 4 hours.","src":["S6"]}},"prevent":{"ar":["قدر سميك القاع ونار متوسطة.","اخفق بلا توقف ووصّل للزوايا.","خلّها تفقّع دقيقة إلى دقيقتين.","صفّها وهي حارة.","برّدها بسرعة وغطاء ملامس للسطح."],"en":["Heavy pan, medium heat.","Whisk non-stop, into the corners.","Let it bubble one to two minutes.","Strain it hot.","Cool it fast with film on the surface."]},"notFormula":{"ar":"إذا النشا 4 إلى 7% من الوزن، وغلت دقيقة، وانصفّت، فالسبب غالباً في التنفيذ: الحرارة أو الخفق أو القدر.","en":"If the starch is 4–7% of the weight, it boiled for a minute and was strained, the cause is most likely the process: heat, whisking or the pan."},"unsure":{"ar":"ما أقدر أحدد السبب من الأرقام وحدها. جاوب الأسئلة، أو جرّب: صفّ نصف الدفعة ولا تصفّ الثاني وقارن.","en":"I cannot tell the cause from the numbers alone. Answer the questions, or try straining half the batch and comparing."}},{"id":"ganache-split","category":"ganache","status":"draft","reviewedBy":null,"severity":"medium","rescuable":true,"symptom":{"ar":"الغاناش انفصل وطلع منه زيت","en":"Ganache split and released oil","syn":{"ar":["الغاناش انفصل","الغاناش مقطّع","طلع زيت من الغاناش","الغاناش صار محبب","الغاناش دهني","الحشوة طلعت زيت"],"en":["ganache split","broken ganache","oily ganache","grainy ganache","ganache separated"]}},"see":{"ar":"سطح دهني وقطرات زيت، والقوام محبب أو مقطّع بدل ما يكون لامع ومرن.","en":"A greasy surface with oil drops, and a grainy or broken texture instead of a glossy, elastic one."},"questions":[{"id":"when","ar":"متى انفصل؟","en":"When did it split?","options":[{"id":"mix","ar":"أثناء الخلط","en":"While mixing"},{"id":"set","ar":"بعد التبريد أو التبلور","en":"After cooling or setting"},{"id":"days","ar":"بعد أيام داخل المنتج","en":"Days later inside the product"}]},{"id":"temp","ar":"كم كانت حرارة الخليط وقت الخلط؟","en":"What was the temperature when you mixed?","options":[{"id":"cold","ar":"تحت 32°م","en":"Below 32 °C"},{"id":"ok","ar":"32 إلى 40°م","en":"32–40 °C"},{"id":"hot","ar":"فوق 45°م","en":"Above 45 °C"},{"id":"nk","ar":"ما قستها","en":"Did not measure"}]},{"id":"tool","ar":"كيف خلطت؟","en":"How did you mix?","options":[{"id":"whisk","ar":"مضرب يدوي (ويسك)","en":"Whisk"},{"id":"blender","ar":"خلاط يدوي (بلندر)","en":"Stick blender"},{"id":"spatula","ar":"ملعقة مطاطية","en":"Spatula"}]}],"causes":[{"id":"too-hot","kind":"process","prior":1,"evidence":"established","src":["S4","S5"],"title":{"ar":"الحرارة عالية وقت الخلط","en":"Too hot while mixing"},"why":{"ar":"فوق 40°م تقريباً تكون الدهون سائلة كاملاً، فتتجمّع القطرات وينفصل الدهن عن الماء. والشوكولاتة إذا انحرقت (الداكنة فوق 50°م تقريباً، والحليب والبيضاء فوق 45°م) تثخن وتطلع دهنها.","en":"Above about 40 °C the fat is fully liquid, so droplets merge and the fat separates from the water. Overheated chocolate (dark above about 50 °C, milk and white above about 45 °C) also thickens and releases fat."},"answers":{"temp":{"hot":3,"ok":-1,"cold":-1},"when":{"mix":1}},"fixes":[{"type":"process","evidence":"consensus","src":["S4"],"ar":"اسكب الكريمة الحارة على الشوكولاتة على دفعات، وكمّل الخلط النهائي والخليط بين 32 و35°م تقريباً.","en":"Pour the hot cream onto the chocolate in stages and finish emulsifying with the mix at about 32–35 °C.","tradeoff":{"ar":"تحتاج ميزان حرارة ووقت انتظار.","en":"Needs a thermometer and some waiting."}}],"verify":{"ar":"قِس الحرارة قبل الخلط النهائي. إذا طلع لامع ومرن عند 32 إلى 35°م، فالسبب كان الحرارة.","en":"Measure before the final mix. If it turns glossy and elastic at 32–35 °C, heat was the cause."}},{"id":"too-cold","kind":"process","prior":0,"evidence":"consensus","src":["S4"],"title":{"ar":"الحرارة منخفضة وقت الخلط","en":"Too cold while mixing"},"why":{"ar":"تحت 30°م تقريباً تبدأ زبدة الكاكاو تتبلور وأنت تخلط، فيصير الغاناش محبباً وقاسياً وما يتجانس.","en":"Below about 30 °C cocoa butter starts to crystallise while you mix, so the ganache turns grainy and stiff and will not come together."},"answers":{"temp":{"cold":3,"hot":-2},"when":{"set":1}},"fixes":[{"type":"process","evidence":"consensus","src":["S4"],"ar":"سخّنه بهدوء إلى 33–35°م (حمام مائي أو مايكرويف على دفعات قصيرة)، ثم اخلطه بالبلندر.","en":"Warm it gently to 33–35 °C (water bath or short microwave bursts), then blend.","tradeoff":{"ar":"التسخين الزايد يرجّعك للسبب الأول، فقِس الحرارة.","en":"Overheating brings back the first cause, so measure."}}],"verify":{"ar":"إذا رجع لامعاً بعد التسخين إلى 33–35°م والخلط، فالسبب كان البرودة.","en":"If it turns glossy after warming to 33–35 °C and blending, cold was the cause."}},{"id":"water-low","kind":"formula","prior":0,"evidence":"established","src":["S4"],"title":{"ar":"الماء قليل مقابل الدهون في الوصفة","en":"Too little water for the fat in the recipe"},"why":{"ar":"الغاناش مستحلب: قطرات دهن محمولة في الماء. إذا الماء قليل (أو الزبدة زايدة)، ما يقدر يحمل كل الدهن فيطلع الزيت.","en":"Ganache is an emulsion: fat droplets carried in water. With too little water (or extra butter) there is not enough to carry all the fat, so oil comes out."},"rule":{"feat":"water","when":"below","range":{"default":[14,38],"gb":[14,22],"gt":[22,38],"gw":[35,52]},"evidence":"estimate","src":["S4"],"note":{"ar":"نطاقات الماء لكل نوع غاناش من محرك التوازن في المنصة، وهي تقدير عمل يحتاج اعتماد مراجع.","en":"Water ranges per ganache type come from the platform's balance engine; working estimates pending review."}},"answers":{"when":{"mix":1,"days":1}},"fixes":[{"type":"recipe","evidence":"estimate","src":["S4"],"ar":"زد الكريمة حتى يصير الماء فوق الحد الأدنى لنوع منتجك.","en":"Increase the cream until the water is above the minimum for your product type.","op":{"op":"reach","role":"cream","feat":"water","target":{"rel":"lo","add":1}},"tradeoff":{"ar":"ماء أكثر يرفع نشاط الماء ويقصّر الصلاحية. إذا تبي صلاحية طويلة، عوّض بسكر محوّل.","en":"More water raises water activity and shortens shelf life. For a long shelf life, compensate with invert sugar."}}],"verify":{"ar":"اعمل دفعة صغيرة بالكمية الجديدة: إذا بقيت لامعة بعد التبلور بدون ما تحرّك الحرارة، فالسبب كان الماء.","en":"Make a small batch with the new amount. If it stays glossy after setting with no change in temperature, water was the cause."}},{"id":"fat-high","kind":"formula","prior":0,"evidence":"established","src":["S4"],"title":{"ar":"الدهون عالية في الوصفة","en":"Fat is too high in the recipe"},"why":{"ar":"كل ما زادت الدهون، صار المستحلب أقرب للانقلاب، خصوصاً مع زبدة مضافة أو براليني.","en":"The more fat, the closer the emulsion is to breaking, especially with added butter or praline."},"rule":{"feat":"fat","when":"above","range":{"default":[25,40],"gb":[30,40],"gt":[25,40],"gw":[25,38]},"evidence":"estimate","src":["S4"],"note":{"ar":"نطاقات الدهون لكل نوع غاناش من محرك التوازن في المنصة، وهي تقدير عمل يحتاج اعتماد مراجع.","en":"Fat ranges per ganache type come from the platform's balance engine; working estimates pending review."}},"answers":{"when":{"mix":1}},"fixes":[{"type":"recipe","evidence":"estimate","src":["S4"],"ar":"زد الكريمة حتى تنزل الدهون تحت الحد الأعلى لنوع منتجك. تقليل الزبدة وحده نادراً يكفي لأن أغلب الدهن من الشوكولاتة.","en":"Increase the cream until the fat is below the maximum for your product type. Cutting butter alone rarely works, as most of the fat comes from the chocolate.","op":{"op":"reach","role":"cream","feat":"fat","target":{"rel":"hi","add":-1}},"tradeoff":{"ar":"الكريمة تزيد الماء، فيرتفع نشاط الماء وتقصر الصلاحية. عوّض بسكر محوّل إذا تبي صلاحية طويلة.","en":"Cream adds water, raising water activity and shortening shelf life. Compensate with invert sugar for a long shelf life."}}],"verify":{"ar":"قارن الدفعتين بعد 24 ساعة: سطح بدون زيت ومقطع لامع يؤكد السبب.","en":"Compare both batches after 24 hours. No oil on the surface and a glossy cut confirm it."}},{"id":"mixing-method","kind":"process","prior":0,"evidence":"consensus","src":["S4"],"title":{"ar":"طريقة الخلط","en":"Mixing method"},"why":{"ar":"المضرب اليدوي يدخل هواء ويعطي قصّاً ضعيفاً. البلندر ورأسه تحت السطح يعطي قطرات دقيقة ومستحلب أثبت.","en":"A whisk adds air and gives weak shear. A stick blender with its head below the surface makes fine droplets and a more stable emulsion."},"answers":{"tool":{"whisk":2,"spatula":1,"blender":-2}},"fixes":[{"type":"process","evidence":"consensus","src":["S4"],"ar":"استعمل بلندر يدوي ورأسه مغمور كاملاً، وميّل الوعاء عشان ما يدخل هواء.","en":"Use a stick blender with the head fully submerged and tilt the container so no air gets in.","tradeoff":{"ar":"لو طلع الرأس من السطح يدخل فقاعات.","en":"If the head breaks the surface it adds bubbles."}}],"verify":{"ar":"مرّر قطرة على ظهر الملعقة: سطح لامع بدون قطرات زيت.","en":"Draw a drop across the back of a spoon: a glossy surface with no oil beads."}},{"id":"storage-heat","kind":"process","prior":0,"evidence":"consensus","src":["S5"],"title":{"ar":"حرارة التخزين أو النقل","en":"Storage or transport heat"},"why":{"ar":"فوق 28°م تقريباً يلين دهن الحليب وزبدة الكاكاو، فيتحرك الدهن ويطلع على السطح، خصوصاً مع تكرار التسخين والتبريد. هذا شائع في صيف الخليج.","en":"Above about 28 °C milk fat and cocoa butter soften, so fat migrates to the surface, especially with repeated warming and cooling. This is common in Gulf summers."},"answers":{"when":{"days":3,"mix":-2}},"fixes":[{"type":"process","evidence":"consensus","src":["S5"],"ar":"خزّن بين 15 و18°م ورطوبة 50 إلى 60%، ولا تنقل المنتج فوق 25°م.","en":"Store at 15–18 °C and 50–60% humidity, and do not transport the product above 25 °C.","tradeoff":{"ar":"تكلفة تبريد ونقل مبرّد.","en":"Cost of cooling and chilled transport."}}],"verify":{"ar":"خزّن عيّنتين أسبوعاً، وحدة على 16°م ووحدة على 28°م وقارن.","en":"Store two samples for a week, one at 16 °C and one at 28 °C, and compare."}}],"rescue":{"ar":["أرجع حرارته إلى 33–35°م.","أضف 5 إلى 10% من وزنه سائلاً دافئاً (كريمة أو حليب).","اخلطه بالبلندر من الوسط حتى يرجع لامعاً."],"en":["Bring it back to 33–35 °C.","Add 5–10% of its weight in warm liquid (cream or milk).","Blend from the centre with a stick blender until glossy."]},"prevent":{"ar":["قِس الحرارة قبل الخلط النهائي.","استعمل بلندر يدوي ورأسه مغمور.","أضف الزبدة بعد ما يتكوّن المستحلب والخليط تحت 35°م.","تأكد إن الماء والدهون ضمن نطاق نوع منتجك."],"en":["Measure the temperature before the final mix.","Use a stick blender, head submerged.","Add butter after the emulsion forms, below 35 °C.","Keep water and fat within your product type's range."]},"notFormula":{"ar":"إذا الماء والدهون ضمن نطاق نوع منتجك، فالسبب غالباً الحرارة أو طريقة الخلط أو التخزين.","en":"If water and fat are within your product type's range, the cause is most likely temperature, mixing or storage."},"unsure":{"ar":"ما أقدر أحدد السبب بثقة. قِس الحرارة في المرة الجاية وجاوب الأسئلة.","en":"I cannot tell the cause with confidence. Measure the temperature next time and answer the questions."}},{"id":"cake-sink","category":"cake","status":"draft","reviewedBy":null,"severity":"medium","rescuable":true,"symptom":{"ar":"الكيك هبط في النصف","en":"The cake sank in the middle","syn":{"ar":["الكيك هبط","الكيكة نزلت من النص","الكيك فيه حفرة","الكيك ارتفع ونزل","الكيك نصه عجين"],"en":["cake sank","cake collapsed in the middle","cake dips in the centre","cake rose then fell"]}},"see":{"ar":"الوسط أوطى من الأطراف، وأحياناً تحته طبقة كثيفة أو عجينية.","en":"The centre is lower than the edges, sometimes with a dense or gummy layer under it."},"questions":[{"id":"when","ar":"متى هبط؟","en":"When did it sink?","options":[{"id":"oven","ar":"داخل الفرن","en":"In the oven"},{"id":"out","ar":"أول ما طلع من الفرن","en":"Right after it came out"},{"id":"cool","ar":"أثناء التبريد","en":"While cooling"}]},{"id":"door","ar":"فتحت الفرن قبل ما يمر ثلثا وقت الخبز؟","en":"Did you open the oven before two thirds of the bake?","options":[{"id":"yes","ar":"نعم","en":"Yes"},{"id":"no","ar":"لا","en":"No"}]},{"id":"crumb","ar":"كيف الوسط من الداخل؟","en":"How is the centre inside?","options":[{"id":"wet","ar":"رطب أو عجيني","en":"Wet or gummy"},{"id":"ok","ar":"مخبوز طبيعي","en":"Baked through"}]}],"causes":[{"id":"over-leavened","kind":"formula","prior":0,"evidence":"established","src":["S1","S3"],"title":{"ar":"البيكنج باودر زايد","en":"Too much baking powder"},"why":{"ar":"الرافع الزايد ينفخ الفقاعات أسرع مما يتماسك الخليط، فتكبر وتندمج ثم تنهار قبل ما يثبت الهيكل.","en":"Excess leavening inflates the cells faster than the batter can set; they grow, merge and collapse before the structure is fixed."},"rule":{"feat":"bpFlour","when":"above","range":{"default":[3,5]},"evidence":"consensus","src":["S1"]},"answers":{"when":{"oven":2,"out":1},"crumb":{"ok":1}},"fixes":[{"type":"recipe","evidence":"consensus","src":["S1"],"ar":"اضبط البيكنج باودر على 4% من وزن الدقيق.","en":"Set the baking powder to 4% of the flour weight.","op":{"op":"ratio","role":"bp","base":"flour","target":0.04},"tradeoff":{"ar":"حجم أقل قليلاً وقوام أكثف. قد تحتاج تهوية أكثر بالخفق.","en":"Slightly less volume and a denser crumb; you may need more aeration from mixing."}}],"verify":{"ar":"راقب من شباك الفرن: يرتفع بانتظام ويثبت بدون قمة ثم هبوط.","en":"Watch through the oven glass: it rises evenly and holds, with no peak then drop."}},{"id":"sugar-high","kind":"formula","prior":0,"evidence":"established","src":["S1","S3"],"title":{"ar":"السكر عالي مقابل الدقيق","en":"Sugar too high for the flour"},"why":{"ar":"السكر يؤخر انتفاخ النشا وتجمّد البيض، فيتماسك الهيكل متأخراً. إذا زاد كثير يتماسك بعد ما يطلع الغاز.","en":"Sugar delays starch swelling and egg setting, so the structure sets later. Too much and it sets after the gas has escaped."},"rule":{"feat":"sugarFlour","when":"above","range":{"default":[0.8,1.25]},"evidence":"consensus","src":["S1","S3"],"note":{"ar":"فوق 1.25 تقريباً تحتاج الوصفة دقيقاً معالجاً لكيك السكر العالي، وهو غير متوفر غالباً في الخليج.","en":"Above about 1.25 a recipe needs treated high-ratio cake flour, often unavailable in the Gulf."}},"answers":{"crumb":{"wet":1},"when":{"out":1}},"fixes":[{"type":"recipe","evidence":"consensus","src":["S1"],"ar":"قلّل السكر إلى 1.1 من وزن الدقيق.","en":"Reduce the sugar to 1.1 times the flour weight.","op":{"op":"ratio","role":["sugar","invert"],"base":"flour","target":1.1},"tradeoff":{"ar":"أقل حلاوة وطراوة، يجف أسرع ويتلوّن أقل.","en":"Less sweet and tender; stales faster and browns less."}}],"verify":{"ar":"اخبز الوصفة المعدّلة بنفس الفرن والوقت: وسط مستوٍ ومخبوز يؤكد السبب.","en":"Bake the adjusted recipe in the same oven and time. A level, baked centre confirms it."}},{"id":"liquid-high","kind":"formula","prior":0,"evidence":"established","src":["S1"],"title":{"ar":"السوائل زايدة مقابل الدقيق","en":"Too much liquid for the flour"},"why":{"ar":"السائل الزايد يخفف الهيكل، فيبقى الوسط رطباً وينزل.","en":"Excess liquid dilutes the structure, so the centre stays wet and drops."},"rule":{"feat":"waterFlour","when":"above","range":{"default":[0.8,1.4]},"evidence":"estimate","src":["S1"],"note":{"ar":"نسبة الماء الكلي (من كل المكونات) للدقيق في الكيك بالزبدة: نطاق تقديري يحتاج اعتماد.","en":"Total water (from all ingredients) to flour in butter cakes: a working range pending review."}},"answers":{"crumb":{"wet":2,"ok":-1}},"fixes":[{"type":"recipe","evidence":"estimate","src":["S1"],"ar":"قلّل الحليب أو الماء حتى تنزل النسبة إلى 1.3.","en":"Reduce the milk or water until the ratio is 1.3.","op":{"op":"reach","role":["milk","water"],"feat":"waterFlour","target":1.3},"tradeoff":{"ar":"إذا قللت كثير يصير الكيك ناشفاً.","en":"Reduce too much and the cake turns dry."}}],"verify":{"ar":"اغرز ميزان حرارة في الوسط: لازم يوصل 95°م تقريباً في نفس الوقت اللي كان يطلع فيه.","en":"Probe the centre: it should reach about 95 °C in the same bake time as before."}},{"id":"underbaked","kind":"process","prior":1,"evidence":"established","src":["S1"],"title":{"ar":"ما انخبز كفاية أو حرارة الفرن أقل","en":"Underbaked, or the oven runs cool"},"why":{"ar":"الهيكل يثبت لما يتجمد البيض وينتفخ النشا في الوسط. إذا طلع قبل كذا، أو الفرن أبرد من المضبوط، ينزل الوسط.","en":"The structure sets when egg coagulates and starch swells in the centre. Out too early, or with an oven cooler than its dial, the centre falls."},"answers":{"crumb":{"wet":3,"ok":-2},"when":{"out":2,"cool":1}},"fixes":[{"type":"process","evidence":"consensus","src":["S1"],"ar":"تأكد من حرارة الفرن بميزان مستقل، واخبز حتى يطلع العود نظيفاً من الوسط وتوصل حرارته 95 إلى 98°م تقريباً.","en":"Check the oven with an independent thermometer, and bake until a skewer comes out clean and the centre reaches about 95–98 °C.","tradeoff":{"ar":"الأطراف تنشف قليلاً.","en":"Edges dry slightly."}}],"verify":{"ar":"قِس حرارة الوسط عند الإخراج وسجّلها مع الوقت للدفعات الجاية.","en":"Record the centre temperature at removal, with the time, for future batches."}},{"id":"door-opened","kind":"process","prior":0,"evidence":"consensus","src":["S1"],"title":{"ar":"فتح الفرن بدري","en":"The oven was opened early"},"why":{"ar":"فتح الباب يدخل هواء بارد ويوقف التمدد قبل ما يثبت الهيكل، فينزل الوسط.","en":"Opening the door lets in cool air and stops expansion before the structure sets, so the centre drops."},"answers":{"door":{"yes":3,"no":-2},"when":{"oven":2}},"fixes":[{"type":"process","evidence":"consensus","src":["S1"],"ar":"لا تفتح الفرن قبل ما يمر ثلثا وقت الخبز، وراقب من الزجاج.","en":"Do not open the oven before two thirds of the bake; watch through the glass.","tradeoff":{"ar":"ما تقدر تلف الصينية بدري للتلوين المتساوي.","en":"You cannot rotate the tray early for even colour."}}],"verify":{"ar":"اخبز نفس الوصفة بدون فتح الباب: إذا ثبت الوسط، فهذا هو السبب.","en":"Bake the same recipe without opening the door. If the centre holds, that was the cause."}}],"rescue":{"ar":["إذا الوسط مخبوز: قصّ الجزء الهابط واستعمل الباقي قاعدة أو فتات (ترافل، كيك بوبس).","إذا الوسط عجيني: لا تقدّمه."],"en":["If the centre is baked, trim the sunken part and use the rest as a base or crumbs (trifle, cake pops).","If the centre is gummy, do not serve it."]},"prevent":{"ar":["البيكنج باودر 3 إلى 5% من الدقيق.","السكر لا يزيد كثيراً عن وزن الدقيق.","ميزان حرارة مستقل للفرن.","لا تفتح الفرن قبل ثلثي الوقت."],"en":["Baking powder 3–5% of the flour.","Sugar not much above the flour weight.","An independent oven thermometer.","Do not open the oven before two thirds of the time."]},"notFormula":{"ar":"إذا البيكنج باودر 3 إلى 5% من الدقيق، والسكر لا يزيد عن وزن الدقيق كثيراً، فالسبب غالباً الفرن أو وقت الخبز.","en":"If baking powder is 3–5% of the flour and sugar is not far above the flour weight, the cause is most likely the oven or the bake time."},"unsure":{"ar":"الأرقام ضمن المعتاد. جاوب الأسئلة، وتأكد من حرارة الفرن بميزان مستقل.","en":"The numbers are in the usual range. Answer the questions and check the oven with an independent thermometer."}},{"id":"tart-shell","category":"dough","status":"draft","reviewedBy":null,"severity":"low","rescuable":true,"symptom":{"ar":"قاعدة التارت انكمشت أو صارت طرية","en":"Tart shell shrank or the base went soggy","syn":{"ar":["التارت انكمش","العجينة نزلت على الجوانب","قاعدة التارت طرية","التارت مو مقرمش","التارت عجنته رطبة"],"en":["tart shrinks","tart shell slides down","soggy tart base","tart not crisp"]}},"see":{"ar":"الجوانب نزلت أو قصرت عن حافة القالب، أو القاعدة لينة وما تنكسر بصوت.","en":"The sides slid down or fall short of the ring, or the base is soft and does not snap."},"questions":[{"id":"sym","ar":"وش المشكلة بالضبط؟","en":"What exactly is the problem?","options":[{"id":"shrink","ar":"انكمشت ونزلت على الجوانب","en":"It shrank down the sides"},{"id":"soggy","ar":"القاعدة طرية","en":"The base is soggy"},{"id":"both","ar":"الاثنين","en":"Both"}]},{"id":"rest","ar":"رتّحت العجينة في الثلاجة قبل التبطين وبعده؟","en":"Did you rest the dough chilled before and after lining?","options":[{"id":"yes","ar":"نعم، 30 دقيقة أو أكثر كل مرة","en":"Yes, 30 minutes or more each time"},{"id":"no","ar":"أقل، أو لا","en":"Less, or no"}]},{"id":"blind","ar":"خبزت القاعدة لحالها قبل الحشوة؟","en":"Did you blind-bake the base before filling?","options":[{"id":"golden","ar":"نعم، حتى صارت ذهبية","en":"Yes, until golden"},{"id":"pale","ar":"نعم، بس كانت فاتحة","en":"Yes, but it was pale"},{"id":"no","ar":"لا","en":"No"}]}],"causes":[{"id":"gluten-rest","kind":"process","sym":["shrink","both"],"prior":1,"evidence":"established","src":["S1","S3"],"title":{"ar":"الغلوتين مشدود: عجن زايد أو بدون راحة","en":"Tight gluten: overworked or not rested"},"why":{"ar":"العجن والسائل يكوّنان غلوتين. لما تشد العجينة يرجع الغلوتين يتقلص في الفرن، والراحة في البرد ترخيه.","en":"Working and liquid develop gluten. Stretched gluten springs back in the oven; chilled resting relaxes it."},"answers":{"rest":{"no":3,"yes":-1}},"fixes":[{"type":"process","evidence":"consensus","src":["S1"],"ar":"اخلط لين تتجمع العجينة بس، ورتّحها 30 دقيقة على الأقل في الثلاجة بعد الخلط وبعد التبطين. ادفع العجينة في الزوايا ولا تشدّها.","en":"Mix only until it comes together, and rest it at least 30 minutes chilled after mixing and after lining. Push the dough into the corners; do not stretch it.","tradeoff":{"ar":"يزيد وقت الإنتاج.","en":"Longer production time."}}],"verify":{"ar":"علّم مستوى الحافة قبل الخبز وقِس النزول بعده، وسجّله لكل دفعة.","en":"Mark the edge height before baking, measure the drop after, and log it for each batch."}},{"id":"liquid-high","kind":"formula","sym":["shrink","both"],"prior":0,"evidence":"established","src":["S1"],"title":{"ar":"الماء عالي مقابل الدقيق","en":"Too much water for the flour"},"why":{"ar":"كل ما زاد الماء في العجينة (من البيض والزبدة والماء)، تكوّن غلوتين أكثر وزاد الانكماش.","en":"The more water in the dough (from egg, butter and water), the more gluten forms and the more it shrinks."},"rule":{"feat":"waterFlour","when":"above","range":{"default":[0.18,0.3]},"evidence":"estimate","src":["S1"],"note":{"ar":"محسوب من وصفات عجينة سكرية وعجينة قصيرة شائعة. نطاق تقديري يحتاج اعتماد.","en":"Derived from common sweet and short pastry formulas; a working range pending review."}},"answers":{"rest":{"yes":1}},"fixes":[{"type":"recipe","evidence":"estimate","src":["S1"],"ar":"قلّل الماء أو البيض حتى تنزل النسبة إلى 0.26.","en":"Reduce the water or egg until the ratio is 0.26.","op":{"op":"reach","role":["water","egg","milk"],"feat":"waterFlour","target":0.26},"tradeoff":{"ar":"عجينة أصعب في الفرد وتتشقق. إذا احتجت رطوبة، استعمل صفار بدل البياض.","en":"Harder to roll and may crack. If you need moisture, use yolk instead of white."}}],"verify":{"ar":"قارن نزول الحافة بين الوصفتين بنفس الراحة والفرن.","en":"Compare the edge drop of both recipes with the same rest and oven."}},{"id":"fat-low","kind":"formula","sym":["shrink","both"],"prior":0,"evidence":"established","src":["S1"],"title":{"ar":"الزبدة قليلة مقابل الدقيق","en":"Too little fat for the flour"},"why":{"ar":"الدهن يغلّف الدقيق ويقصّر خيوط الغلوتين. إذا قلّ، تصير العجينة مطاطية أكثر وتنكمش.","en":"Fat coats the flour and shortens gluten strands. With too little, the dough is more elastic and shrinks."},"rule":{"feat":"fatFlour","when":"below","range":{"default":[0.35,0.6]},"evidence":"estimate","src":["S1"],"note":{"ar":"محسوب من وصفات عجينة سكرية وقصيرة شائعة (الزبدة 40 إلى 60% من الدقيق). نطاق تقديري.","en":"Derived from common sweet and short pastry formulas (butter 40–60% of flour); a working range."}},"answers":{},"fixes":[{"type":"recipe","evidence":"estimate","src":["S1"],"ar":"زد الزبدة حتى تصير الدهون 0.4 من وزن الدقيق.","en":"Increase the butter until the fat is 0.4 times the flour weight.","op":{"op":"reach","role":"butter","feat":"fatFlour","target":0.4},"tradeoff":{"ar":"أهش وأطرى، وأصعب في التشكيل في الجو الحار.","en":"Shorter and more tender, but harder to handle in hot weather."}}],"verify":{"ar":"إذا قلّ الانكماش بنفس الراحة، فالسبب كان الدهن.","en":"If shrinkage drops with the same rest, fat was the cause."}},{"id":"strong-flour","kind":"formula","sym":["shrink","both"],"prior":0,"evidence":"established","src":["S1","S7"],"title":{"ar":"الدقيق قوي (بروتين عالي)","en":"Strong flour (high protein)"},"why":{"ar":"الدقيق العالي البروتين يكوّن غلوتين أكثر. بعض الدقيق المحلي متعدد الاستعمال أقوى من دقيق المعجنات.","en":"High-protein flour forms more gluten. Some local all-purpose flours are stronger than pastry flour."},"rule":{"feat":"flourProtein","when":"above","range":{"default":[8,11]},"evidence":"estimate","src":["S1"],"note":{"ar":"يعتمد على نسبة البروتين المسجلة لمادة الدقيق. دقيق المعجنات عادة أقل من دقيق الخبز؛ تأكد من مورّدك.","en":"Relies on the protein recorded for the flour material. Pastry flour is usually lower than bread flour; confirm with your supplier."}},"answers":{},"fixes":[{"type":"recipe","evidence":"consensus","src":["S1"],"ar":"بدّل 15% من الدقيق بنشا ذرة لتخفيف الغلوتين.","en":"Replace 15% of the flour with cornstarch to weaken the gluten.","op":{"op":"swap","from":"flour","to":"starch","frac":0.15,"factor":1,"name":{"ar":"نشا ذرة","en":"Cornstarch"},"comp":{"w":0.12}},"tradeoff":{"ar":"أهش وأقل تماسكاً عند التشكيل.","en":"More crumbly and less cohesive when shaping."}}],"verify":{"ar":"اسأل المورّد عن نسبة بروتين الدقيق وسجّلها في مادة الدقيق بالمنصة.","en":"Ask your supplier for the flour protein and record it on the flour material in the platform."}},{"id":"underbaked-base","kind":"process","sym":["soggy","both"],"prior":1,"evidence":"consensus","src":["S1","S3"],"title":{"ar":"القاعدة ما انخبزت كفاية","en":"The base was underbaked"},"why":{"ar":"القاعدة الفاتحة ما زال فيها ماء، فتمتص رطوبة الحشوة بسرعة.","en":"A pale base still holds water, so it soaks up moisture from the filling quickly."},"answers":{"blind":{"no":3,"pale":2,"golden":-2}},"fixes":[{"type":"process","evidence":"consensus","src":["S1"],"ar":"اخبزها خبزاً أعمى على 160 إلى 170°م حتى تتلون القاعدة ذهبي متساوي، ثم شيل الأوزان وكمّل دقائق.","en":"Blind-bake at 160–170 °C until the base is evenly golden, then remove the weights and bake a few minutes more.","tradeoff":{"ar":"الحواف قد تغمق.","en":"Edges may darken."}}],"verify":{"ar":"اقلب الحلقة: القاعدة ذهبية متساوية وتنكسر بصوت.","en":"Turn the shell over: the base is evenly golden and snaps."}},{"id":"wet-filling","kind":"process","sym":["soggy","both"],"prior":0,"evidence":"established","src":["S3"],"title":{"ar":"الحشوة رطبة وما في طبقة عازلة","en":"Wet filling with no barrier"},"why":{"ar":"الماء ينتقل من الحشوة الرطبة للعجينة الناشفة لين يتعادل نشاط الماء بينهم.","en":"Water moves from a wet filling into dry pastry until their water activity evens out."},"answers":{"blind":{"golden":1}},"fixes":[{"type":"process","evidence":"consensus","src":["S3"],"ar":"اعزل القاعدة بطبقة رقيقة من زبدة الكاكاو أو الشوكولاتة، أو بصفار وارجعها للفرن دقيقة أو دقيقتين. واحشُها قريب من وقت التقديم.","en":"Seal the base with a thin layer of cocoa butter or chocolate, or with egg yolk baked for 1–2 minutes. Fill close to serving.","tradeoff":{"ar":"طبقة الشوكولاتة تغيّر الطعم قليلاً وتزيد التكلفة.","en":"A chocolate layer changes the taste slightly and adds cost."}}],"verify":{"ar":"قارن تارتين بعد 6 ساعات: واحد بطبقة عازلة وواحد بدون.","en":"Compare two tarts after 6 hours, one sealed and one not."}}],"rescue":{"ar":["القواعد الفاضية الطرية: ارجعها للفرن 5 دقائق على 160°م لتجف.","المنكمشة: استعملها لتارتلت أصغر أو قطّعها فتات للقواعد.","المحشية الطرية ما تنقذ."],"en":["Soft empty shells: return to a 160 °C oven for 5 minutes to dry.","Shrunken shells: use for smaller tartlets or crumble into bases.","A filled soggy tart cannot be rescued."]},"prevent":{"ar":["اخلط لين تتجمع العجينة بس.","راحة 30 دقيقة باردة بعد الخلط وبعد التبطين.","خبز أعمى حتى الذهبي.","طبقة عازلة للحشوات الرطبة.","خزّن القواعد في علب محكمة، خصوصاً مع رطوبة الخليج."],"en":["Mix only until it comes together.","Rest 30 minutes chilled after mixing and after lining.","Blind-bake until golden.","Seal before wet fillings.","Store shells airtight, especially in Gulf humidity."]},"notFormula":{"ar":"إذا الماء 0.18 إلى 0.3 من وزن الدقيق والزبدة كافية، فالانكماش غالباً من العجن أو الراحة، والطراوة من الخبز أو الحشوة.","en":"If water is 0.18–0.3 of the flour weight and there is enough butter, shrinking most likely comes from working or resting, and sogginess from baking or the filling."},"unsure":{"ar":"حدد المشكلة (انكماش أو طراوة) وجاوب الأسئلة.","en":"Choose the problem (shrinking or soggy) and answer the questions."}},{"id":"choux-collapse","category":"choux","status":"draft","reviewedBy":null,"severity":"medium","rescuable":true,"symptom":{"ar":"الشو هبط بعد الخبز","en":"Choux collapsed after baking","syn":{"ar":["الشو هبط","الإكلير نزل","الشو ما انتفخ","الشو فاضي ونزل","البروفيترول هبط"],"en":["choux collapsed","eclairs deflated","choux went flat","profiteroles sank"]}},"see":{"ar":"القطع تنفخ في الفرن ثم تنكمش وتتجعد، وأحياناً الداخل رطب.","en":"The pieces puff in the oven, then shrink and wrinkle, sometimes with a wet inside."},"questions":[{"id":"when","ar":"متى هبط؟","en":"When did it collapse?","options":[{"id":"oven","ar":"داخل الفرن قبل ما يتلون","en":"In the oven before colouring"},{"id":"out","ar":"أول ما طلع من الفرن","en":"Right after coming out"},{"id":"cool","ar":"بعد دقائق من التبريد","en":"A few minutes after cooling"}]},{"id":"inside","ar":"كيف الداخل؟","en":"How is the inside?","options":[{"id":"wet","ar":"رطب وعجيني","en":"Wet and doughy"},{"id":"dry","ar":"جاف ومجوّف","en":"Dry and hollow"}]},{"id":"paste","ar":"قوام العجينة قبل التشكيل؟","en":"Paste consistency before piping?","options":[{"id":"v","ar":"تنزل من الملعقة على شكل V وتمسك","en":"Falls from the spatula in a V and holds"},{"id":"runny","ar":"سائلة وتنتشر","en":"Runny and spreads"},{"id":"stiff","ar":"ناشفة وثقيلة","en":"Dry and heavy"}]}],"causes":[{"id":"underbaked-shell","kind":"process","prior":1,"evidence":"established","src":["S1","S2"],"title":{"ar":"القشرة ما ثبتت: خبز ناقص","en":"The shell did not set: underbaked"},"why":{"ar":"البخار ينفخ الشو، بس القشرة لازم تنشف وتثبت قبل ما يقل الضغط. إذا طلع بدري، ينهار.","en":"Steam puffs the choux, but the shell must dry and set before the pressure drops. Out too early, it collapses."},"answers":{"inside":{"wet":3,"dry":-2},"when":{"out":2,"cool":2}},"fixes":[{"type":"process","evidence":"consensus","src":["S1"],"ar":"اخبز حتى يصير لونه ذهبي غامق ويحس ناشف، وكمّل آخر 10 دقائق على 150 إلى 160°م مع فتحة تهوية.","en":"Bake until deep golden and dry to the touch, and finish the last 10 minutes at 150–160 °C with the vent open.","tradeoff":{"ar":"لون أغمق وقشرة أسمك.","en":"Darker colour and a thicker shell."}}],"verify":{"ar":"شقّ قطعة: الداخل جاف. وقارن وزن 10 قطع قبل الخبز وبعده وسجّل الفاقد لتثبّته.","en":"Cut one open: the inside is dry. Weigh 10 pieces before and after baking and log the loss to keep it consistent."}},{"id":"paste-wet","kind":"formula","prior":0,"evidence":"established","src":["S1"],"title":{"ar":"العجينة رطبة: البيض زايد","en":"Paste too wet: too much egg"},"why":{"ar":"البيض الزايد يخلي العجينة تسيل، فتطلع الجدران رقيقة وما تمسك.","en":"Too much egg makes the paste runny, so the walls are thin and cannot hold."},"rule":{"feat":"eggFlour","when":"above","range":{"default":[1.5,2]},"evidence":"consensus","src":["S1"]},"answers":{"paste":{"runny":3,"v":-1,"stiff":-2}},"fixes":[{"type":"recipe","evidence":"consensus","src":["S1"],"ar":"اضبط البيض على 1.8 من وزن الدقيق، وأضفه بالتدريج وتوقف أول ما توصل لشكل V.","en":"Set the egg at 1.8 times the flour weight; add it gradually and stop as soon as it forms a V.","op":{"op":"ratio","role":["egg"],"base":"flour","target":1.8},"tradeoff":{"ar":"إذا قللت أكثر من اللازم تطلع العجينة ثقيلة وتنتفخ أقل وتتشقق.","en":"Cut too far and the paste is heavy, puffs less and cracks."}}],"verify":{"ar":"اختبار الملعقة: العجينة تنزل على شكل V وتمسك. والقطع تحتفظ بشكلها بعد الخبز.","en":"Spatula test: the paste falls in a V and holds, and the pieces keep their shape after baking."}},{"id":"panade-wet","kind":"process","prior":0,"evidence":"consensus","src":["S1"],"title":{"ar":"العجينة ما جفّت كفاية على النار","en":"The paste was not dried enough on the heat"},"why":{"ar":"طبخ العجينة (الباناد) يبخّر ماء ويطبخ النشا عشان تمتص البيض. إذا ما جفّت، تبقى رطبة حتى بنفس كمية البيض.","en":"Cooking the paste (panade) evaporates water and cooks the starch so it absorbs the egg. Under-dried, it stays wet even with the same egg."},"answers":{"paste":{"runny":2}},"fixes":[{"type":"process","evidence":"consensus","src":["S1"],"ar":"حرّك العجينة على النار دقيقة إلى دقيقتين بعد ما تتجمع، لين تتكوّن طبقة رقيقة على قاع القدر.","en":"Stir the paste on the heat one to two minutes after it comes together, until a thin film forms on the pan base.","tradeoff":{"ar":"إذا زاد التجفيف تطلع الدهون وتصير العجينة لامعة دهنية.","en":"Overdrying releases fat and makes the paste greasy."}}],"verify":{"ar":"زِن العجينة قبل التجفيف وبعده: لازم تنقص بوضوح، وسجّل الفرق.","en":"Weigh the paste before and after drying; it should lose clearly. Log the difference."}},{"id":"oven-door-temp","kind":"process","prior":0,"evidence":"consensus","src":["S1"],"title":{"ar":"فتح الفرن بدري أو حرارته قليلة","en":"Oven opened early or too cool"},"why":{"ar":"الشو يعتمد على البخار. فتح الباب بدري أو فرن بارد يعني ضغط بخار أقل قبل ما تثبت القشرة.","en":"Choux relies on steam. Opening the door early or a cool oven means less steam pressure before the shell sets."},"answers":{"when":{"oven":3}},"fixes":[{"type":"process","evidence":"consensus","src":["S1"],"ar":"لا تفتح الفرن أول 20 دقيقة، وتأكد من حرارته بميزان مستقل.","en":"Do not open the oven in the first 20 minutes, and check it with an independent thermometer.","tradeoff":{"ar":"ما تقدر تلف الصينية بدري.","en":"You cannot rotate the tray early."}}],"verify":{"ar":"سجّل حرارة الفرن الفعلية ووقت أول فتح لكل دفعة.","en":"Log the actual oven temperature and the time of the first opening for each batch."}},{"id":"fat-high","kind":"formula","prior":0,"evidence":"established","src":["S1"],"title":{"ar":"الزبدة عالية مقابل الدقيق","en":"Too much butter for the flour"},"why":{"ar":"الدهن الزايد يضعف الهيكل، فتطلع قشرة طرية ما تمسك بعد الخبز.","en":"Excess fat weakens the structure, giving a soft shell that does not hold after baking."},"rule":{"feat":"fatFlour","when":"above","range":{"default":[0.45,0.9]},"evidence":"estimate","src":["S1"],"note":{"ar":"محسوب من وصفات شو كلاسيكية شائعة (يشمل دهن البيض). نطاق تقديري يحتاج اعتماد.","en":"Derived from common classic choux formulas (includes egg fat); a working range pending review."}},"answers":{},"fixes":[{"type":"recipe","evidence":"estimate","src":["S1"],"ar":"قلّل الزبدة حتى تصير الدهون 0.75 من وزن الدقيق.","en":"Reduce the butter until the fat is 0.75 times the flour weight.","op":{"op":"reach","role":"butter","feat":"fatFlour","target":0.75},"tradeoff":{"ar":"قشرة أنشف وطعم زبدة أقل.","en":"A drier shell and less butter flavour."}}],"verify":{"ar":"قارن صلابة القشرة بعد 15 دقيقة من الخروج.","en":"Compare shell firmness 15 minutes after baking."}}],"rescue":{"ar":["إذا هبط بعد الخروج والداخل رطب: ارجعه للفرن 10 دقائق على 150 إلى 160°م يجف.","الهابط تماماً: استعمله كقاعدة مقطّعة أو تزيين بعد التجفيف."],"en":["If it collapsed after baking with a wet inside, return it to a 150–160 °C oven for 10 minutes to dry.","Fully collapsed pieces can be dried and used as a crumbled base or decoration."]},"prevent":{"ar":["جفّف العجينة على النار حتى تتكوّن طبقة على القاع.","أضف البيض تدريجياً حتى شكل V.","لا تفتح الفرن أول 20 دقيقة.","اخبز حتى الذهبي الغامق وكمّل التجفيف."],"en":["Dry the paste on the heat until a film forms on the base.","Add egg gradually until it forms a V.","Do not open the oven in the first 20 minutes.","Bake to deep golden and finish drying."]},"notFormula":{"ar":"إذا البيض 1.5 إلى 2 من وزن الدقيق والعجينة تنزل على شكل V، فالسبب غالباً الخبز أو الفرن.","en":"If the egg is 1.5–2 times the flour weight and the paste falls in a V, the cause is most likely baking or the oven."},"unsure":{"ar":"جاوب الأسئلة: أهم معلومة هي هل الداخل رطب أو جاف.","en":"Answer the questions; the key one is whether the inside is wet or dry."}},{"id":"pastry-cream-thin","category":"custard","status":"draft","reviewedBy":null,"severity":"medium","rescuable":false,"symptom":{"ar":"الكريمة باتسيير ما ثخنت أو ارتخت بعد ساعات","en":"Pastry cream did not thicken or turned runny after hours","syn":{"ar":["الباتسيير سايل","الكريمة رجعت سايلة","الكاسترد ارتخى","الكريمة ما ثخنت","الكريمة طلعت ماي","الباتسيير ذاب في الثلاجة"],"en":["runny pastry cream","pastry cream thinned","custard turned liquid","pastry cream will not thicken"]}},"see":{"ar":"الكريمة ما تمسك شكلها، أو كانت ثخينة ورجعت سايلة بعد ساعات في الثلاجة، وأحياناً يطلع منها ماء.","en":"The cream does not hold its shape, or it was thick and turned runny after hours in the fridge, sometimes leaking water."},"questions":[{"id":"when","ar":"متى صارت سايلة؟","en":"When did it turn runny?","options":[{"id":"never","ar":"ما ثخنت أصلاً","en":"It never thickened"},{"id":"later","ar":"ثخنت ثم ارتخت بعد ساعات","en":"It thickened, then thinned after hours"},{"id":"added","ar":"بعد ما أضفت فاكهة أو عصير أو ليكير","en":"After adding fruit, juice or liqueur"}]},{"id":"boil","ar":"هل غلت وفقّعت دقيقة على الأقل بعد ما ثخنت؟","en":"Did it bubble for at least a minute after thickening?","options":[{"id":"yes","ar":"نعم","en":"Yes"},{"id":"no","ar":"لا، أو ما أدري","en":"No, or not sure"}]},{"id":"frozen","ar":"هل جمّدتها أو خلطتها بقوة بعد التبريد؟","en":"Did you freeze it or beat it hard after chilling?","options":[{"id":"freeze","ar":"جمّدتها","en":"I froze it"},{"id":"beat","ar":"خفقتها بقوة","en":"I beat it hard"},{"id":"no","ar":"لا","en":"No"}]}],"causes":[{"id":"amylase","kind":"process","prior":1,"evidence":"established","src":["S2"],"title":{"ar":"إنزيم الصفار ما انطفى","en":"The yolk enzyme was not destroyed"},"why":{"ar":"الصفار فيه إنزيم أميليز يكسّر النشا. إذا ما غلت الكريمة دقيقة، يبقى الإنزيم شغّال، فتكون ثخينة وقت الطبخ وترتخي بعد ساعات.","en":"Yolk contains amylase, which breaks down starch. If the cream does not boil for a minute the enzyme survives, so it is thick at first and thins after hours."},"answers":{"when":{"later":3,"never":-1},"boil":{"no":3,"yes":-2}},"fixes":[{"type":"process","evidence":"established","src":["S2"],"ar":"بعد ما تثخن، خلّها تفقّع دقيقة إلى دقيقتين مع الخفق المستمر.","en":"Once thick, let it bubble for one to two minutes while whisking.","tradeoff":{"ar":"تبخّر بسيط يثقّل القوام قليلاً.","en":"A little evaporation thickens it slightly."}}],"verify":{"ar":"اترك عيّنة 24 ساعة في الثلاجة: إذا ما ارتخت، فالسبب كان الإنزيم.","en":"Keep a sample 24 hours in the fridge. If it does not thin, the enzyme was the cause."}},{"id":"starch-low","kind":"formula","prior":0,"evidence":"established","src":["S2","S1"],"title":{"ar":"النشا قليل في الوصفة","en":"Too little starch in the recipe"},"why":{"ar":"النشا هو اللي يمسك الكريمة. إذا قليل مقابل السوائل، تطلع الكريمة سايلة حتى لو انطبخت صح.","en":"Starch is what sets the cream. With too little for the liquid, it stays runny even when cooked correctly."},"rule":{"feat":"thickPct","when":"below","range":{"default":[4,7]},"evidence":"estimate","src":["S2"],"note":{"ar":"نسبة النشا للكريمة باتسيير بالنشا: نطاق عمل من وصفات مهنية شائعة، يحتاج اعتماد مراجع.","en":"Starch level for cornstarch pastry cream: a working range from common professional formulas, pending review."}},"answers":{"when":{"never":2},"boil":{"yes":1}},"fixes":[{"type":"recipe","evidence":"estimate","src":["S2"],"ar":"ارفع النشا إلى حوالي 5% من وزن الكريمة.","en":"Raise the starch to about 5% of the cream weight.","op":{"op":"reach","role":"starch","feat":"thickPct","target":5},"tradeoff":{"ar":"قوام أثقل ولمعة أقل، وطعم نشا إذا ما انطبخت كفاية.","en":"Heavier and less glossy, with a starchy taste if undercooked."}}],"verify":{"ar":"اطبخ دفعة صغيرة بالنسبة الجديدة: إذا مسكت شكلها بعد التبريد، فالسبب كان النشا.","en":"Cook a small batch at the new level. If it holds its shape after chilling, starch was the cause."}},{"id":"acid","kind":"process","prior":0,"evidence":"established","src":["S7","S1"],"title":{"ar":"حموضة أضيفت للنشا","en":"Acid added to the starch"},"why":{"ar":"الحموضة (ليمون، فاكهة) مع الحرارة تقطّع جزيئات النشا فيضعف الجل. إضافة العصير بعد الطبخ والكريمة دافئة أقل ضرراً.","en":"Acid (lemon, fruit) with heat cuts starch molecules and weakens the gel. Adding juice after cooking, while warm, does less harm."},"answers":{"when":{"added":3,"later":1}},"fixes":[{"type":"process","evidence":"consensus","src":["S1"],"ar":"اطبخ الكريمة بالحليب أولاً، وأضف العصير أو الفاكهة بعد الطبخ وهي دافئة. للكريمات الحامضة استعمل نشا معدّل يتحمل الحموضة.","en":"Cook the cream with milk first and add juice or fruit after cooking while warm. For acidic creams use an acid-stable modified starch.","tradeoff":{"ar":"طعم الفاكهة يكون أخف إذا قلّلت الكمية.","en":"Fruit flavour is milder if you reduce the amount."}}],"verify":{"ar":"قارن دفعتين: وحدة العصير أضيف قبل الطبخ ووحدة بعده.","en":"Compare two batches: juice added before cooking and after."}},{"id":"gel-broken","kind":"process","prior":0,"evidence":"established","src":["S7","S1"],"title":{"ar":"الجل تكسّر بالتجميد أو الخفق","en":"The gel broke by freezing or beating"},"why":{"ar":"نشا الذرة العادي يطرد الماء بعد التجميد والذوبان، والخفق القوي بعد التبريد يكسّر الجل فيرتخي.","en":"Native cornstarch weeps after freezing and thawing, and hard beating after chilling breaks the gel so it thins."},"answers":{"frozen":{"freeze":3,"beat":2,"no":-2}},"fixes":[{"type":"process","evidence":"established","src":["S7"],"ar":"إذا تبي تجمّدها، استعمل نشا معدّل مخصص للتجميد. ونعّمها بهدوء بالمضرب المسطح بدل الخفق القوي.","en":"If you freeze it, use a freeze-thaw stable modified starch. Smooth it gently with a paddle instead of beating hard.","tradeoff":{"ar":"النشا المعدّل أغلى وما يعطي نفس الطعم الكلاسيكي.","en":"Modified starch costs more and tastes less classic."}}],"verify":{"ar":"جمّد عيّنتين وذوّبهم: وحدة بالنشا العادي ووحدة بالمعدّل وقارن الماء اللي يطلع.","en":"Freeze and thaw two samples, native and modified starch, and compare the water released."}}],"rescue":{"ar":["الكريمة اللي ارتخت من الإنزيم ما ترجع: لا تعيد غليها بعد ما برّدت إذا كان فيها بيض للسلامة؛ استعملها كصوص فقط إذا ريحتها وطعمها سليمين وضمن يومها.","إذا ما ثخنت أثناء الطبخ: كمّل الطبخ حتى تفقّع دقيقة."],"en":["Cream thinned by the enzyme does not recover; use it only as a sauce if it smells and tastes fine and within the day.","If it never thickened while cooking, keep cooking until it bubbles for a minute."],"safety":{"ar":"الكريمة اللي فيها بيض لازم تبرد بسرعة: من 57 إلى 21°م خلال ساعتين، ثم إلى 5°م خلال 4 ساعات إضافية.","en":"Egg creams must cool fast: from 57 to 21 °C within 2 hours, then to 5 °C within a further 4 hours.","src":["S6"]}},"prevent":{"ar":["خلّها تفقّع دقيقة إلى دقيقتين.","النشا 4 إلى 7% من الوزن.","أضف الحموضة بعد الطبخ.","نشا معدّل للتجميد."],"en":["Let it bubble one to two minutes.","Starch 4–7% of the weight.","Add acid after cooking.","Modified starch for freezing."]},"notFormula":{"ar":"إذا النشا 4 إلى 7% وما فيها حموضة، فالسبب غالباً إن الكريمة ما غلت كفاية.","en":"If starch is 4–7% and there is no acid, the cause is most likely that the cream did not boil long enough."},"unsure":{"ar":"أهم سؤال: هل غلت دقيقة؟ جاوبه عشان أحدد السبب.","en":"The key question is whether it boiled for a minute. Answer it so I can tell."}},{"id":"anglaise-curdled","category":"custard","status":"draft","reviewedBy":null,"severity":"medium","rescuable":true,"symptom":{"ar":"الكريم أنجليز أو الكيرد تقطّع وصار فيه حبيبات","en":"Crème anglaise or curd curdled into grains","syn":{"ar":["الأنجليز تقطّع","الكريم أنجليز صار بيض مخفوق","الليمون كيرد تحبب","الكاسترد تخثّر","الصوص صار حبوب"],"en":["anglaise curdled","custard sauce split","lemon curd grainy","scrambled custard"]}},"see":{"ar":"الصوص فقد نعومته وصار فيه حبيبات بيض واضحة، وأحياناً سائل خفيف حولها.","en":"The sauce lost its smoothness and shows clear egg grains, sometimes with thin liquid around them."},"questions":[{"id":"temp","ar":"كم وصلت الحرارة؟","en":"What temperature did it reach?","options":[{"id":"ok","ar":"تحت 84°م","en":"Below 84 °C"},{"id":"hot","ar":"فوق 85°م أو غلت","en":"Above 85 °C or it boiled"},{"id":"nk","ar":"ما قستها","en":"Did not measure"}]},{"id":"heat","ar":"كيف طبختها؟","en":"How did you cook it?","options":[{"id":"direct","ar":"على النار مباشرة","en":"Direct heat"},{"id":"bain","ar":"على حمام مائي","en":"Water bath"}]},{"id":"after","ar":"وش سويت بعد الطبخ؟","en":"What did you do after cooking?","options":[{"id":"cooled","ar":"صفّيتها وبرّدتها فوراً","en":"Strained and cooled at once"},{"id":"pan","ar":"تركتها في القدر الحار","en":"Left it in the hot pan"}]}],"causes":[{"id":"overheated","kind":"process","prior":1,"evidence":"consensus","src":["S2"],"title":{"ar":"سخنت زيادة","en":"It overheated"},"why":{"ar":"الأنجليز تثخن بين 78 و84°م تقريباً. فوق 85°م يتجمّد البيض بسرعة ويتقطّع، لأن ما فيها نشا يحمي الصفار.","en":"Anglaise thickens at roughly 78–84 °C. Above 85 °C the egg sets fast and curdles, as there is no starch to protect the yolk."},"answers":{"temp":{"hot":3,"ok":-2},"heat":{"direct":1}},"fixes":[{"type":"process","evidence":"consensus","src":["S2"],"ar":"اطبخ على نار هادئة مع تحريك مستمر، وارفعها عند 82 إلى 84°م أو لما تغطي ظهر الملعقة وترسم خط واضح.","en":"Cook on low heat stirring constantly, and take it off at 82–84 °C or when it coats the spoon and holds a clear line.","tradeoff":{"ar":"يحتاج ميزان حرارة ووقت أطول.","en":"Needs a thermometer and more time."}}],"verify":{"ar":"قس الحرارة وارفعها عند 82°م: إذا طلعت ناعمة، فالسبب كان الحرارة.","en":"Measure and stop at 82 °C. If it is smooth, heat was the cause."}},{"id":"carryover","kind":"process","prior":0,"evidence":"consensus","src":["S2"],"title":{"ar":"استمرّ الطبخ بعد ما رفعتها","en":"It kept cooking after you took it off"},"why":{"ar":"القدر الحار يكمّل التسخين. إذا تركتها فيه، ترتفع الحرارة فوق الحد وتتقطّع.","en":"A hot pan keeps heating. Left in it, the custard climbs past the limit and curdles."},"answers":{"after":{"pan":3,"cooled":-2}},"fixes":[{"type":"process","evidence":"consensus","src":["S2"],"ar":"صفّها فوراً في وعاء بارد موضوع على ثلج، وحرّكها لين تبرد.","en":"Strain it at once into a cold bowl set over ice, and stir until it cools.","tradeoff":{"ar":"خطوة إضافية تحتاج ثلج جاهز.","en":"An extra step that needs ice ready."}}],"verify":{"ar":"قس الحرارة بعد دقيقتين من رفعها: ما لازم ترتفع.","en":"Measure two minutes after removing it: it should not rise."}},{"id":"sugar-low","kind":"formula","prior":0,"evidence":"established","src":["S2"],"title":{"ar":"السكر قليل في الوصفة","en":"Too little sugar in the recipe"},"why":{"ar":"السكر يرفع حرارة تجمّد البيض ويعطيك هامش أمان. الوصفة القليلة السكر تتقطّع أسرع.","en":"Sugar raises the egg setting temperature and gives a safety margin. Low-sugar recipes curdle sooner."},"rule":{"feat":"addedSugar","when":"below","range":{"default":[8,20]},"evidence":"estimate","src":["S2"],"note":{"ar":"السكر المضاف في الأنجليز الكلاسيكية حوالي 10 إلى 18% من الوزن؛ نطاق تقديري.","en":"Added sugar in classic anglaise is about 10–18% of the weight; a working range."}},"answers":{"temp":{"ok":1}},"fixes":[{"type":"recipe","evidence":"estimate","src":["S2"],"ar":"ارفع السكر إلى حوالي 12% من الوزن.","en":"Raise the sugar to about 12% of the weight.","op":{"op":"reach","role":"sugar","feat":"addedSugar","target":12},"tradeoff":{"ar":"أحلى، وقد يغطي على طعم الفانيلا أو الفاكهة.","en":"Sweeter, and it may mask vanilla or fruit."}}],"verify":{"ar":"اطبخ نفس الطريقة بالسكر الجديد وقارن عند نفس الحرارة.","en":"Cook the same way with the new sugar and compare at the same temperature."}}],"rescue":{"ar":["إذا التقطّع خفيف: صفّها فوراً في وعاء بارد، واخلطها بالبلندر 30 ثانية، ثم صفّها مرة ثانية.","إذا فيها قطع بيض كبيرة: استعملها في مكان ما يحتاج نعومة، أو تخلّص منها."],"en":["If lightly curdled, strain at once into a cold bowl, blend 30 seconds and strain again.","With large egg pieces, use it where smoothness does not matter, or discard."],"safety":{"ar":"برّدها بسرعة واحفظها مبرّدة: من 57 إلى 21°م خلال ساعتين، ثم إلى 5°م خلال 4 ساعات إضافية.","en":"Cool it fast and keep it chilled: from 57 to 21 °C within 2 hours, then to 5 °C within a further 4 hours.","src":["S6"]}},"prevent":{"ar":["نار هادئة وتحريك مستمر.","ارفعها عند 82 إلى 84°م.","صفّها فوراً على ثلج.","حمام مائي للكيرد."],"en":["Low heat, constant stirring.","Stop at 82–84 °C.","Strain at once over ice.","Water bath for curds."]},"notFormula":{"ar":"التقطّع في الأنجليز تقريباً دايماً من الحرارة، مو من الوصفة.","en":"Curdling in anglaise is almost always heat, not the recipe."},"unsure":{"ar":"قِس الحرارة في المرة الجاية؛ هي أهم معلومة.","en":"Measure the temperature next time; it is the key fact."}},{"id":"whipped-cream-fail","category":"cream","status":"draft","reviewedBy":null,"severity":"low","rescuable":true,"symptom":{"ar":"الكريمة ما انخفقت، أو انخفقت ثم صارت زبدة","en":"Cream will not whip, or whips then turns to butter","syn":{"ar":["الكريمة ما تنخفق","الكريمة ما تمسك","الكريمة صارت زبدة","الكريمة تحببت","الشانتيه نزل","الكريمة سايلة بعد الخفق"],"en":["cream won't whip","whipped cream collapses","cream turned to butter","grainy whipped cream"]}},"see":{"ar":"الكريمة تبقى سايلة وما تمسك، أو صارت محببة وطلع منها سائل.","en":"The cream stays liquid and will not hold, or it went grainy and released liquid."},"questions":[{"id":"result","ar":"وش صار؟","en":"What happened?","options":[{"id":"liquid","ar":"ما انخفقت أو نزلت بسرعة","en":"It would not whip or fell quickly"},{"id":"butter","ar":"صارت محببة أو زبدة","en":"It went grainy or buttery"}]},{"id":"temp","ar":"كانت الكريمة والوعاء باردين؟","en":"Were the cream and bowl cold?","options":[{"id":"cold","ar":"نعم، من الثلاجة (تحت 8°م)","en":"Yes, from the fridge (below 8 °C)"},{"id":"warm","ar":"لا، دافئة أو الجو حار","en":"No, warm or a hot room"}]},{"id":"speed","ar":"كيف خفقتها؟","en":"How did you whip it?","options":[{"id":"high","ar":"سرعة عالية لين النهاية","en":"High speed to the end"},{"id":"control","ar":"متوسطة وراقبتها","en":"Medium, watching it"}]}],"causes":[{"id":"fat-low","kind":"formula","prior":0,"evidence":"established","src":["S2"],"title":{"ar":"الدهن قليل","en":"Too little fat"},"why":{"ar":"الكريمة تنخفق لأن كريات الدهن تتلاصق حول فقاعات الهواء. تحت حوالي 30% دهن ما تكفي لتمسك الرغوة.","en":"Cream whips because fat globules link around air bubbles. Below about 30% fat there are not enough to hold the foam."},"rule":{"feat":"fat","when":"below","range":{"default":[28,40]},"evidence":"established","src":["S2"]},"answers":{"result":{"liquid":2,"butter":-2}},"fixes":[{"type":"recipe","evidence":"established","src":["S2"],"ar":"قلّل الحليب أو السائل المضاف حتى يصير الدهن 30% على الأقل، أو استعمل كريمة خفق 35%.","en":"Reduce the added milk or liquid until fat is at least 30%, or use 35% whipping cream.","op":{"op":"reach","role":["milk","water"],"feat":"fat","target":30},"tradeoff":{"ar":"أثقل وأغنى وتكلفة أعلى.","en":"Heavier, richer and more costly."}}],"verify":{"ar":"اخفق نفس الكمية بالكريمة الجديدة باردة: إذا مسكت قمم ثابتة، فالسبب كان الدهن.","en":"Whip the same amount of the new cream cold. Stiff peaks confirm fat was the cause."}},{"id":"too-warm","kind":"process","prior":1,"evidence":"consensus","src":["S2"],"title":{"ar":"الكريمة أو المكان دافئ","en":"Cream or room too warm"},"why":{"ar":"الدهن لازم يكون نصف صلب عشان يمسك الهواء. فوق حوالي 10°م يلين الدهن وتنزل الرغوة أو تتحول زبدة بسرعة. هذا شائع في مطابخ الخليج.","en":"Fat must be partly solid to hold air. Above about 10 °C it softens, so the foam falls or turns to butter fast. Common in Gulf kitchens."},"answers":{"temp":{"warm":3,"cold":-2}},"fixes":[{"type":"process","evidence":"consensus","src":["S2"],"ar":"برّد الكريمة إلى 4 إلى 6°م، وبرّد الوعاء والمضرب في الفريزر 10 دقائق.","en":"Chill the cream to 4–6 °C and the bowl and whisk in the freezer for 10 minutes.","tradeoff":{"ar":"وقت تحضير أطول.","en":"Longer preparation."}}],"verify":{"ar":"قس حرارة الكريمة قبل الخفق وسجّلها.","en":"Measure the cream before whipping and log it."}},{"id":"overwhipped","kind":"process","prior":0,"evidence":"established","src":["S2"],"title":{"ar":"خفق زايد","en":"Over-whipped"},"why":{"ar":"الخفق الزايد يكسّر أغلفة كريات الدهن فتتجمّع حبيبات زبدة ويطلع السائل (اللبن).","en":"Over-whipping breaks the fat globule membranes, so butter grains clump and the buttermilk separates."},"answers":{"result":{"butter":3,"liquid":-2},"speed":{"high":2,"control":-1}},"fixes":[{"type":"process","evidence":"consensus","src":["S2"],"ar":"اخفق على سرعة متوسطة وتوقّف أول ما تمسك قمم ناعمة، وكمّل باليد إذا تبيها أقوى.","en":"Whip on medium and stop at soft peaks; finish by hand if you want it firmer.","tradeoff":{"ar":"أبطأ قليلاً.","en":"Slightly slower."}}],"verify":{"ar":"إذا مسكت ناعمة بدون حبيبات عند التوقف المبكر، فالسبب كان الخفق الزايد.","en":"If it holds smoothly when you stop earlier, over-whipping was the cause."}}],"rescue":{"ar":["إذا تحببت قليلاً: أضف 10 إلى 20% كريمة سايلة باردة وحرّك باليد بهدوء.","إذا صارت زبدة: كمّل الخفق، صفّ اللبن، واستعمل الزبدة في الطبخ."],"en":["If slightly grainy, fold in 10–20% cold liquid cream by hand.","If it turned to butter, keep whipping, drain the buttermilk and use the butter in cooking."]},"prevent":{"ar":["كريمة 30 إلى 35% دهن.","كل شي بارد (4 إلى 6°م).","سرعة متوسطة وتوقّف عند القمم الناعمة."],"en":["Cream with 30–35% fat.","Everything cold (4–6 °C).","Medium speed; stop at soft peaks."]},"notFormula":{"ar":"إذا الدهن 30% أو أكثر، فالسبب غالباً الحرارة أو الخفق.","en":"If fat is 30% or more, the cause is most likely temperature or whipping."},"unsure":{"ar":"حدد وش صار (ما انخفقت أو صارت زبدة) وجاوب الأسئلة.","en":"Say what happened (would not whip or turned to butter) and answer the questions."}},{"id":"buttercream-split","category":"cream","status":"draft","reviewedBy":null,"severity":"low","rescuable":true,"symptom":{"ar":"كريمة الزبدة تقطّعت أو صارت سايلة","en":"Buttercream curdled or turned soupy","syn":{"ar":["كريمة الزبدة تقطعت","البتر كريم مقطع","كريمة الزبدة سايلة","البتر كريم صار شوربة","كريمة الزبدة محببة"],"en":["buttercream curdled","buttercream split","soupy buttercream","runny swiss buttercream"]}},"see":{"ar":"إما شكل جبن مقطّع مع سائل، أو قوام سايل لامع ما يمسك.","en":"Either a cottage-cheese look with liquid, or a glossy runny texture that will not hold."},"questions":[{"id":"look","ar":"كيف شكلها؟","en":"What does it look like?","options":[{"id":"curdled","ar":"مقطّعة مثل الجبن","en":"Curdled like cottage cheese"},{"id":"soupy","ar":"سايلة ولامعة","en":"Runny and glossy"}]},{"id":"butter","ar":"كيف كانت الزبدة وقت الإضافة؟","en":"How was the butter when added?","options":[{"id":"cold","ar":"باردة وقاسية","en":"Cold and hard"},{"id":"soft","ar":"طرية (تنضغط بالإصبع وتمسك شكلها)","en":"Soft (dents but holds its shape)"},{"id":"warm","ar":"شبه ذايبة","en":"Almost melted"}]},{"id":"meringue","ar":"الميرنغ وقت إضافة الزبدة؟","en":"The meringue when adding butter?","options":[{"id":"warm","ar":"كانت دافئة","en":"Still warm"},{"id":"cool","ar":"بردت لحرارة الغرفة","en":"Cooled to room temperature"}]}],"causes":[{"id":"too-cold","kind":"process","prior":1,"evidence":"consensus","src":["S1"],"title":{"ar":"الزبدة باردة","en":"Butter too cold"},"why":{"ar":"الزبدة الباردة ما تقدر تحمل الماء اللي في الميرنغ، فيتقطّع الخليط. غالباً ما هي مشكلة؛ تكمل الخفق ويرجع.","en":"Cold butter cannot hold the water in the meringue, so the mix curdles. Often not a real problem: keep beating and it comes back."},"answers":{"look":{"curdled":2,"soupy":-2},"butter":{"cold":3,"warm":-2}},"fixes":[{"type":"process","evidence":"consensus","src":["S1"],"ar":"كمّل الخفق، أو دفّي جوانب الوعاء بالهواء الحار ثواني لين يتجانس. استعمل زبدة على حوالي 18 إلى 21°م.","en":"Keep beating, or warm the bowl sides briefly with a heat gun until it comes together. Use butter at about 18–21 °C.","tradeoff":{"ar":"التدفئة الزايدة تقلبها سايلة.","en":"Too much warming turns it soupy."}}],"verify":{"ar":"قس حرارة الزبدة قبل الإضافة وسجّلها.","en":"Measure the butter before adding and log it."}},{"id":"too-warm","kind":"process","prior":1,"evidence":"consensus","src":["S1"],"title":{"ar":"الخليط دافئ: الزبدة ذايبة أو الميرنغ حار","en":"Too warm: melted butter or hot meringue"},"why":{"ar":"إذا الميرنغ دافئة أو الزبدة شبه ذايبة، الدهن يصير سائل وما يمسك الهواء فتطلع سايلة.","en":"With warm meringue or near-melted butter the fat turns liquid and cannot hold air, so it goes soupy."},"answers":{"look":{"soupy":3,"curdled":-2},"butter":{"warm":2},"meringue":{"warm":3,"cool":-1}},"fixes":[{"type":"process","evidence":"consensus","src":["S1"],"ar":"برّد الوعاء 10 إلى 15 دقيقة في الثلاجة ثم اخفق من جديد. ولا تضيف الزبدة إلا لما تبرد الميرنغ لحرارة الغرفة.","en":"Chill the bowl 10–15 minutes, then beat again. Only add butter once the meringue has cooled to room temperature.","tradeoff":{"ar":"وقت انتظار.","en":"Waiting time."}}],"verify":{"ar":"قس حرارة الميرنغ قبل الزبدة: إذا كانت قريبة من حرارة الغرفة والكريمة مسكت، فالسبب كان الحرارة.","en":"Measure the meringue before the butter. Near room temperature with a stable cream confirms heat was the cause."}},{"id":"water-high","kind":"formula","prior":0,"evidence":"established","src":["S1"],"title":{"ar":"السوائل كثيرة مقابل الزبدة","en":"Too much liquid for the butter"},"why":{"ar":"كريمة الزبدة مستحلب ماء في دهن. إذا زاد الماء (بياض، عصير، بيوريه) عن طاقة الزبدة، يتقطّع الخليط.","en":"Buttercream is water in fat. If water (whites, juice, purée) exceeds what the butter can hold, it curdles."},"rule":{"feat":"fatWater","when":"below","range":{"default":[1.4,3]},"evidence":"estimate","src":["S1"],"note":{"ar":"محسوب من وصفات كريمة زبدة سويسرية وإيطالية شائعة؛ نطاق تقديري.","en":"Derived from common Swiss and Italian buttercream formulas; a working range."}},"answers":{"look":{"curdled":1}},"fixes":[{"type":"recipe","evidence":"estimate","src":["S1"],"ar":"زد الزبدة حتى تصير الدهون 1.6 من وزن الماء.","en":"Increase the butter until fat is 1.6 times the water.","op":{"op":"reach","role":"butter","feat":"fatWater","target":1.6},"tradeoff":{"ar":"أثقل وطعم زبدة أقوى.","en":"Heavier, with a stronger butter taste."}}],"verify":{"ar":"اعمل دفعة صغيرة بالنسبة الجديدة بنفس الحرارة.","en":"Make a small batch at the new ratio at the same temperature."}}],"rescue":{"ar":["مقطّعة: كمّل الخفق أو دفّي الجوانب قليلاً.","سايلة: برّدها 10 إلى 15 دقيقة ثم اخفقها."],"en":["Curdled: keep beating or warm the sides slightly.","Soupy: chill 10–15 minutes, then beat."]},"prevent":{"ar":["زبدة على 18 إلى 21°م.","الميرنغ بحرارة الغرفة قبل الزبدة.","أضف الزبدة قطعة قطعة.","أضف السوائل والبيوريه في الأخير وبكمية محدودة."],"en":["Butter at 18–21 °C.","Meringue at room temperature before butter.","Add butter piece by piece.","Add liquids and purées last and in limited amounts."]},"notFormula":{"ar":"أغلب حالات كريمة الزبدة من الحرارة، والوصفة نادراً هي السبب.","en":"Most buttercream failures are temperature; the recipe is rarely the cause."},"unsure":{"ar":"حدد الشكل (مقطّعة أو سايلة)؛ كل وحدة عكس الثانية.","en":"Say how it looks (curdled or soupy); each is the opposite of the other."}},{"id":"mousse-not-set","category":"mousse","status":"draft","reviewedBy":null,"severity":"medium","rescuable":false,"symptom":{"ar":"الموس ما تماسك أو نزل","en":"Mousse did not set or collapsed","syn":{"ar":["الموس ما مسك","الموس سايل","الموس نزل","البافاروا ما تماسكت","الجيلاتين ما اشتغل","الموس ما جمد"],"en":["mousse not setting","runny mousse","bavarois did not set","gelatine not working"]}},"see":{"ar":"الموس طري أو سايل بعد ساعات في الثلاجة، أو فقد الهواء ونزل.","en":"The mousse is soft or runny after hours chilled, or it lost its air and sank."},"questions":[{"id":"fruit","ar":"فيه فاكهة طازجة مثل أناناس أو كيوي أو بابايا أو مانجو طازج؟","en":"Does it contain fresh pineapple, kiwi, papaya or fresh mango?","options":[{"id":"fresh","ar":"نعم، طازجة","en":"Yes, fresh"},{"id":"cooked","ar":"نعم بس مطبوخة أو معلّبة","en":"Yes, but cooked or canned"},{"id":"no","ar":"لا","en":"No"}]},{"id":"fold","ar":"حرارة الخليط لما أضفت الكريمة المخفوقة؟","en":"Base temperature when folding in the whipped cream?","options":[{"id":"hot","ar":"دافئ (فوق 35°م)","en":"Warm (above 35 °C)"},{"id":"ok","ar":"حوالي 25 إلى 30°م","en":"About 25–30 °C"},{"id":"cold","ar":"بارد ومتماسك","en":"Cold and already setting"}]},{"id":"time","ar":"كم تركته في الثلاجة؟","en":"How long did it chill?","options":[{"id":"short","ar":"أقل من 4 ساعات","en":"Less than 4 hours"},{"id":"long","ar":"4 ساعات أو أكثر","en":"4 hours or more"}]}],"causes":[{"id":"gelatin-low","kind":"formula","prior":0,"evidence":"established","src":["S1"],"title":{"ar":"الجيلاتين قليل","en":"Too little gelatine"},"why":{"ar":"الجيلاتين يمسك الموس. إذا قليل مقابل الوزن الكلي، يبقى طري حتى بعد ساعات.","en":"Gelatine sets the mousse. Too little for the total weight and it stays soft even after hours."},"rule":{"feat":"gelPct","when":"below","range":{"default":[0.6,1.5]},"evidence":"estimate","src":["S1"],"note":{"ar":"لجيلاتين بقوة 200 بلوم تقريباً؛ نفس النطاق المستعمل في قواعد المنصة. يحتاج اعتماد.","en":"For about 200-bloom gelatine; the same range as the platform's rules. Pending review."}},"answers":{"time":{"long":1},"fruit":{"no":1}},"fixes":[{"type":"recipe","evidence":"estimate","src":["S1"],"ar":"ارفع الجيلاتين إلى حوالي 0.9% من الوزن الكلي.","en":"Raise the gelatine to about 0.9% of the total weight.","op":{"op":"reach","role":"gelatin","feat":"gelPct","target":0.9},"tradeoff":{"ar":"الزيادة الكبيرة تعطي قوام مطاطي.","en":"Too much gives a rubbery texture."}}],"verify":{"ar":"اعمل كوب صغير بالنسبة الجديدة واتركه 6 ساعات.","en":"Set a small cup at the new level for 6 hours."}},{"id":"enzymes","kind":"formula","prior":0,"evidence":"established","src":["S2"],"title":{"ar":"إنزيمات الفاكهة الطازجة كسّرت الجيلاتين","en":"Fresh fruit enzymes broke down the gelatine"},"why":{"ar":"الأناناس والكيوي والبابايا والتين الطازج فيها إنزيمات تقطّع بروتين الجيلاتين فما يتماسك. الطبخ يوقف الإنزيم.","en":"Fresh pineapple, kiwi, papaya and fig contain enzymes that cut gelatine protein so it cannot set. Cooking stops the enzyme."},"answers":{"fruit":{"fresh":4,"cooked":-1,"no":-3}},"fixes":[{"type":"process","evidence":"established","src":["S2"],"ar":"اغلي البيوريه دقيقتين وبرّده قبل الاستعمال، أو استعمل معلّب أو مجمّد مبستر، أو بدّل الجيلاتين بأجار أو بكتين.","en":"Boil the purée for two minutes and cool it, or use canned or pasteurised frozen fruit, or switch to agar or pectin.","tradeoff":{"ar":"الطبخ يغيّر طعم الفاكهة الطازج قليلاً.","en":"Cooking slightly changes the fresh fruit flavour."}}],"verify":{"ar":"اعمل كوبين: بيوريه مغلي وبيوريه طازج، بنفس الجيلاتين.","en":"Set two cups, boiled and fresh purée, with the same gelatine."}},{"id":"fold-temp","kind":"process","prior":1,"evidence":"consensus","src":["S1"],"title":{"ar":"حرارة الخلط غلط","en":"Wrong folding temperature"},"why":{"ar":"إذا الخليط حار، يذوّب الكريمة المخفوقة فيطير الهواء وينزل الموس. وإذا بارد ومتماسك، يتكتّل الجيلاتين ويتوزع غلط.","en":"A hot base melts the whipped cream so air escapes and the mousse sinks. A cold, setting base makes the gelatine clump unevenly."},"answers":{"fold":{"hot":3,"cold":2,"ok":-2}},"fixes":[{"type":"process","evidence":"consensus","src":["S1"],"ar":"برّد الخليط إلى حوالي 25 إلى 30°م قبل ما تضيف الكريمة المخفوقة على دفعات.","en":"Cool the base to about 25–30 °C before folding in the whipped cream in stages.","tradeoff":{"ar":"تحتاج ميزان حرارة ووقت.","en":"Needs a thermometer and time."}}],"verify":{"ar":"قس الخليط قبل الإضافة، وقارن ارتفاع الموس في القالب بعد التماسك.","en":"Measure the base before folding and compare the set mousse height."}},{"id":"short-set","kind":"process","prior":0,"evidence":"consensus","src":["S1"],"title":{"ar":"ما أخذ وقت كافي في البرد","en":"Not chilled long enough"},"why":{"ar":"الجيلاتين يحتاج ساعات في البرد عشان يكمل تماسكه.","en":"Gelatine needs hours in the cold to set fully."},"answers":{"time":{"short":3,"long":-2}},"fixes":[{"type":"process","evidence":"consensus","src":["S1"],"ar":"اتركه 6 ساعات على الأقل في الثلاجة، أو جمّده إذا المنتج يتحمل.","en":"Chill at least 6 hours, or freeze if the product allows.","tradeoff":{"ar":"يأخر التسليم.","en":"Delays delivery."}}],"verify":{"ar":"افحص عيّنة بعد 2 و4 و6 ساعات وسجّل متى تماسكت.","en":"Check a sample at 2, 4 and 6 hours and log when it set."}}],"rescue":{"ar":["الموس اللي ما تماسك ما يرجع. استعمله كحشوة كأس أو صوص بارد.","إذا السبب الوقت: انتظر أو جمّده."],"en":["An unset mousse does not recover. Use it as a cup filling or a cold sauce.","If time was the cause, wait or freeze it."]},"prevent":{"ar":["الجيلاتين 0.6 إلى 1.5% من الوزن.","اغلي بيوريه الفاكهة اللي فيها إنزيمات.","الخليط 25 إلى 30°م قبل الكريمة.","6 ساعات تبريد على الأقل."],"en":["Gelatine 0.6–1.5% of the weight.","Boil enzyme-rich fruit purées.","Base at 25–30 °C before the cream.","At least 6 hours chilling."]},"notFormula":{"ar":"إذا الجيلاتين ضمن النطاق وما فيه فاكهة طازجة، فالسبب غالباً حرارة الخلط أو الوقت.","en":"If gelatine is in range and there is no fresh fruit, the cause is most likely folding temperature or time."},"unsure":{"ar":"جاوب سؤال الفاكهة الطازجة أول؛ هو الأكثر حسماً.","en":"Answer the fresh fruit question first; it is the most decisive."}},{"id":"ganache-soft","category":"ganache","status":"draft","reviewedBy":null,"severity":"low","rescuable":true,"symptom":{"ar":"الغاناش طري وما يتماسك أو ما ينقطع","en":"Ganache is too soft and will not set or cut","syn":{"ar":["الغاناش طري","الغاناش ما جمد","الغاناش ما ينقطع","الحشوة طرية","الغاناش سايل"],"en":["soft ganache","ganache will not set","ganache too runny","cannot cut ganache"]}},"see":{"ar":"الغاناش يبقى طري أو لزج بعد التبلور، وما يمسك شكل عند التقطيع أو الحشو.","en":"The ganache stays soft or sticky after setting and will not hold a shape when cut or piped."},"questions":[{"id":"choc","ar":"وش نوع الشوكولاتة؟","en":"Which chocolate?","options":[{"id":"dark","ar":"داكنة","en":"Dark"},{"id":"milk","ar":"حليب أو بيضاء","en":"Milk or white"}]},{"id":"set","ar":"وين وكم تركته يتبلور؟","en":"Where and how long did it set?","options":[{"id":"good","ar":"15 إلى 18°م، 12 ساعة أو أكثر","en":"15–18 °C, 12 hours or more"},{"id":"fridge","ar":"في الثلاجة لوقت قصير","en":"Briefly in the fridge"},{"id":"warm","ar":"حرارة غرفة دافئة","en":"A warm room"}]},{"id":"use","ar":"وش الاستعمال؟","en":"What is it for?","options":[{"id":"cut","ar":"بونبون مقطّع أو بالقالب","en":"Cut or moulded bonbon"},{"id":"tart","ar":"تارت أو حلى مبرّد","en":"Tart or chilled dessert"}]}],"causes":[{"id":"water-high","kind":"formula","prior":0,"evidence":"established","src":["S4"],"title":{"ar":"الماء عالي لنوع المنتج","en":"Too much water for the product type"},"why":{"ar":"كل ما زاد الماء (من الكريمة والبيوريه)، صار الغاناش أطرى. البونبون يحتاج ماء أقل من غاناش التارت.","en":"The more water (from cream and purée), the softer the ganache. Bonbons need less water than tart ganache."},"rule":{"feat":"water","when":"above","range":{"default":[14,38],"gb":[14,22],"gt":[22,38],"gw":[35,52]},"evidence":"estimate","src":["S4"],"note":{"ar":"نطاقات الماء لكل نوع غاناش من محرك التوازن في المنصة؛ تقدير عمل يحتاج اعتماد.","en":"Water ranges per ganache type come from the platform's balance engine; working estimates pending review."}},"answers":{"use":{"cut":1},"set":{"good":1}},"fixes":[{"type":"recipe","evidence":"estimate","src":["S4"],"ar":"قلّل الكريمة حتى ينزل الماء تحت الحد الأعلى لنوع منتجك.","en":"Reduce the cream until water is below the maximum for your product type.","op":{"op":"reach","role":"cream","feat":"water","target":{"rel":"hi","add":-1}},"tradeoff":{"ar":"أقسى وأحلى نسبياً، وخطر تبلّر السكر يزيد إذا الماء قلّ كثير.","en":"Firmer and relatively sweeter; the risk of sugar crystallising rises if water drops a lot."}}],"verify":{"ar":"اعمل دفعة صغيرة وقصّها بعد 12 ساعة على 16°م.","en":"Make a small batch and cut it after 12 hours at 16 °C."}},{"id":"milk-fat","kind":"formula","prior":0,"evidence":"established","src":["S5"],"title":{"ar":"دهن الحليب يليّن زبدة الكاكاو","en":"Milk fat softens the cocoa butter"},"why":{"ar":"دهن الحليب (من الكريمة والزبدة وشوكولاتة الحليب والبيضاء) يختلط بزبدة الكاكاو ويخلي الخليط أطرى. لذلك غاناش الحليب والبيضاء يحتاج كريمة أقل.","en":"Milk fat (from cream, butter, milk and white chocolate) mixes with cocoa butter and makes the blend softer. So milk and white ganaches need less cream."},"answers":{"choc":{"milk":3,"dark":-1}},"fixes":[{"type":"process","evidence":"consensus","src":["S4"],"ar":"مع شوكولاتة الحليب أو البيضاء، قلّل الكريمة والزبدة مقارنة بالداكنة، أو أضف قليل زبدة كاكاو (2 إلى 5%).","en":"With milk or white chocolate, use less cream and butter than with dark, or add a little cocoa butter (2–5%).","tradeoff":{"ar":"زبدة الكاكاو تزيد التكلفة وتعطي قوام أقصف في الفم.","en":"Cocoa butter adds cost and a firmer bite."}}],"verify":{"ar":"قارن صلابة دفعتين بعد 12 ساعة: وحدة بزبدة كاكاو مضافة ووحدة بدون.","en":"Compare firmness of two batches after 12 hours, with and without added cocoa butter."}},{"id":"set-conditions","kind":"process","prior":1,"evidence":"consensus","src":["S4"],"title":{"ar":"ما تبلور صح","en":"It did not crystallise properly"},"why":{"ar":"زبدة الكاكاو تحتاج وقت وحرارة مناسبة عشان تتبلور. الحرارة الدافئة توقف التبلور، والثلاجة السريعة تعطي بلورات ضعيفة.","en":"Cocoa butter needs time at the right temperature to crystallise. Warmth stops it, and a quick fridge set gives weak crystals."},"answers":{"set":{"warm":3,"fridge":2,"good":-2}},"fixes":[{"type":"process","evidence":"consensus","src":["S4"],"ar":"اترك الغاناش يتبلور 12 إلى 24 ساعة على 15 إلى 18°م ورطوبة معتدلة، قبل التقطيع.","en":"Let the ganache crystallise 12–24 hours at 15–18 °C and moderate humidity before cutting.","tradeoff":{"ar":"يأخذ يوم كامل ويحتاج مكان مضبوط الحرارة.","en":"Takes a full day and needs a temperature-controlled room."}}],"verify":{"ar":"قس الحرارة في مكان التبلور وسجّلها مع وقت التقطيع.","en":"Log the setting-room temperature with the cutting time."}}],"rescue":{"ar":["اتركه يتبلور أطول على 15 إلى 18°م.","إذا ما زال طري: استعمله في تارت أو حشوة بالقالب بدل التقطيع."],"en":["Let it set longer at 15–18 °C.","If still soft, use it in tarts or moulded shells instead of cutting."]},"prevent":{"ar":["الماء ضمن نطاق نوع المنتج.","كريمة أقل مع الحليب والبيضاء.","تبلور 12 إلى 24 ساعة على 15 إلى 18°م."],"en":["Water within the product type's range.","Less cream with milk and white chocolate.","Set 12–24 hours at 15–18 °C."]},"notFormula":{"ar":"إذا الماء ضمن نطاق نوع منتجك، فالسبب غالباً نوع الشوكولاتة أو ظروف التبلور.","en":"If water is within your product type's range, the cause is most likely the chocolate type or the setting conditions."},"unsure":{"ar":"اختر نوع المنتج في المشروع (بونبون، تارت، مخفوق) عشان أقارن بالنطاق الصحيح.","en":"Choose the product type in the project (bonbon, tart, whipped) so I compare with the right range."}},{"id":"ganache-grainy","category":"ganache","status":"draft","reviewedBy":null,"severity":"low","rescuable":true,"symptom":{"ar":"الغاناش صار رملي أو محبب بعد أيام","en":"Ganache turned sandy or grainy after days","syn":{"ar":["الغاناش رملي","الغاناش فيه حبيبات سكر","الحشوة صارت رملية","الغاناش تسكّر","الغاناش خشن"],"en":["sandy ganache","grainy ganache after days","sugar crystals in ganache","gritty ganache"]}},"see":{"ar":"الغاناش كان ناعم، وبعد أيام صار فيه ملمس رملي على اللسان أو بقع باهتة.","en":"The ganache was smooth, then after days it feels sandy on the tongue or shows dull spots."},"questions":[{"id":"when","ar":"متى ظهر؟","en":"When did it appear?","options":[{"id":"start","ar":"من البداية","en":"From the start"},{"id":"days","ar":"بعد أيام","en":"After days"}]},{"id":"feel","ar":"كيف الملمس؟","en":"How does it feel?","options":[{"id":"sandy","ar":"رملي مثل السكر","en":"Sandy like sugar"},{"id":"waxy","ar":"شمعي مع بقع باهتة","en":"Waxy with dull spots"}]},{"id":"temp","ar":"كيف كان التخزين؟","en":"How was it stored?","options":[{"id":"stable","ar":"حرارة ثابتة 15 إلى 18°م","en":"Steady 15–18 °C"},{"id":"cycle","ar":"حرارة متغيرة أو دافئة","en":"Changing or warm temperature"}]}],"causes":[{"id":"sugar-crystal","kind":"formula","prior":0,"evidence":"established","src":["S8"],"title":{"ar":"السكر أكثر من اللي يذوب في الماء","en":"More sugar than the water can dissolve"},"why":{"ar":"السكروز يذوب حتى حوالي 2 غرام لكل غرام ماء في حرارة الغرفة. إذا السكريات فوق هالحد، يتبلور السكر مع الوقت ويصير رملي.","en":"Sucrose dissolves up to about 2 g per gram of water at room temperature. Above that, sugar crystallises over time and turns sandy."},"rule":{"feat":"sugarWater","when":"above","range":{"default":[0.5,2]},"evidence":"established","src":["S8"]},"answers":{"feel":{"sandy":3,"waxy":-2},"when":{"days":1}},"fixes":[{"type":"recipe","evidence":"established","src":["S8"],"ar":"بدّل نصف السكر المضاف بسكر محوّل؛ السكريات المختلطة تقاوم التبلور.","en":"Replace half the added sugar with invert sugar; mixed sugars resist crystallisation.","op":{"op":"swap","from":"sugar","to":"invert","frac":0.5,"factor":1,"name":{"ar":"سكر محوّل","en":"Invert sugar"},"comp":{"w":0.2,"s":0.8}},"tradeoff":{"ar":"أحلى قليلاً ويلون أسرع إذا انطبخ.","en":"Slightly sweeter and browns faster if heated."}},{"type":"recipe","evidence":"established","src":["S8"],"ar":"زد الكريمة حتى تنزل السكريات إلى 1.8 من وزن الماء.","en":"Increase the cream until sugars are 1.8 times the water.","op":{"op":"reach","role":"cream","feat":"sugarWater","target":1.8},"tradeoff":{"ar":"ماء أكثر يرفع نشاط الماء ويقصّر الصلاحية.","en":"More water raises water activity and shortens shelf life."}}],"verify":{"ar":"خزّن عيّنتين أسبوعين على 16°م، وحدة بالتعديل ووحدة بدون، وقارن الملمس.","en":"Store two samples two weeks at 16 °C, adjusted and not, and compare texture."}},{"id":"fat-bloom","kind":"process","prior":0,"evidence":"established","src":["S5"],"title":{"ar":"تزهّر الدهن من تقلب الحرارة","en":"Fat bloom from temperature swings"},"why":{"ar":"تقلب الحرارة يذوّب بلورات زبدة الكاكاو ويعيدها بشكل خشن، فيصير الملمس شمعي وتظهر بقع باهتة.","en":"Temperature swings melt cocoa butter crystals and re-form them coarser, giving a waxy feel and dull spots."},"answers":{"feel":{"waxy":3,"sandy":-2},"temp":{"cycle":3,"stable":-2}},"fixes":[{"type":"process","evidence":"consensus","src":["S5"],"ar":"خزّن على حرارة ثابتة 15 إلى 18°م، وتجنّب النقل في الحر وفتح الثلاجة المتكرر.","en":"Store at a steady 15–18 °C and avoid hot transport and repeated fridge opening.","tradeoff":{"ar":"تكلفة تخزين مضبوط.","en":"Cost of controlled storage."}}],"verify":{"ar":"قارن عيّنة على حرارة ثابتة بعيّنة تتنقل بين برد وحر يومياً.","en":"Compare a steady sample with one moved between cold and warm daily."}},{"id":"seeding","kind":"process","prior":0,"evidence":"consensus","src":["S8"],"title":{"ar":"بذور سكر غير ذايبة","en":"Undissolved sugar seeds"},"why":{"ar":"حبيبات سكر ما ذابت كاملاً (من سكر بودرة أو سكر مضاف بارد) تصير بذور يتبلور عليها الباقي.","en":"Sugar grains that never fully dissolved (from powdered or cold-added sugar) act as seeds the rest crystallises on."},"answers":{"when":{"start":2},"feel":{"sandy":1}},"fixes":[{"type":"process","evidence":"consensus","src":["S8"],"ar":"ذوّب السكر كاملاً في الكريمة الحارة قبل الخلط مع الشوكولاتة.","en":"Dissolve all sugar in the hot cream before mixing with the chocolate.","tradeoff":{"ar":"خطوة تسخين إضافية.","en":"An extra heating step."}}],"verify":{"ar":"افرك قطرة من الكريمة بين أصابعك قبل الخلط: لازم تكون ناعمة بدون حبيبات.","en":"Rub a drop of the cream between your fingers before mixing: it should be smooth with no grains."}}],"rescue":{"ar":["الغاناش الرملي ما يرجع ناعم في القطع الجاهزة.","إذا ما زال في الوعاء: سخّنه إلى 33–35°م مع 5% كريمة واخلطه، ثم استعمله بسرعة."],"en":["Sandy ganache in finished pieces does not turn smooth again.","If still in the bowl, warm to 33–35 °C with 5% cream, blend and use it quickly."]},"prevent":{"ar":["السكريات لا تتجاوز ضعف وزن الماء.","سكر محوّل أو جلوكوز مع السكر.","ذوّب السكر كاملاً.","تخزين ثابت 15 إلى 18°م."],"en":["Sugars no more than twice the water.","Invert sugar or glucose with sucrose.","Dissolve the sugar fully.","Steady storage at 15–18 °C."]},"notFormula":{"ar":"إذا السكريات أقل من ضعف الماء والملمس شمعي، فالسبب غالباً التخزين.","en":"If sugars are below twice the water and the feel is waxy, the cause is most likely storage."},"unsure":{"ar":"حدد الملمس (رملي أو شمعي)؛ الرملي غالباً سكر، والشمعي غالباً دهن.","en":"Say how it feels (sandy or waxy); sandy usually means sugar, waxy usually fat."}},{"id":"baked-custard-fail","category":"custard","status":"draft","reviewedBy":null,"severity":"medium","rescuable":false,"symptom":{"ar":"الكريم بروليه أو الفلان ما تماسك أو صار فيه فقاعات وتقطّع","en":"Crème brûlée or flan did not set, or has bubbles and curdled","syn":{"ar":["الكريم بروليه ما مسك","الفلان سايل","الكريم كراميل فيه فقاعات","الفلان مخرّم","الكريم بروليه تقطع"],"en":["creme brulee not setting","runny flan","flan with holes","curdled baked custard"]}},"see":{"ar":"الوسط سايل بعد التبريد، أو القوام فيه ثقوب وفقاعات وطعم بيض قوي.","en":"The centre is runny after chilling, or the texture has holes and bubbles with a strong egg taste."},"questions":[{"id":"result","ar":"وش المشكلة؟","en":"What is the problem?","options":[{"id":"runny","ar":"ما تماسك والوسط سايل","en":"Did not set, runny centre"},{"id":"holes","ar":"فيه ثقوب وفقاعات أو تقطّع","en":"Holes, bubbles or curdled"}]},{"id":"bake","ar":"كيف خبزته؟","en":"How did you bake it?","options":[{"id":"bain","ar":"حمام مائي على حرارة منخفضة","en":"Water bath, low oven"},{"id":"hot","ar":"بدون حمام مائي أو حرارة عالية","en":"No water bath or a hot oven"}]},{"id":"jiggle","ar":"لما طلعته، الوسط كان؟","en":"When you took it out, the centre was?","options":[{"id":"liquid","ar":"سائل يتموّج","en":"Liquid and wavy"},{"id":"wobble","ar":"يهتز كجلي","en":"Wobbling like jelly"},{"id":"firm","ar":"متماسك تماماً","en":"Completely firm"}]}],"causes":[{"id":"underbaked","kind":"process","prior":1,"evidence":"consensus","src":["S2"],"title":{"ar":"ما انخبز كفاية","en":"Underbaked"},"why":{"ar":"الكاسترد يتماسك لما يوصل الوسط حوالي 78 إلى 82°م. لو طلع والوسط سائل، يبقى سايل حتى بعد التبريد.","en":"Custard sets when the centre reaches about 78–82 °C. Taken out while liquid, it stays runny after chilling."},"answers":{"result":{"runny":2,"holes":-2},"jiggle":{"liquid":3,"wobble":-1}},"fixes":[{"type":"process","evidence":"consensus","src":["S2"],"ar":"اخبز حتى يهتز الوسط كجلي وما يتموّج، أو حتى تقيس 78 إلى 80°م في الوسط.","en":"Bake until the centre wobbles like jelly without waves, or reads 78–80 °C.","tradeoff":{"ar":"وقت خبز أطول.","en":"Longer bake."}}],"verify":{"ar":"قس حرارة الوسط عند الإخراج وسجّلها مع الوقت.","en":"Log the centre temperature and time at removal."}},{"id":"overbaked","kind":"process","prior":1,"evidence":"consensus","src":["S2"],"title":{"ar":"انخبز زيادة أو الفرن حار","en":"Overbaked or oven too hot"},"why":{"ar":"فوق حوالي 85°م يتجمّد البيض بقوة ويطرد الماء، فتتكوّن ثقوب وفقاعات وطعم بيض. الحمام المائي يحمي الأطراف.","en":"Above about 85 °C egg sets hard and squeezes out water, forming holes, bubbles and an eggy taste. A water bath protects the edges."},"answers":{"result":{"holes":3,"runny":-2},"bake":{"hot":3,"bain":-1},"jiggle":{"firm":2}},"fixes":[{"type":"process","evidence":"consensus","src":["S2"],"ar":"اخبز في حمام مائي على حرارة منخفضة (حوالي 100 إلى 150°م حسب الفرن والحجم)، وطلّعه وهو يهتز.","en":"Bake in a water bath at a low oven (about 100–150 °C depending on oven and size) and remove while it still wobbles.","tradeoff":{"ar":"وقت أطول ومساحة فرن أكثر.","en":"Longer time and more oven space."}}],"verify":{"ar":"اخبز نفس الخليط في حمام مائي وقارن القوام.","en":"Bake the same mix in a water bath and compare."}},{"id":"egg-low","kind":"formula","prior":0,"evidence":"established","src":["S2"],"title":{"ar":"البيض قليل مقابل السوائل","en":"Too little egg for the liquid"},"why":{"ar":"بروتين البيض هو اللي يمسك الكاسترد. إذا قليل مقابل الحليب والكريمة، ما يتماسك.","en":"Egg protein is what sets the custard. Too little for the milk and cream and it will not set."},"rule":{"feat":"yolkPct","when":"below","range":{"default":[8,20]},"evidence":"estimate","src":["S2"],"note":{"ar":"الصفار (أو ما يعادله من البيض الكامل) في الكريم بروليه والفلان الشائعة حوالي 9 إلى 16%؛ نطاق تقديري.","en":"Yolk (or whole-egg equivalent) in common crème brûlée and flan is about 9–16%; a working range."}},"answers":{"result":{"runny":1},"jiggle":{"wobble":1}},"fixes":[{"type":"recipe","evidence":"estimate","src":["S2"],"ar":"زد الصفار أو البيض حتى يصير الصفار حوالي 10% من الوزن.","en":"Increase yolk or egg until yolk is about 10% of the weight.","op":{"op":"reach","role":["yolk","egg"],"feat":"yolkPct","target":10},"tradeoff":{"ar":"أغنى وأثقل وطعم بيض أوضح.","en":"Richer, heavier and a clearer egg taste."}}],"verify":{"ar":"اخبز رامكين واحد بالنسبة الجديدة بنفس الفرن والوقت.","en":"Bake one ramekin at the new ratio, same oven and time."}}],"rescue":{"ar":["السايل: إذا ما زال في الفرن كمّل الخبز. بعد التبريد ما يرجع.","المقطّع: ما ينقذ، بس صالح للأكل كحلى بيتي إذا انحفظ مبرّد."],"en":["Runny: if still in the oven, keep baking; after chilling it will not recover.","Curdled: cannot be saved, though edible as a homestyle dessert if kept chilled."],"safety":{"ar":"الكاسترد المخبوز يُحفظ مبرّداً، ويبرّد بسرعة بعد الخبز: من 57 إلى 21°م خلال ساعتين، ثم إلى 5°م خلال 4 ساعات إضافية.","en":"Baked custard must be kept chilled and cooled fast after baking: from 57 to 21 °C within 2 hours, then to 5 °C within a further 4 hours.","src":["S6"]}},"prevent":{"ar":["حمام مائي وحرارة منخفضة.","طلّعه وهو يهتز كجلي.","اخلط بهدوء بدون ما تدخل هواء، وصفّ الخليط."],"en":["Water bath, low oven.","Remove while it wobbles like jelly.","Mix gently without air and strain the mix."]},"notFormula":{"ar":"إذا الصفار 8 إلى 20% من الوزن، فالسبب غالباً وقت أو حرارة الخبز.","en":"If yolk is 8–20% of the weight, the cause is most likely bake time or temperature."},"unsure":{"ar":"حدد المشكلة (سايل أو مخرّم) وكيف كان الوسط وقت الإخراج.","en":"Say whether it is runny or full of holes, and how the centre looked at removal."}},{"id":"cake-dry","category":"cake","status":"draft","reviewedBy":null,"severity":"low","rescuable":true,"symptom":{"ar":"الكيك ناشف ويتفتت","en":"Cake is dry and crumbly","syn":{"ar":["الكيك ناشف","الكيكة تتفتت","الكيك جاف","الكيك يشربك ماي","الكيك ينشف بسرعة"],"en":["dry cake","crumbly cake","cake dries out fast","cake not moist"]}},"see":{"ar":"القوام ناشف ويتفتت عند القطع، أو ينشف بسرعة بعد يوم.","en":"The crumb is dry and falls apart when cut, or dries out fast after a day."},"questions":[{"id":"when","ar":"متى يكون ناشف؟","en":"When is it dry?","options":[{"id":"fresh","ar":"من أول ما يبرد","en":"As soon as it cools"},{"id":"nextday","ar":"من ثاني يوم","en":"From the next day"}]},{"id":"bake","ar":"كيف كان الخبز؟","en":"How was the bake?","options":[{"id":"long","ar":"أطول من الوقت أو الحواف غامقة","en":"Longer than planned or dark edges"},{"id":"ok","ar":"حسب الوقت، والعود طلع نظيف بالضبط","en":"On time; the skewer just came out clean"}]},{"id":"store","ar":"كيف تخزّنه؟","en":"How do you store it?","options":[{"id":"open","ar":"مكشوف أو في الثلاجة بدون تغليف","en":"Uncovered or unwrapped in the fridge"},{"id":"wrapped","ar":"مغلّف محكم","en":"Wrapped airtight"}]}],"causes":[{"id":"overbaked","kind":"process","prior":1,"evidence":"consensus","src":["S1"],"title":{"ar":"انخبز زيادة","en":"Overbaked"},"why":{"ar":"كل دقيقة زيادة في الفرن تبخّر ماء من الكيك. أغلب الكيك الناشف من خبز زايد أو فرن أحر من المضبوط.","en":"Every extra minute in the oven evaporates water. Most dry cakes come from overbaking or an oven hotter than its dial."},"answers":{"bake":{"long":3,"ok":-2},"when":{"fresh":1}},"fixes":[{"type":"process","evidence":"consensus","src":["S1"],"ar":"طلّع الكيك أول ما يطلع العود نظيف من الوسط، وتأكد من حرارة الفرن بميزان مستقل.","en":"Take the cake out as soon as a skewer comes out clean from the centre, and check the oven with an independent thermometer.","tradeoff":{"ar":"لون القشرة أفتح قليلاً.","en":"Slightly paler crust."}}],"verify":{"ar":"زِن الكيك قبل الخبز وبعده وسجّل نسبة الفاقد؛ إذا قلّ الفاقد وصار أطرى، فالسبب كان الخبز.","en":"Weigh the cake before and after baking and log the loss; less loss and a moister crumb confirm baking was the cause."}},{"id":"sugar-low","kind":"formula","prior":0,"evidence":"established","src":["S1","S3"],"title":{"ar":"السكر قليل مقابل الدقيق","en":"Too little sugar for the flour"},"why":{"ar":"السكر يمسك الماء ويطري القوام ويبطئ الجفاف. الوصفة القليلة السكر تنشف أسرع.","en":"Sugar holds water, tenderises the crumb and slows staling. Low-sugar recipes dry out sooner."},"rule":{"feat":"sugarFlour","when":"below","range":{"default":[0.8,1.25]},"evidence":"consensus","src":["S1","S3"]},"answers":{"when":{"nextday":1}},"fixes":[{"type":"recipe","evidence":"consensus","src":["S1"],"ar":"ارفع السكر إلى وزن الدقيق تقريباً.","en":"Raise the sugar to about the flour weight.","op":{"op":"ratio","role":["sugar"],"base":"flour","target":1},"tradeoff":{"ar":"أحلى وقشرة أغمق، والهيكل أضعف قليلاً.","en":"Sweeter, darker crust and a slightly weaker structure."}}],"verify":{"ar":"قارن الطراوة بعد 24 ساعة بين الوصفتين بنفس التغليف.","en":"Compare moistness after 24 hours, both wrapped the same way."}},{"id":"fat-low","kind":"formula","prior":0,"evidence":"established","src":["S1"],"title":{"ar":"الدهن قليل مقابل الدقيق","en":"Too little fat for the flour"},"why":{"ar":"الدهن يغلّف الدقيق ويعطي إحساس بالطراوة في الفم. إذا قلّ، يحس الكيك ناشف حتى لو فيه ماء كافي.","en":"Fat coats the flour and gives a moist mouthfeel. With too little, the cake feels dry even with enough water."},"rule":{"feat":"fatFlour","when":"below","range":{"default":[0.5,1.1]},"evidence":"estimate","src":["S1"],"note":{"ar":"محسوب من وصفات كيك الزبدة الشائعة (يشمل دهن البيض)؛ الإسفنج والجينواز أقل دهناً بطبيعتها.","en":"Derived from common butter-cake formulas (includes egg fat); sponges and génoise are naturally leaner."}},"answers":{"when":{"fresh":1}},"fixes":[{"type":"recipe","evidence":"estimate","src":["S1"],"ar":"زد الزبدة حتى تصير الدهون 0.6 من وزن الدقيق.","en":"Increase the butter until fat is 0.6 times the flour weight.","op":{"op":"reach","role":"butter","feat":"fatFlour","target":0.6},"tradeoff":{"ar":"أغنى وأثقل وتكلفة أعلى.","en":"Richer, heavier and more costly."}}],"verify":{"ar":"اخبز الوصفة الجديدة بنفس الوقت وقارن القوام.","en":"Bake the new recipe for the same time and compare the crumb."}},{"id":"liquid-low","kind":"formula","prior":0,"evidence":"established","src":["S1"],"title":{"ar":"السوائل قليلة مقابل الدقيق","en":"Too little liquid for the flour"},"why":{"ar":"إذا الماء قليل مقابل الدقيق، يطلع الكيك كثيف وناشف.","en":"With too little water for the flour, the cake comes out dense and dry."},"rule":{"feat":"waterFlour","when":"below","range":{"default":[0.8,1.4]},"evidence":"estimate","src":["S1"],"note":{"ar":"نسبة الماء المضاف (من كل المكونات ما عدا رطوبة الدقيق) للدقيق في كيك الزبدة؛ نطاق تقديري.","en":"Added water (from all ingredients except flour moisture) to flour in butter cakes; a working range."}},"answers":{"when":{"fresh":1}},"fixes":[{"type":"recipe","evidence":"estimate","src":["S1"],"ar":"زد الحليب حتى تصير النسبة 0.9.","en":"Increase the milk until the ratio is 0.9.","op":{"op":"reach","role":["milk","water"],"feat":"waterFlour","target":0.9},"tradeoff":{"ar":"الزيادة الكبيرة تخلي الوسط رطب وينزل.","en":"Too much makes the centre wet and prone to sinking."}}],"verify":{"ar":"قارن القوام بعد التبريد بين الوصفتين.","en":"Compare the crumb of both recipes after cooling."}},{"id":"storage","kind":"process","prior":0,"evidence":"established","src":["S3"],"title":{"ar":"التخزين يسحب الرطوبة","en":"Storage draws out moisture"},"why":{"ar":"الكيك المكشوف يفقد ماء للجو، والثلاجة تسرّع تيبّس النشا. التغليف المحكم يبطئ الجفاف.","en":"Uncovered cake loses water to the air, and the fridge speeds starch staling. Airtight wrapping slows drying."},"answers":{"store":{"open":3,"wrapped":-2},"when":{"nextday":2,"fresh":-1}},"fixes":[{"type":"process","evidence":"established","src":["S3"],"ar":"غلّف الكيك وهو دافئ قليلاً بغلاف محكم، وخزّنه على حرارة الغرفة أو جمّده إذا تحتاج أكثر من يومين.","en":"Wrap the cake airtight while slightly warm, and keep it at room temperature or freeze it if you need more than two days.","tradeoff":{"ar":"التجميد يحتاج مساحة وتغليف جيد.","en":"Freezing needs space and good wrapping."}}],"verify":{"ar":"قارن قطعتين بعد يومين: مغلّفة ومكشوفة.","en":"Compare two slices after two days, wrapped and uncovered."}}],"rescue":{"ar":["ادهن الكيك بشراب سكري خفيف (سكر وماء بالتساوي) وهو دافئ.","استعمله في ترايفل أو كيك بوبس أو فتات."],"en":["Brush the cake with a light syrup (equal sugar and water) while warm.","Use it in trifle, cake pops or crumbs."]},"prevent":{"ar":["لا تخبز زيادة: العود نظيف من الوسط ويكفي.","السكر قريب من وزن الدقيق.","غلّف محكم بعد التبريد."],"en":["Do not overbake: a clean skewer from the centre is enough.","Sugar close to the flour weight.","Wrap airtight after cooling."]},"notFormula":{"ar":"إذا السكر والدهن والسوائل ضمن المعتاد، فالسبب غالباً الخبز الزايد أو التخزين.","en":"If sugar, fat and liquid are in the usual range, the cause is most likely overbaking or storage."},"unsure":{"ar":"جاوب سؤال الخبز أول، هو السبب الأكثر شيوعاً.","en":"Answer the baking question first; it is the most common cause."}},{"id":"cake-dense","category":"cake","status":"draft","reviewedBy":null,"severity":"low","rescuable":true,"symptom":{"ar":"الكيك ثقيل وكثيف وما ارتفع","en":"Cake is heavy and dense and did not rise","syn":{"ar":["الكيك ثقيل","الكيك ما انتفخ","الكيك كثيف","الكيك مطاطي","الكيك ما ارتفع"],"en":["dense cake","heavy cake","cake did not rise","gummy cake"]}},"see":{"ar":"الكيك منخفض وقوامه كثيف أو مطاطي، والفقاعات صغيرة أو قليلة.","en":"The cake is low with a dense or rubbery crumb and few, small cells."},"questions":[{"id":"butter","ar":"كيف كانت الزبدة وقت الخفق مع السكر؟","en":"How was the butter when creamed with the sugar?","options":[{"id":"cold","ar":"باردة وقاسية","en":"Cold and hard"},{"id":"soft","ar":"طرية (18 إلى 21°م تقريباً)","en":"Soft (about 18–21 °C)"},{"id":"melted","ar":"ذايبة","en":"Melted"}]},{"id":"mix","ar":"كم خلطت بعد إضافة الدقيق؟","en":"How long did you mix after adding the flour?","options":[{"id":"long","ar":"كثير، بالخلاط على سرعة","en":"A lot, with the mixer on speed"},{"id":"brief","ar":"قليل لين اختفى الدقيق","en":"Briefly until the flour disappeared"}]},{"id":"agent","ar":"عمر البيكنج باودر؟","en":"How old is the baking powder?","options":[{"id":"fresh","ar":"جديد","en":"Fresh"},{"id":"old","ar":"قديم أو مفتوح من شهور","en":"Old or open for months"}]}],"causes":[{"id":"bp-low","kind":"formula","prior":0,"evidence":"consensus","src":["S1"],"title":{"ar":"البيكنج باودر قليل","en":"Too little baking powder"},"why":{"ar":"الرافع ينتج الغاز اللي يكبّر الفقاعات. إذا قليل، يطلع الكيك منخفض وكثيف.","en":"Leavening makes the gas that grows the cells. With too little, the cake is low and dense."},"rule":{"feat":"bpFlour","when":"below","range":{"default":[3,5]},"evidence":"consensus","src":["S1"],"note":{"ar":"لا ينطبق على الكيك اللي يعتمد على خفق البيض (جينواز، شيفون بدون رافع).","en":"Does not apply to cakes leavened by whipped eggs (génoise, chiffon without powder)."}},"answers":{"agent":{"old":1}},"fixes":[{"type":"recipe","evidence":"consensus","src":["S1"],"ar":"اضبط البيكنج باودر على 4% من وزن الدقيق.","en":"Set the baking powder to 4% of the flour weight.","op":{"op":"ratio","role":"bp","base":"flour","target":0.04},"tradeoff":{"ar":"الزيادة فوق 5% تعطي طعم صابوني وهبوط.","en":"Above 5% it tastes soapy and can sink."}}],"verify":{"ar":"قِس ارتفاع الكيك في نفس القالب قبل وبعد التعديل.","en":"Measure the cake height in the same pan before and after."}},{"id":"creaming","kind":"process","prior":1,"evidence":"established","src":["S1"],"title":{"ar":"الزبدة ما انخفقت صح مع السكر","en":"Butter and sugar were not creamed properly"},"why":{"ar":"خفق الزبدة الطرية مع السكر يدخل فقاعات هواء صغيرة يكبّرها الرافع بعدين. الزبدة الباردة ما تمسك هواء، والذايبة تطيّره.","en":"Creaming soft butter with sugar traps small air cells that the leavening later enlarges. Cold butter will not hold air, and melted butter loses it."},"answers":{"butter":{"cold":3,"melted":3,"soft":-2}},"fixes":[{"type":"process","evidence":"consensus","src":["S1"],"ar":"استعمل زبدة على 18 إلى 21°م، واخفقها مع السكر 3 إلى 5 دقائق لين يفتح لونها ويخف.","en":"Use butter at 18–21 °C and cream it with the sugar for 3–5 minutes until pale and light.","tradeoff":{"ar":"الخفق الزايد جداً يعطي فقاعات كبيرة وأنفاق.","en":"Far too long gives large cells and tunnels."}}],"verify":{"ar":"قس حرارة الزبدة قبل الخفق، وقارن حجم الخليط بعد الخفق.","en":"Measure the butter before creaming and compare the batter volume after."}},{"id":"overmixed","kind":"process","prior":0,"evidence":"established","src":["S1"],"title":{"ar":"خلط زايد بعد الدقيق","en":"Overmixed after the flour"},"why":{"ar":"الخلط بعد الدقيق يطوّر الغلوتين ويطيّر الهواء، فيطلع القوام مطاطي وكثيف.","en":"Mixing after the flour develops gluten and knocks out air, giving a rubbery, dense crumb."},"answers":{"mix":{"long":3,"brief":-2}},"fixes":[{"type":"process","evidence":"consensus","src":["S1"],"ar":"أضف الدقيق على سرعة منخفضة أو باليد، وتوقّف أول ما يختفي.","en":"Add the flour on low speed or by hand, and stop as soon as it disappears.","tradeoff":{"ar":"انتبه لبقع دقيق ما اختلطت في القاع.","en":"Watch for unmixed flour pockets at the bottom."}}],"verify":{"ar":"قارن قوام قطعتين: خلط قصير وخلط طويل.","en":"Compare two batches: short and long mixing."}},{"id":"old-agent","kind":"process","prior":0,"evidence":"consensus","src":["S1"],"title":{"ar":"الرافع فقد قوته","en":"The leavening lost its strength"},"why":{"ar":"البيكنج باودر يمتص رطوبة الجو ويفقد قوته مع الوقت، خصوصاً في الجو الرطب.","en":"Baking powder picks up air moisture and loses strength over time, especially in humid climates."},"answers":{"agent":{"old":3,"fresh":-2}},"fixes":[{"type":"process","evidence":"consensus","src":["S1"],"ar":"اختبره: ملعقة صغيرة في ماء حار لازم تفوّر بقوة. خزّنه مقفل في مكان جاف.","en":"Test it: a teaspoon in hot water should fizz strongly. Store it sealed and dry.","tradeoff":{"ar":"تكلفة استبدال العبوات القديمة.","en":"Cost of replacing old tubs."}}],"verify":{"ar":"اخبز نفس الوصفة برافع جديد.","en":"Bake the same recipe with fresh leavening."}}],"rescue":{"ar":["الكيك الكثيف صالح للأكل: قطّعه طبقات رقيقة مع كريمة، أو استعمله كقاعدة."],"en":["A dense cake is still edible: slice it thin with cream, or use it as a base."]},"prevent":{"ar":["زبدة على 18 إلى 21°م.","اخفق الزبدة والسكر 3 إلى 5 دقائق.","اخلط الدقيق بأقل قدر.","رافع جديد ومخزّن جاف."],"en":["Butter at 18–21 °C.","Cream butter and sugar 3–5 minutes.","Mix the flour in minimally.","Fresh leavening, stored dry."]},"notFormula":{"ar":"إذا البيكنج باودر 3 إلى 5% من الدقيق، فالسبب غالباً حرارة الزبدة أو الخلط.","en":"If baking powder is 3–5% of the flour, the cause is most likely butter temperature or mixing."},"unsure":{"ar":"جاوب سؤال الزبدة أول.","en":"Answer the butter question first."}},{"id":"cake-dome-crack","category":"cake","status":"draft","reviewedBy":null,"severity":"low","rescuable":true,"symptom":{"ar":"الكيك تقبّب وتشقّق من فوق","en":"Cake domed and cracked on top","syn":{"ar":["الكيك قبة","الكيك تشقق من فوق","الكيك وسطه عالي","الكيك انفجر من فوق"],"en":["cake domes","cracked cake top","peaked cake","cake splits on top"]}},"see":{"ar":"الوسط مرتفع كقبة وفيه شق، والأطراف منخفضة أو قاسية.","en":"The centre rises into a dome with a crack, and the edges are low or hard."},"questions":[{"id":"oven","ar":"حرارة الفرن؟","en":"Oven temperature?","options":[{"id":"hot","ar":"180°م أو أكثر، أو فرن معروف إنه حار","en":"180 °C or more, or a known hot oven"},{"id":"mod","ar":"160 إلى 170°م","en":"160–170 °C"}]},{"id":"pan","ar":"القالب؟","en":"The pan?","options":[{"id":"deep","ar":"عميق أو صغير على الكمية","en":"Deep or small for the batter"},{"id":"ok","ar":"مناسب، والخليط حوالي نصف القالب","en":"Right size, batter about half full"}]}],"causes":[{"id":"oven-hot","kind":"process","prior":1,"evidence":"established","src":["S1"],"title":{"ar":"الفرن حار","en":"Oven too hot"},"why":{"ar":"الحرارة العالية تثبّت القشرة والأطراف بسرعة، والوسط يكمل يرتفع فيضغط ويشق القشرة.","en":"High heat sets the crust and edges fast while the centre keeps rising, so it pushes up and cracks the crust."},"answers":{"oven":{"hot":3,"mod":-2}},"fixes":[{"type":"process","evidence":"consensus","src":["S1"],"ar":"اخفض الحرارة 10 إلى 20°م وزد الوقت، أو استعمل شرائط تبريد مبللة حول القالب.","en":"Lower the oven 10–20 °C and bake longer, or wrap damp cake strips around the pan.","tradeoff":{"ar":"قشرة أفتح ووقت أطول.","en":"Paler crust and a longer bake."}}],"verify":{"ar":"اخبز نفس الوصفة على حرارة أقل وقارن استواء السطح.","en":"Bake the same recipe lower and compare how flat the top is."}},{"id":"pan-deep","kind":"equipment","prior":0,"evidence":"consensus","src":["S1"],"title":{"ar":"القالب عميق أو صغير","en":"Pan too deep or too small"},"why":{"ar":"الخليط العميق يحتاج وقت طويل عشان الحرارة توصل الوسط، فتتقبّب الأطراف المثبتة حوله.","en":"Deep batter takes long for heat to reach the centre, so it domes inside the set edges."},"answers":{"pan":{"deep":3,"ok":-2}},"fixes":[{"type":"process","evidence":"consensus","src":["S1"],"ar":"عبّي القالب للنصف أو ثلثيه، أو قسّم الخليط على قالبين، أو استعمل أنبوب حرارة في الوسط للقوالب الكبيرة.","en":"Fill the pan half to two thirds, split the batter into two pans, or use a heating core for large pans.","tradeoff":{"ar":"قوالب أكثر ووقت تجميع.","en":"More pans and assembly time."}}],"verify":{"ar":"قارن قالبين بنفس الخليط: واحد ممتلئ وواحد نصفه.","en":"Compare two pans of the same batter, one full and one half full."}},{"id":"liquid-low","kind":"formula","prior":0,"evidence":"established","src":["S1"],"title":{"ar":"الخليط ثقيل: السوائل قليلة","en":"Stiff batter: too little liquid"},"why":{"ar":"الخليط الثقيل ما ينتشر في القالب ويتماسك بسرعة، فيرتفع في الوسط كقبة.","en":"A stiff batter does not level in the pan and sets fast, so it rises into a dome."},"rule":{"feat":"waterFlour","when":"below","range":{"default":[0.8,1.4]},"evidence":"estimate","src":["S1"],"note":{"ar":"نسبة الماء المضاف للدقيق في كيك الزبدة؛ نطاق تقديري.","en":"Added water to flour in butter cakes; a working range."}},"answers":{},"fixes":[{"type":"recipe","evidence":"estimate","src":["S1"],"ar":"زد الحليب حتى تصير النسبة 1.0.","en":"Increase the milk until the ratio is 1.0.","op":{"op":"reach","role":["milk","water"],"feat":"waterFlour","target":1},"tradeoff":{"ar":"الزيادة الكبيرة تخلي الوسط رطب.","en":"Too much leaves the centre wet."}}],"verify":{"ar":"قارن انتشار الخليط في القالب قبل الخبز وشكل السطح بعده.","en":"Compare how the batter levels before baking and the top after."}}],"rescue":{"ar":["قصّ القبة بسكين مسننة واستعمل القطع كفتات.","اقلب الكيك وخلّ القاعدة المستوية فوق."],"en":["Level the dome with a serrated knife and use the trim as crumbs.","Turn the cake over so the flat base is on top."]},"prevent":{"ar":["حرارة 160 إلى 170°م لأغلب الكيك.","القالب للنصف أو الثلثين.","شرائط تبريد للقوالب الكبيرة."],"en":["160–170 °C for most cakes.","Fill pans half to two thirds.","Cake strips for large pans."]},"notFormula":{"ar":"التقبّب غالباً من الفرن أو القالب، مو من الوصفة.","en":"Doming is usually the oven or the pan, not the recipe."},"unsure":{"ar":"جاوب سؤال الفرن والقالب.","en":"Answer the oven and pan questions."}},{"id":"genoise-fail","category":"cake","status":"draft","reviewedBy":null,"severity":"medium","rescuable":true,"symptom":{"ar":"الجينواز أو الإسفنج ما ارتفع أو نزل","en":"Génoise or sponge did not rise or fell","syn":{"ar":["الجينواز ما انتفخ","الإسفنج نزل","الكيك الإسفنجي ما ارتفع","الجينواز مطاطي","الإسفنج فيه طبقة ثقيلة تحت"],"en":["genoise flat","sponge did not rise","sponge collapsed","rubbery sponge"]}},"see":{"ar":"الإسفنج منخفض أو مطاطي، وأحياناً طبقة كثيفة في القاع.","en":"The sponge is low or rubbery, sometimes with a dense layer at the base."},"questions":[{"id":"whip","ar":"كيف كان البيض بعد الخفق؟","en":"How were the eggs after whipping?","options":[{"id":"ribbon","ar":"شريطي: يرسم خط يبقى ثواني","en":"Ribbon stage: leaves a trail that holds for seconds"},{"id":"thin","ar":"منتفخ بس سايل","en":"Foamy but runny"}]},{"id":"fold","ar":"كيف أضفت الدقيق؟","en":"How did you add the flour?","options":[{"id":"gentle","ar":"منخول وعلى دفعات بالسباتولا","en":"Sifted, in stages, folded by spatula"},{"id":"rough","ar":"مرة وحدة أو بالخلاط","en":"All at once or with the mixer"}]},{"id":"butter","ar":"فيه زبدة ذايبة؟ كيف أضفتها؟","en":"Melted butter? How was it added?","options":[{"id":"none","ar":"ما فيه زبدة","en":"No butter"},{"id":"ok","ar":"دافئة، مخلوطة مع جزء من الخليط أولاً","en":"Warm, mixed into some batter first"},{"id":"bad","ar":"حارة أو مصبوبة مباشرة","en":"Hot or poured straight in"}]}],"causes":[{"id":"underwhipped","kind":"process","prior":1,"evidence":"established","src":["S1"],"title":{"ar":"البيض ما انخفق كفاية","en":"Eggs under-whipped"},"why":{"ar":"الجينواز يرتفع تقريباً بالهواء اللي في البيض المخفوق. إذا ما وصل للمرحلة الشريطية، ما فيه هواء كافي.","en":"Génoise rises almost entirely on the air in the whipped eggs. Without the ribbon stage there is not enough air."},"answers":{"whip":{"thin":3,"ribbon":-2}},"fixes":[{"type":"process","evidence":"consensus","src":["S1"],"ar":"دفّي البيض والسكر إلى حوالي 40 إلى 45°م ثم اخفق لين المرحلة الشريطية.","en":"Warm eggs and sugar to about 40–45 °C, then whip to the ribbon stage.","tradeoff":{"ar":"وقت خفق أطول.","en":"Longer whipping."}}],"verify":{"ar":"اختبار الشريط: الخط يبقى 3 إلى 5 ثواني قبل ما يختفي.","en":"Ribbon test: the trail holds 3–5 seconds before disappearing."}},{"id":"deflated","kind":"process","prior":1,"evidence":"established","src":["S1"],"title":{"ar":"الهواء طار أثناء الخلط","en":"Air knocked out while folding"},"why":{"ar":"إضافة الدقيق مرة وحدة أو بالخلاط، أو صب زبدة حارة مباشرة، يكسّر الفقاعات فينزل الخليط.","en":"Adding flour all at once or by mixer, or pouring hot butter straight in, breaks the bubbles and the batter falls."},"answers":{"fold":{"rough":3,"gentle":-2},"butter":{"bad":3,"ok":-1}},"fixes":[{"type":"process","evidence":"consensus","src":["S1"],"ar":"انخل الدقيق وأضفه على 2 إلى 3 دفعات بالسباتولا. اخلط الزبدة الدافئة مع جزء صغير من الخليط ثم أرجعه للباقي.","en":"Sift the flour and fold it in two or three additions. Mix the warm butter into a little batter first, then fold that back in.","tradeoff":{"ar":"أبطأ ويحتاج يد خفيفة.","en":"Slower and needs a light hand."}}],"verify":{"ar":"زِن كوب من الخليط قبل وبعد إضافة الدقيق: الوزن الثقيل يعني هواء أقل.","en":"Weigh a cup of batter before and after the flour: heavier means less air."}},{"id":"egg-low","kind":"formula","prior":0,"evidence":"consensus","src":["S1"],"title":{"ar":"البيض قليل مقابل الدقيق","en":"Too little egg for the flour"},"why":{"ar":"البيض هو مصدر الهواء والهيكل في الجينواز. إذا قليل مقابل الدقيق، يطلع ثقيل.","en":"Egg provides the air and the structure in génoise. Too little for the flour and it turns heavy."},"rule":{"feat":"eggFlour","when":"below","range":{"default":[1.3,2.4]},"evidence":"estimate","src":["S1"],"note":{"ar":"محسوب من وصفات جينواز كلاسيكية (البيض حوالي 1.5 إلى 2 من وزن الدقيق)؛ نطاق تقديري.","en":"Derived from classic génoise formulas (egg about 1.5–2 times the flour); a working range."}},"answers":{"whip":{"ribbon":1},"fold":{"gentle":1}},"fixes":[{"type":"recipe","evidence":"estimate","src":["S1"],"ar":"اضبط البيض على 1.6 من وزن الدقيق.","en":"Set the egg at 1.6 times the flour weight.","op":{"op":"ratio","role":["egg"],"base":"flour","target":1.6},"tradeoff":{"ar":"طعم بيض أوضح وتكلفة أعلى.","en":"More egg flavour and cost."}}],"verify":{"ar":"اخبز نفس القالب بالنسبة الجديدة وقارن الارتفاع.","en":"Bake the same pan at the new ratio and compare height."}}],"rescue":{"ar":["الجينواز المنخفض يصلح لطبقات رقيقة مشبّعة بشراب، أو رول."],"en":["A low génoise works as thin syrup-soaked layers or a roll."]},"prevent":{"ar":["خفق شريطي.","دقيق منخول على دفعات.","زبدة دافئة مخلوطة بجزء من الخليط أولاً.","اخبز فوراً."],"en":["Ribbon stage.","Sifted flour in stages.","Warm butter tempered into some batter first.","Bake at once."]},"notFormula":{"ar":"إذا البيض 1.3 إلى 2.4 من وزن الدقيق، فالسبب غالباً الخفق أو الخلط.","en":"If egg is 1.3–2.4 times the flour, the cause is most likely whipping or folding."},"unsure":{"ar":"جاوب سؤال الخفق؛ هو أهم خطوة في الجينواز.","en":"Answer the whipping question; it is the key step in génoise."}},{"id":"tart-crack","category":"dough","status":"draft","reviewedBy":null,"severity":"low","rescuable":true,"symptom":{"ar":"عجينة التارت تتفتت وتتشقق وقت الفرد","en":"Tart dough crumbles and cracks when rolling","syn":{"ar":["العجينة تتفتت","العجينة تتكسر","عجينة التارت تتشقق","العجينة ناشفة","ما تنفرد العجينة"],"en":["dough crumbles","tart dough cracks","dry pastry dough","dough breaks when rolling"]}},"see":{"ar":"العجينة تتشقق من الأطراف وتتكسر لما تفردها أو ترفعها.","en":"The dough cracks at the edges and breaks when you roll or lift it."},"questions":[{"id":"temp","ar":"حرارة العجينة وقت الفرد؟","en":"Dough temperature when rolling?","options":[{"id":"cold","ar":"باردة جداً من الثلاجة","en":"Very cold from the fridge"},{"id":"ok","ar":"باردة بس تنضغط بالإصبع","en":"Cool but gives under a finger"},{"id":"warm","ar":"طرية ودافئة","en":"Soft and warm"}]},{"id":"mix","ar":"كيف تجمعت العجينة؟","en":"How did the dough come together?","options":[{"id":"barely","ar":"بالكاد، وفيها فتات","en":"Barely, with crumbs"},{"id":"smooth","ar":"ملساء ومتماسكة","en":"Smooth and cohesive"}]}],"causes":[{"id":"too-cold","kind":"process","prior":1,"evidence":"consensus","src":["S1"],"title":{"ar":"العجينة باردة جداً","en":"Dough too cold"},"why":{"ar":"الزبدة الباردة جداً قاسية وما تنثني، فتتشقق العجينة بدل ما تنفرد.","en":"Very cold butter is hard and will not bend, so the dough cracks instead of rolling."},"answers":{"temp":{"cold":3,"ok":-1,"warm":-2}},"fixes":[{"type":"process","evidence":"consensus","src":["S1"],"ar":"خلها 5 إلى 10 دقائق على الطاولة لين تنضغط بالإصبع، واضغطها بالشوبك قبل الفرد.","en":"Leave it 5–10 minutes on the bench until it gives under a finger, and press it with the pin before rolling.","tradeoff":{"ar":"إذا دفيت زيادة تصير لزجة.","en":"Too warm and it turns sticky."}}],"verify":{"ar":"إذا انفردت بدون شقوق بعد ما دفت قليلاً، فالسبب كان البرودة.","en":"If it rolls without cracks after warming slightly, cold was the cause."}},{"id":"liquid-low","kind":"formula","prior":0,"evidence":"established","src":["S1"],"title":{"ar":"السوائل قليلة","en":"Too little liquid"},"why":{"ar":"الماء (من البيض والماء) هو اللي يربط العجينة. إذا قليل، تبقى فتات وتتشقق.","en":"Water (from egg and water) binds the dough. With too little it stays crumbly and cracks."},"rule":{"feat":"waterFlour","when":"below","range":{"default":[0.18,0.3]},"evidence":"estimate","src":["S1"],"note":{"ar":"نفس نطاق انكماش التارت: محسوب من وصفات عجينة سكرية وقصيرة شائعة.","en":"Same range as tart shrinkage: derived from common sweet and short pastry formulas."}},"answers":{"mix":{"barely":3,"smooth":-2}},"fixes":[{"type":"recipe","evidence":"estimate","src":["S1"],"ar":"زد البيض حتى تصير النسبة 0.22.","en":"Increase the egg until the ratio is 0.22.","op":{"op":"reach","role":["egg","yolk","water"],"feat":"waterFlour","target":0.22},"tradeoff":{"ar":"الزيادة الكبيرة تقوّي الغلوتين وتزيد الانكماش.","en":"Too much strengthens gluten and increases shrinkage."}}],"verify":{"ar":"إذا تجمعت العجينة ملساء بالكمية الجديدة، فالسبب كان السوائل.","en":"If the dough comes together smooth at the new amount, liquid was the cause."}},{"id":"fat-high","kind":"formula","prior":0,"evidence":"established","src":["S1"],"title":{"ar":"الدهن عالي جداً","en":"Fat too high"},"why":{"ar":"الدهن الكثير يقصّر الغلوتين لدرجة إن العجينة ما تتماسك وتتفتت.","en":"So much fat shortens the gluten that the dough will not hold together and crumbles."},"rule":{"feat":"fatFlour","when":"above","range":{"default":[0.35,0.6]},"evidence":"estimate","src":["S1"],"note":{"ar":"نفس نطاق الدهن في انكماش التارت.","en":"Same fat range as tart shrinkage."}},"answers":{"temp":{"warm":1}},"fixes":[{"type":"recipe","evidence":"estimate","src":["S1"],"ar":"قلّل الزبدة حتى تصير الدهون 0.55 من وزن الدقيق.","en":"Reduce the butter until fat is 0.55 times the flour weight.","op":{"op":"reach","role":"butter","feat":"fatFlour","target":0.55},"tradeoff":{"ar":"أقل هشاشة وطعم زبدة.","en":"Less short and less buttery."}}],"verify":{"ar":"قارن تماسك العجينة وقت الفرد بين الوصفتين.","en":"Compare how the doughs hold when rolling."}}],"rescue":{"ar":["اضغط الشقوق بالأصابع أو رقّع بقطع عجينة، والقاعدة تنخبز عادي.","إذا العجينة فتات: أضف ملعقة صفار أو ماء بارد واعجن خفيف."],"en":["Press cracks closed or patch with dough scraps; the shell bakes fine.","If it is crumbs, add a spoon of yolk or cold water and knead lightly."]},"prevent":{"ar":["العجينة باردة بس تنضغط وقت الفرد.","افرد بين ورقتين.","السوائل والدهن ضمن النطاق."],"en":["Dough cool but pliable when rolling.","Roll between two sheets.","Liquid and fat within range."]},"notFormula":{"ar":"إذا السوائل والدهن ضمن النطاق، فالسبب غالباً حرارة العجينة.","en":"If liquid and fat are within range, the cause is most likely dough temperature."},"unsure":{"ar":"جاوب سؤال الحرارة.","en":"Answer the temperature question."}},{"id":"cookies-spread","category":"dough","status":"draft","reviewedBy":null,"severity":"low","rescuable":false,"symptom":{"ar":"الكوكيز انتشر وصار رقيق","en":"Cookies spread and turned thin","syn":{"ar":["الكوكيز انتشر","الكوكيز صار رقيق","الكوكيز سايح","الكوكيز التصق ببعض","الكوكيز مسطح"],"en":["cookies spread","flat cookies","thin cookies","cookies ran together"]}},"see":{"ar":"الكوكيز ينتشر كثير في الصينية ويصير رقيق ومقرمش من الأطراف.","en":"The cookies spread a lot on the tray and turn thin with crisp edges."},"questions":[{"id":"butter","ar":"كيف كانت الزبدة؟","en":"How was the butter?","options":[{"id":"melted","ar":"ذايبة أو طرية جداً","en":"Melted or very soft"},{"id":"soft","ar":"طرية عادية","en":"Normally soft"}]},{"id":"chill","ar":"برّدت العجينة قبل الخبز؟","en":"Did you chill the dough before baking?","options":[{"id":"yes","ar":"نعم، ساعة أو أكثر","en":"Yes, an hour or more"},{"id":"no","ar":"لا","en":"No"}]},{"id":"tray","ar":"الصينية؟","en":"The tray?","options":[{"id":"warm","ar":"استعملتها وهي حارة من الدفعة السابقة","en":"Used it warm from the last batch"},{"id":"cool","ar":"باردة","en":"Cool"}]}],"causes":[{"id":"butter-warm","kind":"process","prior":1,"evidence":"established","src":["S1"],"title":{"ar":"الزبدة أو العجينة دافئة","en":"Butter or dough too warm"},"why":{"ar":"الدهن الطري يذوب بسرعة في الفرن قبل ما تتماسك العجينة، فتنتشر. التبريد يبطئ الذوبان. في مطابخ الخليج الحارة هذا السبب الأول.","en":"Soft fat melts quickly in the oven before the dough sets, so it spreads. Chilling slows the melt. In hot Gulf kitchens this is the first cause."},"answers":{"butter":{"melted":3,"soft":-1},"chill":{"no":2,"yes":-2},"tray":{"warm":2,"cool":-1}},"fixes":[{"type":"process","evidence":"consensus","src":["S1"],"ar":"برّد العجينة ساعة على الأقل، واخبز على صينية باردة.","en":"Chill the dough at least an hour, and bake on a cool tray.","tradeoff":{"ar":"يأخر الإنتاج.","en":"Delays production."}}],"verify":{"ar":"اخبز كرتين من نفس العجينة: مبرّدة وغير مبرّدة، وقِس القطر.","en":"Bake two balls from the same dough, chilled and not, and measure the diameter."}},{"id":"sugar-high","kind":"formula","prior":0,"evidence":"established","src":["S1"],"title":{"ar":"السكر عالي مقابل الدقيق","en":"Sugar too high for the flour"},"why":{"ar":"السكر يذوب في الفرن ويسيّل العجينة، فكل ما زاد زاد الانتشار.","en":"Sugar dissolves in the oven and loosens the dough, so more sugar means more spread."},"rule":{"feat":"sugarFlour","when":"above","range":{"default":[0.6,1.2]},"evidence":"estimate","src":["S1"],"note":{"ar":"محسوب من وصفات كوكيز الشوكولاتة الشائعة (السكر الكلي حوالي 0.8 إلى 1.1 من الدقيق)؛ نطاق تقديري.","en":"Derived from common chocolate-chip cookie formulas (total sugar about 0.8–1.1 of the flour); a working range."}},"answers":{"chill":{"yes":1}},"fixes":[{"type":"recipe","evidence":"estimate","src":["S1"],"ar":"قلّل السكر إلى وزن الدقيق.","en":"Reduce the sugar to the flour weight.","op":{"op":"ratio","role":["sugar"],"base":"flour","target":1},"tradeoff":{"ar":"أقل حلاوة وأطرى وأقل تلوين.","en":"Less sweet, softer and paler."}}],"verify":{"ar":"قِس قطر الكوكيز بعد الخبز بين الوصفتين.","en":"Measure the baked diameter of both recipes."}},{"id":"fat-high","kind":"formula","prior":0,"evidence":"established","src":["S1"],"title":{"ar":"الدهن عالي مقابل الدقيق","en":"Fat too high for the flour"},"why":{"ar":"الدهن الزايد يذوب ويسيّح العجينة.","en":"Excess fat melts and makes the dough run."},"rule":{"feat":"fatFlour","when":"above","range":{"default":[0.4,0.85]},"evidence":"estimate","src":["S1"],"note":{"ar":"محسوب من وصفات كوكيز الشوكولاتة الشائعة (يشمل دهن البيض)؛ نطاق تقديري.","en":"Derived from common chocolate-chip cookie formulas (includes egg fat); a working range."}},"answers":{"butter":{"soft":1}},"fixes":[{"type":"recipe","evidence":"estimate","src":["S1"],"ar":"قلّل الزبدة حتى تصير الدهون 0.75 من وزن الدقيق.","en":"Reduce the butter until fat is 0.75 times the flour weight.","op":{"op":"reach","role":"butter","feat":"fatFlour","target":0.75},"tradeoff":{"ar":"أقل طراوة وطعم زبدة.","en":"Less tender and buttery."}}],"verify":{"ar":"قارن القطر والسماكة بعد الخبز.","en":"Compare diameter and thickness after baking."}}],"rescue":{"ar":["الكوكيز المنتشر ما يرجع، بس تقدر تقصّه بقطّاعة دائرية وهو حار، أو تفتته لقاعدة تشيز كيك."],"en":["Spread cookies do not recover, but you can trim them with a round cutter while hot, or crumble them for a cheesecake base."]},"prevent":{"ar":["برّد العجينة ساعة.","صينية باردة لكل دفعة.","لا تذوّب الزبدة إلا إذا الوصفة تطلب."],"en":["Chill the dough an hour.","A cool tray each batch.","Do not melt the butter unless the recipe says so."]},"notFormula":{"ar":"إذا السكر والدهن ضمن النطاق، فالسبب غالباً حرارة العجينة أو الصينية.","en":"If sugar and fat are within range, the cause is most likely dough or tray temperature."},"unsure":{"ar":"جاوب سؤال الزبدة والتبريد.","en":"Answer the butter and chilling questions."}},{"id":"choux-crack","category":"choux","status":"draft","reviewedBy":null,"severity":"low","rescuable":true,"symptom":{"ar":"الشو أو الإكلير يتشقق بشكل غير منتظم","en":"Choux or éclairs crack unevenly","syn":{"ar":["الشو يتشقق","الإكلير مشقق","الشو شكله مو منتظم","الإكلير انفجر من الجنب"],"en":["choux cracks","cracked eclairs","uneven choux","eclairs burst on the side"]}},"see":{"ar":"شقوق عميقة وغير منتظمة على السطح أو الجوانب، والشكل مو متساوي.","en":"Deep, irregular cracks on the top or sides, and uneven shapes."},"questions":[{"id":"paste","ar":"قوام العجينة قبل التشكيل؟","en":"Paste consistency before piping?","options":[{"id":"stiff","ar":"ناشفة وثقيلة وما تنزل من الملعقة","en":"Dry and heavy, will not drop from the spatula"},{"id":"v","ar":"تنزل على شكل V وتمسك","en":"Falls in a V and holds"}]},{"id":"oven","ar":"حرارة الفرن في البداية؟","en":"Oven temperature at the start?","options":[{"id":"hot","ar":"عالية (200°م أو أكثر)","en":"High (200 °C or more)"},{"id":"mod","ar":"متوسطة","en":"Moderate"}]},{"id":"top","ar":"استعملت كراكلان أو سكّر بودرة أو طلاء؟","en":"Did you use craquelin, icing sugar or a wash?","options":[{"id":"none","ar":"لا شي","en":"Nothing"},{"id":"craq","ar":"كراكلان","en":"Craquelin"}]}],"causes":[{"id":"paste-dry","kind":"formula","prior":0,"evidence":"consensus","src":["S1"],"title":{"ar":"العجينة ناشفة: البيض قليل","en":"Paste too dry: too little egg"},"why":{"ar":"العجينة الناشفة ما تتمدد بمرونة مع البخار، فتنفجر وتتشقق.","en":"A dry paste does not stretch with the steam, so it bursts and cracks."},"rule":{"feat":"eggFlour","when":"below","range":{"default":[1.5,2]},"evidence":"consensus","src":["S1"]},"answers":{"paste":{"stiff":3,"v":-2}},"fixes":[{"type":"recipe","evidence":"consensus","src":["S1"],"ar":"ارفع البيض إلى 1.7 من وزن الدقيق، وأضفه تدريجياً لين شكل V.","en":"Raise the egg to 1.7 times the flour weight, adding it gradually until it forms a V.","op":{"op":"ratio","role":["egg"],"base":"flour","target":1.7},"tradeoff":{"ar":"إذا زاد كثير، تنتشر العجينة وتهبط.","en":"Too much and the paste spreads and collapses."}}],"verify":{"ar":"اختبار الملعقة: شكل V يمسك، والقطع تنتفخ بسطح أنعم.","en":"Spatula test: the V holds and pieces puff with a smoother surface."}},{"id":"oven-hot","kind":"process","prior":1,"evidence":"consensus","src":["S1"],"title":{"ar":"حرارة بداية عالية","en":"Starting heat too high"},"why":{"ar":"الحرارة العالية تثبّت السطح بسرعة والبخار يكمل يضغط من الداخل، فتنفجر الجوانب.","en":"High heat sets the surface fast while steam keeps pushing from inside, so the sides burst."},"answers":{"oven":{"hot":3,"mod":-2}},"fixes":[{"type":"process","evidence":"consensus","src":["S1"],"ar":"ابدأ بحرارة متوسطة (حوالي 170 إلى 180°م حسب الفرن)، أو بفرن مطفي ساخن للأفران الحرارية، ثم ارفعها.","en":"Start moderate (about 170–180 °C depending on the oven), or in a hot switched-off convection oven, then raise it.","tradeoff":{"ar":"انتفاخ أبطأ ووقت أطول.","en":"Slower puff and a longer bake."}}],"verify":{"ar":"اخبز صينيتين على حرارتين وقارن السطح.","en":"Bake two trays at two temperatures and compare the surface."}},{"id":"no-craquelin","kind":"process","prior":0,"evidence":"consensus","src":["S1"],"title":{"ar":"ما فيه غطاء ينظّم التشقق","en":"No topping to even out the cracking"},"why":{"ar":"الكراكلان (قرص رقيق من زبدة وسكر ودقيق) يغطي الشو فيتمدد بانتظام ويطلع الشكل دائري متساوي.","en":"Craquelin (a thin disc of butter, sugar and flour) covers the choux so it expands evenly into a round, regular shape."},"answers":{"top":{"none":2,"craq":-2}},"fixes":[{"type":"process","evidence":"consensus","src":["S1"],"ar":"حط قرص كراكلان رقيق (1 إلى 2 ملم) على كل قطعة، أو رش سكر بودرة خفيف على الإكلير.","en":"Place a thin craquelin disc (1–2 mm) on each piece, or dust éclairs lightly with icing sugar.","tradeoff":{"ar":"خطوة إضافية وطعم أحلى.","en":"An extra step and a sweeter taste."}}],"verify":{"ar":"قارن قطع بكراكلان وبدون.","en":"Compare pieces with and without craquelin."}}],"rescue":{"ar":["الشو المشقق صالح للحشو والتغطية بالفوندان أو الشوكولاتة."],"en":["Cracked choux can still be filled and covered with fondant or chocolate."]},"prevent":{"ar":["البيض حتى شكل V.","حرارة بداية متوسطة.","كراكلان للشو الدائري."],"en":["Egg until a V forms.","Moderate starting heat.","Craquelin for round choux."]},"notFormula":{"ar":"إذا البيض 1.5 إلى 2 من الدقيق، فالسبب غالباً الفرن أو التشكيل.","en":"If egg is 1.5–2 times the flour, the cause is most likely the oven or piping."},"unsure":{"ar":"جاوب سؤال قوام العجينة.","en":"Answer the paste question."}},{"id":"cheesecake-crack","category":"cake","status":"draft","reviewedBy":null,"severity":"low","rescuable":true,"symptom":{"ar":"التشيز كيك تشقق من فوق","en":"Cheesecake cracked on top","syn":{"ar":["التشيز كيك تشقق","التشيزكيك مشقق","شق في وسط التشيز كيك","التشيز كيك انفتح"],"en":["cheesecake cracked","cracks in cheesecake","cheesecake split on top"]}},"see":{"ar":"شق في الوسط أو حول الأطراف، وأحياناً السطح منتفخ ثم نزل.","en":"A crack in the centre or around the edge, sometimes after the top puffed and fell."},"questions":[{"id":"mix","ar":"كيف خلطت الخليط؟","en":"How did you mix the batter?","options":[{"id":"fast","ar":"سرعة عالية أو بالمضرب السلكي","en":"High speed or the whisk"},{"id":"slow","ar":"سرعة منخفضة بالمضرب المسطح","en":"Low speed with the paddle"}]},{"id":"bake","ar":"كيف خبزته؟","en":"How did you bake it?","options":[{"id":"bain","ar":"حمام مائي على 140 إلى 150°م","en":"Water bath at 140–150 °C"},{"id":"hot","ar":"بدون حمام مائي أو حرارة أعلى","en":"No water bath or hotter"}]},{"id":"cool","ar":"كيف برّدته؟","en":"How did you cool it?","options":[{"id":"slow","ar":"في الفرن المطفي والباب مفتوح قليلاً","en":"In the switched-off oven, door ajar"},{"id":"fast","ar":"طلّعته مباشرة للجو أو الثلاجة","en":"Straight out to the room or fridge"}]}],"causes":[{"id":"air","kind":"process","prior":0,"evidence":"consensus","src":["S1"],"title":{"ar":"هواء زايد في الخليط","en":"Too much air in the batter"},"why":{"ar":"الخلط السريع يدخل هواء، فينتفخ الخليط في الفرن ثم ينزل ويتشقق.","en":"Fast mixing whips in air, so the batter puffs in the oven, then falls and cracks."},"answers":{"mix":{"fast":3,"slow":-2}},"fixes":[{"type":"process","evidence":"consensus","src":["S1"],"ar":"اخلط على سرعة منخفضة بالمضرب المسطح، والجبن على حرارة الغرفة، ولا تخلط زيادة بعد البيض.","en":"Mix on low speed with the paddle, with the cheese at room temperature, and do not overmix after the eggs.","tradeoff":{"ar":"يحتاج تحضير الجبن مسبقاً.","en":"Needs the cheese softened ahead."}}],"verify":{"ar":"إذا ما انتفخ السطح في الفرن، فالهواء كان السبب.","en":"If the top no longer puffs in the oven, air was the cause."}},{"id":"oven","kind":"process","prior":1,"evidence":"consensus","src":["S2","S1"],"title":{"ar":"الحرارة عالية أو انخبز زيادة","en":"Too hot or overbaked"},"why":{"ar":"التشيز كيك كاسترد: إذا سخن زيادة يتجمد البيض بقوة وينكمش ويتشقق. الحمام المائي يحمي الأطراف.","en":"Cheesecake is a custard: overheated egg sets hard, shrinks and cracks. A water bath protects the edges."},"answers":{"bake":{"hot":3,"bain":-2}},"fixes":[{"type":"process","evidence":"consensus","src":["S1"],"ar":"اخبز في حمام مائي على 140 إلى 150°م، وطلّعه لما الوسط يهتز قليلاً (حوالي 65 إلى 70°م في الوسط).","en":"Bake in a water bath at 140–150 °C and stop when the centre still wobbles slightly (about 65–70 °C inside).","tradeoff":{"ar":"وقت أطول ومساحة فرن.","en":"Longer time and oven space."}}],"verify":{"ar":"قِس حرارة الوسط عند الإخراج وسجّلها.","en":"Log the centre temperature at removal."}},{"id":"fast-cool","kind":"process","prior":0,"evidence":"consensus","src":["S1"],"title":{"ar":"تبريد سريع","en":"Cooled too fast"},"why":{"ar":"التبريد المفاجئ يخلي السطح ينكمش أسرع من الداخل، وإذا لاصق في القالب يتشقق.","en":"Sudden cooling shrinks the top faster than the inside; if it sticks to the pan it cracks."},"answers":{"cool":{"fast":3,"slow":-2}},"fixes":[{"type":"process","evidence":"consensus","src":["S1"],"ar":"برّده ساعة في الفرن المطفي والباب مفتوح قليلاً، ومرّر سكين حول القالب.","en":"Cool it an hour in the switched-off oven with the door ajar, and run a knife around the pan.","tradeoff":{"ar":"يشغل الفرن ساعة إضافية.","en":"Ties up the oven an extra hour."}}],"verify":{"ar":"قارن تشيز كيك مبرّد ببطء بآخر مبرّد بسرعة.","en":"Compare one cooled slowly with one cooled fast."}},{"id":"egg-high","kind":"formula","prior":0,"evidence":"consensus","src":["S2"],"title":{"ar":"البيض عالي مقابل الجبن","en":"Egg too high for the cheese"},"why":{"ar":"البيض الكثير يعطي قوام إسفنجي ينتفخ وينكمش أكثر، فيتشقق.","en":"Lots of egg gives a spongy texture that puffs and shrinks more, so it cracks."},"rule":{"feat":"eggCheese","when":"above","range":{"default":[0.2,0.45]},"evidence":"consensus","src":["S2"],"note":{"ar":"نفس الحد المستعمل في قواعد المنصة (البيض فوق 45% من وزن الجبن).","en":"The same limit as the platform's rules (egg above 45% of the cheese weight)."}},"answers":{"mix":{"slow":1}},"fixes":[{"type":"recipe","evidence":"consensus","src":["S2"],"ar":"اضبط البيض على 35% من وزن الجبن.","en":"Set the egg at 35% of the cheese weight.","op":{"op":"ratio","role":["egg","yolk","white"],"base":"cheese","target":0.35},"tradeoff":{"ar":"قوام أكثف وأثقل.","en":"A denser, heavier texture."}}],"verify":{"ar":"اخبز الوصفة المعدّلة بنفس الطريقة وقارن السطح.","en":"Bake the adjusted recipe the same way and compare the top."}}],"rescue":{"ar":["غطّ الشق بطبقة كريمة حامضة أو صوص فاكهة أو جاناش.","التشيز كيك المشقق صالح للأكل عادي."],"en":["Cover the crack with a sour-cream layer, fruit sauce or ganache.","A cracked cheesecake is perfectly edible."]},"prevent":{"ar":["جبن بحرارة الغرفة وخلط بطيء.","حمام مائي 140 إلى 150°م.","طلّعه والوسط يهتز.","تبريد بطيء في الفرن."],"en":["Room-temperature cheese, slow mixing.","Water bath at 140–150 °C.","Remove while the centre wobbles.","Cool slowly in the oven."]},"notFormula":{"ar":"إذا البيض تحت 45% من الجبن، فالسبب غالباً الخلط أو الحرارة أو التبريد.","en":"If egg is below 45% of the cheese, the cause is most likely mixing, heat or cooling."},"unsure":{"ar":"جاوب الأسئلة الثلاثة؛ أغلب الأسباب من الطريقة.","en":"Answer all three questions; most causes are method."}},{"id":"freeze-thaw-weep","category":"industrial","status":"draft","reviewedBy":null,"severity":"medium","rescuable":false,"symptom":{"ar":"الكريمة أو الحشوة تطرد ماء بعد التجميد والذوبان","en":"Cream or filling weeps water after freezing and thawing","syn":{"ar":["الحشوة طلعت ماي بعد التجميد","الكريمة تفصل بعد الفريزر","الكيك المجمد يطلع ماء","الحشوة صارت إسفنجية بعد التجميد","ماء في قاعدة الكيكة بعد الذوبان"],"en":["weeping after thawing","filling separates after freezing","syneresis after freezing","watery frozen cake"]}},"see":{"ar":"بعد الذوبان يطلع ماء من الحشوة أو الكريمة، ويصير القوام إسفنجي أو مقطّع، والقاعدة تتشرب.","en":"After thawing, water seeps from the filling or cream, the texture turns spongy or curdled, and the base soaks up the liquid."},"questions":[{"id":"freeze","ar":"كيف تجمّد؟","en":"How do you freeze?","options":[{"id":"blast","ar":"مجمّد سريع (بلاست) ثم تخزين","en":"Blast freezer, then storage"},{"id":"normal","ar":"فريزر عادي مباشرة","en":"A normal freezer directly"}]},{"id":"thaw","ar":"كيف تذوّب؟","en":"How do you thaw?","options":[{"id":"fridge","ar":"في الثلاجة ببطء","en":"Slowly in the fridge"},{"id":"room","ar":"على حرارة الغرفة","en":"At room temperature"}]},{"id":"thick","ar":"وش يمسك الحشوة؟","en":"What sets the filling?","options":[{"id":"native","ar":"نشا ذرة عادي أو دقيق","en":"Ordinary cornstarch or flour"},{"id":"modified","ar":"نشا معدّل للتجميد","en":"Freeze-thaw modified starch"},{"id":"gel","ar":"جيلاتين أو كريمة فقط","en":"Gelatine or cream only"}]}],"causes":[{"id":"native-starch","kind":"formula","prior":0,"evidence":"established","src":["S7"],"title":{"ar":"نشا عادي ما يتحمل التجميد","en":"Native starch does not tolerate freezing"},"why":{"ar":"جل النشا العادي يرجع يتبلور مع البرودة والتجميد فيعصر الماء منه. النشا المعدّل للتجميد مصنوع عشان ما يطرد الماء.","en":"A native starch gel re-crystallises in the cold and squeezes out water. Freeze-thaw modified starch is made not to weep."},"answers":{"thick":{"native":3,"modified":-2,"gel":-1}},"fixes":[{"type":"process","evidence":"established","src":["S7"],"ar":"استعمل نشا معدّل مخصص للتجميد والذوبان (اسأل مورّدك عن نوع «freeze-thaw stable») بنفس الكمية تقريباً، وجرّبه على دفعة صغيرة.","en":"Use a freeze-thaw stable modified starch (ask your supplier) at about the same amount, and trial it on a small batch.","tradeoff":{"ar":"أغلى، وقوامه وطعمه يختلفان قليلاً عن الكلاسيكي.","en":"Costs more, and its texture and taste differ slightly from the classic."}}],"verify":{"ar":"جمّد وذوّب عيّنتين (عادي ومعدّل) بنفس الطريقة، وزِن الماء اللي يطلع بعد 24 ساعة.","en":"Freeze and thaw two samples (native and modified) the same way and weigh the water released after 24 hours."}},{"id":"slow-freeze","kind":"process","prior":1,"evidence":"established","src":["S8","S3"],"title":{"ar":"تجميد بطيء يكوّن بلورات ثلج كبيرة","en":"Slow freezing forms large ice crystals"},"why":{"ar":"التجميد البطيء يكوّن بلورات ثلج كبيرة تمزّق القوام، ولما تذوب يطلع الماء. التجميد السريع يعطي بلورات صغيرة.","en":"Slow freezing grows large ice crystals that tear the structure, so water escapes on thawing. Fast freezing makes small crystals."},"answers":{"freeze":{"normal":3,"blast":-2}},"fixes":[{"type":"process","evidence":"consensus","src":["S3"],"ar":"جمّد بمجمّد سريع حتى يوصل القلب −18°م بأسرع وقت، ثم انقله للتخزين، وغلّف محكم.","en":"Blast freeze until the core reaches −18 °C as fast as possible, then move to storage, wrapped airtight.","tradeoff":{"ar":"يحتاج مجمّد سريع وكهرباء أكثر.","en":"Needs a blast freezer and more power."}}],"verify":{"ar":"قِس حرارة القلب بالميزان وسجّل الوقت حتى −18°م.","en":"Probe the core and log the time to reach −18 °C."}},{"id":"thaw-cycle","kind":"process","prior":0,"evidence":"established","src":["S8"],"title":{"ar":"ذوبان سريع أو تقلب الحرارة","en":"Fast thawing or temperature swings"},"why":{"ar":"الذوبان على حرارة الغرفة، أو فتح الفريزر كثير، أو النقل بدون تبريد، يذوّب البلورات ويعيد تجميدها أكبر، فيزيد الماء المفصول.","en":"Thawing at room temperature, frequent freezer opening or unrefrigerated transport melt and refreeze crystals larger, so more water separates."},"answers":{"thaw":{"room":3,"fridge":-2}},"fixes":[{"type":"process","evidence":"consensus","src":["S3"],"ar":"ذوّب في الثلاجة (2 إلى 5°م) 8 إلى 12 ساعة، وحافظ على سلسلة التبريد بدون انقطاع.","en":"Thaw in the fridge (2–5 °C) for 8–12 hours and keep the cold chain unbroken.","tradeoff":{"ar":"تخطيط مسبق للطلبات.","en":"Orders must be planned ahead."}}],"verify":{"ar":"ذوّب قطعتين: ثلاجة وحرارة غرفة، وقارن الماء.","en":"Thaw two pieces, fridge and room temperature, and compare the water."}},{"id":"sugar-low","kind":"formula","prior":0,"evidence":"established","src":["S8"],"title":{"ar":"السكر قليل مقابل الماء","en":"Too little sugar for the water"},"why":{"ar":"السكر يخفض نقطة التجمد ويمسك الماء، فيقل الثلج المتكوّن. الحشوة القليلة السكر يتجمد أغلب مائها.","en":"Sugar lowers the freezing point and binds water, so less ice forms. In a low-sugar filling most of the water freezes."},"rule":{"feat":"sugarWater","when":"below","range":{"default":[0.3,1.5]},"evidence":"estimate","src":["S8"],"note":{"ar":"حد تقديري للحشوات المجمّدة؛ يحتاج اعتماد مراجع.","en":"A working limit for frozen fillings; pending review."}},"answers":{"thick":{"gel":1}},"fixes":[{"type":"recipe","evidence":"estimate","src":["S8"],"ar":"زد السكر حتى تصير السكريات 0.4 من وزن الماء، أو بدّل جزءاً منه بجلوكوز أو دكستروز لحلاوة أقل.","en":"Increase sugar until sugars are 0.4 times the water, or use glucose or dextrose for part of it to keep sweetness lower.","op":{"op":"reach","role":"sugar","feat":"sugarWater","target":0.4},"tradeoff":{"ar":"أحلى، وقوام أطرى في الفريزر.","en":"Sweeter, and softer in the freezer."}}],"verify":{"ar":"جمّد وذوّب عيّنة بالنسبة الجديدة وقارن الماء المفصول.","en":"Freeze and thaw a sample at the new ratio and compare the water released."}}],"rescue":{"ar":["الحشوة اللي طردت ماء ما ترجع. لا تعيد تجميدها.","إذا القاعدة تشربت قليلاً: قدّمها نفس اليوم أو استعملها بشكل ثاني."],"en":["A filling that has wept does not recover; do not refreeze it.","If the base soaked a little, serve it the same day or repurpose it."],"safety":{"ar":"لا تعيد تجميد منتج ذاب فيه كريمة أو بيض. ذوّبه في الثلاجة واستعمله خلال يوم إلى يومين.","en":"Do not refreeze a thawed product containing cream or egg. Thaw it in the fridge and use within one to two days.","src":["S3"]}},"prevent":{"ar":["نشا معدّل للتجميد.","تجميد سريع حتى −18°م في القلب.","ذوبان في الثلاجة.","سلسلة تبريد بدون انقطاع."],"en":["Freeze-thaw modified starch.","Fast freezing to −18 °C core.","Thaw in the fridge.","An unbroken cold chain."]},"notFormula":{"ar":"إذا تستعمل نشا معدّل والسكر كافي، فالسبب غالباً طريقة التجميد أو الذوبان.","en":"If you use modified starch and enough sugar, the cause is most likely how you freeze or thaw."},"unsure":{"ar":"جاوب سؤال نوع النشا أول.","en":"Answer the starch question first."}},{"id":"mould-fast","category":"industrial","status":"draft","reviewedBy":null,"severity":"high","rescuable":false,"symptom":{"ar":"المنتج يعفّن بسرعة","en":"The product moulds quickly","syn":{"ar":["الكيك عفّن","طلع عفن","الحلى يخرب بسرعة","نقاط خضراء على الكيك","الصلاحية قصيرة","المنتج خرب قبل وقته"],"en":["cake goes mouldy","mould on product","short shelf life","green spots on cake"]}},"see":{"ar":"بقع عفن (بيضاء أو خضراء أو سوداء) تطلع قبل الصلاحية المتوقعة، غالباً على السطح أو داخل العبوة.","en":"Mould spots (white, green or black) appear before the expected shelf life, often on the surface or inside the pack."},"questions":[{"id":"pack","ar":"متى تغلّف المنتج؟","en":"When do you pack the product?","options":[{"id":"warm","ar":"وهو دافئ","en":"While still warm"},{"id":"cool","ar":"بعد ما يبرد كاملاً","en":"After it has fully cooled"}]},{"id":"store","ar":"وين يتخزّن ويتعرض؟","en":"Where is it stored and displayed?","options":[{"id":"room","ar":"حرارة الغرفة أو مكان دافئ","en":"Room temperature or a warm place"},{"id":"cold","ar":"مبرّد","en":"Chilled"}]},{"id":"where","ar":"وين يطلع العفن أول؟","en":"Where does the mould appear first?","options":[{"id":"surface","ar":"على السطح أو جوا العبوة","en":"On the surface or inside the pack"},{"id":"inside","ar":"داخل الحشوة أو بين الطبقات","en":"Inside the filling or between layers"}]}],"causes":[{"id":"packed-warm","kind":"process","prior":1,"evidence":"established","src":["S3"],"title":{"ar":"التغليف وهو دافئ","en":"Packed while warm"},"why":{"ar":"المنتج الدافئ يطلع بخار يتكثف داخل العبوة، فيرطّب السطح ويسرّع العفن.","en":"A warm product releases steam that condenses inside the pack, wetting the surface and speeding mould."},"answers":{"pack":{"warm":3,"cool":-2},"where":{"surface":1}},"fixes":[{"type":"process","evidence":"established","src":["S3"],"ar":"برّد المنتج كاملاً في مكان نظيف قبل التغليف، وتأكد ما في قطرات داخل العبوة.","en":"Cool the product fully in a clean area before packing, and check there are no droplets inside the pack.","tradeoff":{"ar":"يحتاج مساحة ووقت تبريد.","en":"Needs cooling space and time."}}],"verify":{"ar":"غلّف دفعتين: وحدة دافئة ووحدة باردة، وسجّل يوم ظهور العفن.","en":"Pack two batches, one warm and one cool, and log the day mould appears."}},{"id":"storage-warm","kind":"process","prior":1,"evidence":"established","src":["S3","S8"],"title":{"ar":"التخزين دافئ ورطب","en":"Warm, humid storage"},"why":{"ar":"العفن ينمو أسرع بكثير في الحرارة والرطوبة. حرارة الغرفة في الخليج (25 إلى 30°م) تقصّر الصلاحية بوضوح مقارنة بالتبريد.","en":"Mould grows much faster in warmth and humidity. Gulf room temperatures (25–30 °C) clearly shorten shelf life compared with chilling."},"answers":{"store":{"room":3,"cold":-2}},"fixes":[{"type":"process","evidence":"consensus","src":["S3"],"ar":"خزّن المنتجات الطرية والمحشية مبرّدة، وحدد الصلاحية بتجربة تخزين على نفس الظروف.","en":"Keep soft and filled products chilled, and set the shelf life by a storage trial under the same conditions.","tradeoff":{"ar":"تكلفة تبريد، والتبريد يسرّع تيبّس الكيك.","en":"Cooling cost, and chilling speeds cake staling."}}],"verify":{"ar":"خزّن عيّنات على حرارة الغرفة ومبرّدة، وافحصها يومياً.","en":"Store samples at room temperature and chilled, and check them daily."}},{"id":"hygiene","kind":"equipment","prior":0,"evidence":"established","src":["S3"],"title":{"ar":"تلوّث بعد الخبز","en":"Contamination after baking"},"why":{"ar":"الخبز يقتل جراثيم العفن، فالعفن غالباً يجي بعد الخبز: من الهواء، أو أسطح التقطيع، أو الأيدي، أو الحشوات والفاكهة الطازجة.","en":"Baking kills mould spores, so mould usually arrives afterwards: from air, cutting surfaces, hands, or fresh fillings and fruit."},"answers":{"where":{"inside":2,"surface":1}},"fixes":[{"type":"process","evidence":"consensus","src":["S3"],"ar":"نظّف وعقّم أسطح التبريد والتقطيع والأدوات، واستعمل قفازات، وغطِّ المنتج أثناء التبريد.","en":"Clean and sanitise cooling and cutting surfaces and tools, use gloves, and cover the product while it cools.","tradeoff":{"ar":"وقت ومواد تنظيف.","en":"Cleaning time and materials."}}],"verify":{"ar":"قارن دفعة بعد تنظيف كامل للأسطح بدفعة عادية.","en":"Compare a batch made after a full surface clean with a normal batch."}},{"id":"water-high","kind":"formula","prior":0,"evidence":"established","src":["S8"],"title":{"ar":"الماء الحر عالي (السكر قليل مقابل الماء)","en":"High free water (little sugar for the water)"},"why":{"ar":"كل ما كان السكر قليل مقابل الماء، ارتفع نشاط الماء وصار المنتج بيئة أسهل للعفن.","en":"The less sugar for the water, the higher the water activity and the easier it is for mould."},"rule":{"feat":"sugarWater","when":"below","range":{"default":[0.8,2]},"evidence":"estimate","src":["S8"],"note":{"ar":"مؤشر تقريبي لنشاط الماء فقط. تقدير نشاط الماء الكامل موجود في تبويب «القيم والصلاحية» للوصفة.","en":"Only a rough proxy for water activity; the full water-activity estimate is in the recipe's Nutrition and shelf-life tab."}},"answers":{"store":{"room":1}},"fixes":[{"type":"recipe","evidence":"estimate","src":["S8"],"ar":"زد السكر حتى تصير السكريات 0.9 من وزن الماء، أو بدّل جزءاً منه بسكر محوّل أو جلسرين يمسك الماء أكثر.","en":"Increase sugar until sugars are 0.9 times the water, or swap part for invert sugar or glycerol, which bind water better.","op":{"op":"reach","role":"sugar","feat":"sugarWater","target":0.9},"tradeoff":{"ar":"أحلى، وقد يتغيّر القوام واللون.","en":"Sweeter, and texture and colour may change."}}],"verify":{"ar":"قارن تقدير نشاط الماء في المنصة قبل وبعد، ثم أكّد بتجربة تخزين.","en":"Compare the platform's water-activity estimate before and after, then confirm with a storage trial."}}],"rescue":{"ar":["المنتج الطري اللي ظهر فيه عفن: تخلّص منه كاملاً، ولا تقطع الجزء المعفّن فقط، لأن العفن يمتد داخل المنتجات الطرية."],"en":["A soft product with visible mould must be discarded entirely; do not just cut off the mouldy part, because mould spreads inside soft foods."],"safety":{"ar":"لا تبيع أي منتج فيه عفن. افحص الدفعة كاملة، ونظّف مكان التخزين قبل الدفعة الجاية.","en":"Never sell a product with mould. Check the whole batch and clean the storage area before the next batch.","src":["S3"]}},"prevent":{"ar":["برّد كاملاً قبل التغليف.","تخزين مبرّد للمنتجات الطرية.","تعقيم أسطح التقطيع والتبريد.","حدد الصلاحية بتجربة تخزين حقيقية."],"en":["Cool fully before packing.","Chilled storage for soft products.","Sanitise cutting and cooling surfaces.","Set shelf life by a real storage trial."]},"notFormula":{"ar":"العفن غالباً من التغليف أو التخزين أو النظافة؛ الوصفة تأثيرها على السرعة فقط.","en":"Mould is usually packing, storage or hygiene; the recipe only affects how fast it comes."},"unsure":{"ar":"جاوب سؤال التغليف والتخزين أول.","en":"Answer the packing and storage questions first."}},{"id":"laminate-leak","category":"industrial","status":"draft","reviewedBy":null,"severity":"medium","rescuable":false,"symptom":{"ar":"الزبدة تطلع من الكرواسون أو الميل فاي","en":"Butter leaks from croissants or puff pastry","syn":{"ar":["الزبدة تسيح من الكرواسون","الكرواسون يطلع زيت في الفرن","الطبقات ما طلعت","الميل فاي ما انتفخ","الزبدة انكسرت داخل العجينة"],"en":["butter leaking from croissants","croissants pool butter","no layers in puff pastry","butter broke in the dough"]}},"see":{"ar":"زبدة تسيل في الصينية وقت الخبز أو التخمير، والطبقات قليلة أو مختلطة، والقطع منخفضة.","en":"Butter pools on the tray during proofing or baking, the layers are few or merged, and the pieces are low."},"questions":[{"id":"room","ar":"حرارة المطبخ أو غرفة التخمير؟","en":"Kitchen or proofer temperature?","options":[{"id":"hot","ar":"فوق 26°م","en":"Above 26 °C"},{"id":"ok","ar":"تحت 24°م","en":"Below 24 °C"}]},{"id":"butter","ar":"نوع زبدة الطبقات؟","en":"Which laminating butter?","options":[{"id":"table","ar":"زبدة عادية للمائدة","en":"Ordinary table butter"},{"id":"sheet","ar":"زبدة طبقات (شيت) أو 82% فما فوق","en":"Laminating sheet butter, or 82% and above"}]},{"id":"rest","ar":"الراحة بين الطيّات؟","en":"Rest between folds?","options":[{"id":"short","ar":"أقل من 20 دقيقة أو بدون","en":"Under 20 minutes or none"},{"id":"long","ar":"30 دقيقة أو أكثر في الثلاجة","en":"30 minutes or more chilled"}]}],"causes":[{"id":"too-warm","kind":"process","prior":1,"evidence":"established","src":["S1"],"title":{"ar":"المطبخ أو التخمير حار","en":"Kitchen or proofer too warm"},"why":{"ar":"إذا لانت الزبدة وقت الفرد، تختلط بالعجينة بدل ما تبقى طبقة. وفي التخمير فوق حوالي 28°م تذوب الزبدة وتسيل قبل الفرن.","en":"If the butter softens while rolling, it mixes into the dough instead of staying a layer. When proofing above about 28 °C, the butter melts and runs before baking."},"answers":{"room":{"hot":3,"ok":-2}},"fixes":[{"type":"process","evidence":"consensus","src":["S1"],"ar":"افرد في مكان بارد (تحت 22°م إذا تقدر)، وخمّر الكرواسون على 24 إلى 27°م مع رطوبة، وارجع العجينة للثلاجة أول ما تلين.","en":"Laminate somewhere cool (below 22 °C if possible), proof croissants at 24–27 °C with humidity, and return the dough to the fridge as soon as it softens.","tradeoff":{"ar":"تخمير أبطأ ووقت إنتاج أطول.","en":"Slower proofing and longer production."}}],"verify":{"ar":"قِس حرارة المطبخ وغرفة التخمير وسجّلها مع كل دفعة.","en":"Log the kitchen and proofer temperature with every batch."}},{"id":"butter-type","kind":"formula","prior":0,"evidence":"consensus","src":["S1","S9"],"title":{"ar":"الزبدة ما تناسب الطبقات","en":"The butter is not suited to laminating"},"why":{"ar":"زبدة الطبقات أكثر دهناً وأقل ماء ومرنة على حرارة الفرد. الزبدة العادية 80% أطرى وفيها ماء أكثر، فتنكسر أو تذوب أسرع.","en":"Laminating butter has more fat, less water and stays plastic at rolling temperature. Ordinary 80% butter is softer with more water, so it breaks or melts sooner."},"rule":{"feat":"butterFat","when":"below","range":{"default":[81,84]},"evidence":"estimate","src":["S9"],"note":{"ar":"يعتمد على نسبة الدهن المسجّلة لمادة الزبدة في المنصة. الحد الأدنى في مواصفة الدستور الغذائي 80%.","en":"Relies on the fat recorded for the butter material in the platform. The Codex minimum is 80%."}},"answers":{"butter":{"table":3,"sheet":-2}},"fixes":[{"type":"recipe","evidence":"established","src":["S9"],"ar":"استعمل زبدة 82% فما فوق بوزن أقل يعطي نفس كمية الدهن.","en":"Use 82% or higher butter at a lower weight giving the same fat.","op":{"op":"swap","from":"butter","to":"butter","factor":0.976,"name":{"ar":"زبدة 82%","en":"Butter 82%"},"comp":{"w":0.16,"f":0.82,"s":0.006,"p":0.009}},"tradeoff":{"ar":"أغلى، وقد تحتاج تغيّر المورد.","en":"Costs more and may need a new supplier."}}],"verify":{"ar":"اعمل دفعتين بنفس الظروف: زبدة عادية وزبدة طبقات، وقارن الطبقات.","en":"Make two batches under the same conditions, table and sheet butter, and compare the layers."}},{"id":"short-rest","kind":"process","prior":0,"evidence":"consensus","src":["S1"],"title":{"ar":"راحة قليلة بين الطيّات","en":"Too little rest between folds"},"why":{"ar":"بدون راحة في البرد، تسخن الزبدة من الفرد والغلوتين يشد، فتنكسر الزبدة وتخترق العجينة.","en":"Without a chilled rest, the butter warms from rolling and the gluten tightens, so the butter breaks through the dough."},"answers":{"rest":{"short":3,"long":-2}},"fixes":[{"type":"process","evidence":"consensus","src":["S1"],"ar":"رتّح العجينة 30 دقيقة على الأقل في الثلاجة بعد كل طيّة، وخلّ العجينة والزبدة بنفس الليونة تقريباً.","en":"Rest the dough at least 30 minutes chilled after each fold, and keep dough and butter at about the same firmness.","tradeoff":{"ar":"وقت إنتاج أطول.","en":"Longer production time."}}],"verify":{"ar":"قصّ قطعة بعد الخبز وعدّ الطبقات بين دفعة براحة ودفعة بدون.","en":"Cut a baked piece and count the layers, rested versus not."}}],"rescue":{"ar":["العجينة اللي اختلطت فيها الزبدة: استعملها لمعجنات ما تحتاج طبقات واضحة (مثل قاعدة مالحة أو بريوش مورّق خفيف)."],"en":["Dough where the butter has mixed in: use it for products that do not need clear layers (a savoury base or lightly layered brioche)."]},"prevent":{"ar":["مطبخ بارد وقت الفرد.","تخمير 24 إلى 27°م.","زبدة طبقات 82% فما فوق.","راحة 30 دقيقة بين الطيّات."],"en":["A cool kitchen when laminating.","Proof at 24–27 °C.","Laminating butter 82% or above.","30 minutes rest between folds."]},"notFormula":{"ar":"في الخليج أغلب تسرّب الزبدة من الحرارة، حتى مع زبدة ممتازة.","en":"In the Gulf most butter leakage is from heat, even with excellent butter."},"unsure":{"ar":"جاوب سؤال الحرارة أول.","en":"Answer the temperature question first."}},{"id":"cake-tough","category":"industrial","status":"draft","reviewedBy":null,"severity":"low","rescuable":true,"symptom":{"ar":"الكيك مطاطي أو قاسي","en":"Cake is rubbery or tough","syn":{"ar":["الكيك مطاطي","الكيك قاسي","الكيك يمطّ","الكيك علك","قوام الكيك مثل الخبز"],"en":["rubbery cake","tough cake","chewy cake","bready cake"]}},"see":{"ar":"القوام يمطّ أو قاسي بدل ما يكون طري ويتفتت بنعومة، وأحياناً فيه أنفاق.","en":"The crumb is chewy or tough instead of soft and tender, sometimes with tunnels."},"questions":[{"id":"mix","ar":"كم خلطت بعد الدقيق؟","en":"How long did you mix after the flour?","options":[{"id":"long","ar":"كثير بالخلاط","en":"A lot with the mixer"},{"id":"brief","ar":"قليل لين اختفى","en":"Briefly until it disappeared"}]},{"id":"flour","ar":"وش نوع الدقيق؟","en":"Which flour?","options":[{"id":"bread","ar":"دقيق خبز أو قوي","en":"Bread or strong flour"},{"id":"ap","ar":"متعدد الاستعمال","en":"All-purpose"},{"id":"cake","ar":"دقيق كيك أو معجنات","en":"Cake or pastry flour"}]}],"causes":[{"id":"overmixed","kind":"process","prior":1,"evidence":"established","src":["S1"],"title":{"ar":"خلط زايد بعد الدقيق","en":"Overmixed after the flour"},"why":{"ar":"الخلط مع وجود ماء يطوّر الغلوتين، فيصير الكيك مطاطي وفيه أنفاق.","en":"Mixing in the presence of water develops gluten, so the cake turns rubbery with tunnels."},"answers":{"mix":{"long":3,"brief":-2}},"fixes":[{"type":"process","evidence":"consensus","src":["S1"],"ar":"أضف الدقيق على سرعة منخفضة وتوقف أول ما يختفي، وكمّل باليد.","en":"Add the flour on low speed, stop as soon as it disappears, and finish by hand.","tradeoff":{"ar":"انتبه لبقع دقيق ما اختلطت.","en":"Watch for unmixed flour pockets."}}],"verify":{"ar":"قارن دفعتين: خلط قصير وطويل.","en":"Compare short and long mixing."}},{"id":"strong-flour","kind":"formula","prior":0,"evidence":"established","src":["S1","S7"],"title":{"ar":"الدقيق قوي على الكيك","en":"Flour too strong for cake"},"why":{"ar":"دقيق الكيك عادة بروتينه منخفض. الدقيق الأقوى يكوّن غلوتين أكثر. بعض الدقيق المحلي متعدد الاستعمال قريب من دقيق الخبز، فتأكد من مورّدك.","en":"Cake flour is usually low in protein. Stronger flour forms more gluten. Some local all-purpose flours are close to bread flour, so check with your supplier."},"rule":{"feat":"flourProtein","when":"above","range":{"default":[7,10]},"evidence":"estimate","src":["S1"],"note":{"ar":"يعتمد على نسبة البروتين المسجلة لمادة الدقيق؛ دقيق الكيك أقل من المعجنات والخبز.","en":"Relies on the protein recorded for the flour material; cake flour is lower than pastry and bread flour."}},"answers":{"flour":{"bread":3,"ap":1,"cake":-2}},"fixes":[{"type":"recipe","evidence":"consensus","src":["S1"],"ar":"بدّل 20% من الدقيق بنشا ذرة لتقريبه من دقيق الكيك.","en":"Replace 20% of the flour with cornstarch to bring it closer to cake flour.","op":{"op":"swap","from":"flour","to":"starch","frac":0.2,"factor":1,"name":{"ar":"نشا ذرة","en":"Cornstarch"},"comp":{"w":0.12}},"tradeoff":{"ar":"أطرى وأهش، والهيكل أضعف مع الحشوات الثقيلة.","en":"Softer and more tender, but weaker under heavy fillings."}}],"verify":{"ar":"سجّل نسبة بروتين الدقيق من المورد في مادة الدقيق، وقارن القوام بعد التعديل.","en":"Record the supplier's flour protein on the flour material and compare the crumb after the change."}},{"id":"sugar-low","kind":"formula","prior":0,"evidence":"established","src":["S1"],"title":{"ar":"السكر قليل","en":"Too little sugar"},"why":{"ar":"السكر يطري الكيك لأنه يعيق تكوّن الغلوتين ويؤخر تماسك البروتين.","en":"Sugar tenderises cake by hindering gluten formation and delaying protein setting."},"rule":{"feat":"sugarFlour","when":"below","range":{"default":[0.8,1.25]},"evidence":"consensus","src":["S1","S3"]},"answers":{"mix":{"brief":1}},"fixes":[{"type":"recipe","evidence":"consensus","src":["S1"],"ar":"ارفع السكر إلى وزن الدقيق تقريباً.","en":"Raise the sugar to about the flour weight.","op":{"op":"ratio","role":["sugar"],"base":"flour","target":1},"tradeoff":{"ar":"أحلى وقشرة أغمق.","en":"Sweeter with a darker crust."}}],"verify":{"ar":"قارن طراوة القطعتين بعد التبريد.","en":"Compare tenderness of both after cooling."}}],"rescue":{"ar":["الكيك المطاطي يصلح لطبقات مشبّعة بشراب أو للترايفل."],"en":["A rubbery cake works for syrup-soaked layers or trifle."]},"prevent":{"ar":["خلط قصير بعد الدقيق.","دقيق كيك أو معجنات، واعرف بروتين دقيقك.","سكر قريب من وزن الدقيق."],"en":["Short mixing after the flour.","Cake or pastry flour, and know your flour's protein.","Sugar near the flour weight."]},"notFormula":{"ar":"إذا الدقيق للكيك والسكر كافي، فالسبب غالباً الخلط.","en":"If the flour suits cake and sugar is enough, the cause is most likely mixing."},"unsure":{"ar":"جاوب سؤال الخلط ونوع الدقيق.","en":"Answer the mixing and flour questions."}},{"id":"butter-switch","category":"industrial","status":"draft","reviewedBy":null,"severity":"low","rescuable":true,"symptom":{"ar":"النتيجة تغيّرت بعد ما بدّلت نوع الزبدة","en":"Results changed after switching butter","syn":{"ar":["غيرت الزبدة وتغيرت الوصفة","الزبدة الجديدة خربت العجينة","زبدة 80 بدل 82","الزبدة المحلية تختلف","العجينة صارت طرية بعد تغيير الزبدة"],"en":["changed butter brand","new butter ruined the dough","80% vs 82% butter","local butter behaves differently"]}},"see":{"ar":"نفس الوصفة تطلع مختلفة: عجينة أطرى أو تنكمش، أو كريمة زبدة وغاناش ينفصلان، أو كيك قوامه تغيّر.","en":"The same recipe turns out different: a softer or shrinking dough, buttercream or ganache that splits, or a changed cake crumb."},"questions":[{"id":"change","ar":"وش اللي تغيّر؟","en":"What changed?","options":[{"id":"dough","ar":"العجينة أطرى أو تنكمش أكثر","en":"Dough softer or shrinks more"},{"id":"emul","ar":"كريمة الزبدة أو الغاناش انفصل","en":"Buttercream or ganache split"},{"id":"melt","ar":"تذوب أسرع في الحر","en":"Melts faster in the heat"}]},{"id":"fat","ar":"نسبة الدهن في الزبدة الجديدة؟","en":"Fat in the new butter?","options":[{"id":"80","ar":"80% أو ما أعرف (أغلب الزبدة العادية)","en":"80% or not sure (most table butter)"},{"id":"82","ar":"82% أو أكثر","en":"82% or more"}]}],"causes":[{"id":"fat-lower","kind":"formula","prior":0,"evidence":"established","src":["S9"],"title":{"ar":"الزبدة الجديدة دهنها أقل وماؤها أكثر","en":"The new butter has less fat and more water"},"why":{"ar":"الزبدة 80% فيها ماء حوالي 16 إلى 18%، أكثر من زبدة 82% فما فوق. الفرق بسيط، لكنه يكفي يزيد الغلوتين في العجائن ويخل بالمستحلبات الحساسة.","en":"80% butter holds about 16–18% water, more than 82%+ butter. The gap is small, but it is enough to strengthen gluten in doughs and upset sensitive emulsions."},"rule":{"feat":"butterFat","when":"below","range":{"default":[81,84]},"evidence":"established","src":["S9"],"note":{"ar":"يعتمد على نسبة الدهن المسجلة لمادة الزبدة. سجّل الزبدة الجديدة بنسبتها من الملصق.","en":"Relies on the fat recorded for the butter material. Record the new butter with its label value."}},"answers":{"fat":{"80":2,"82":-2},"change":{"dough":1,"emul":1}},"fixes":[{"type":"recipe","evidence":"established","src":["S9"],"ar":"إذا رجعت لزبدة 82%، استعمل وزن أقل قليلاً يعطي نفس الدهن وماء أقل.","en":"If you go back to 82% butter, use a slightly lower weight giving the same fat with less water.","op":{"op":"swap","from":"butter","to":"butter","factor":0.976,"name":{"ar":"زبدة 82%","en":"Butter 82%"},"comp":{"w":0.16,"f":0.82,"s":0.006,"p":0.009}},"tradeoff":{"ar":"أغلى في الغالب.","en":"Usually costs more."}}],"verify":{"ar":"اعمل الوصفة بالزبدتين بنفس اليوم والحرارة وقارن.","en":"Make the recipe with both butters on the same day and temperature and compare."}},{"id":"softness","kind":"process","prior":1,"evidence":"consensus","src":["S1"],"title":{"ar":"ليونة الزبدة تختلف بين الأنواع","en":"Butter firmness differs between brands"},"why":{"ar":"كل زبدة لها نقطة ليونة مختلفة حسب تركيب الدهن والموسم، فنفس الحرارة تعطي زبدة أطرى أو أقسى من قبل.","en":"Each butter softens at a different point depending on its fat makeup and season, so the same temperature gives a softer or harder butter than before."},"answers":{"change":{"melt":3,"dough":1}},"fixes":[{"type":"process","evidence":"consensus","src":["S1"],"ar":"قِس حرارة الزبدة وقت الاستعمال، واضبطها حسب النوع الجديد (غالباً تحتاج تبريد أكثر في الحر).","en":"Measure the butter temperature at use and adjust it for the new brand (in the heat it usually needs more chilling).","tradeoff":{"ar":"تجارب قليلة لضبط الحرارة الجديدة.","en":"A few trials to find the new temperature."}}],"verify":{"ar":"سجّل حرارة الزبدة مع كل دفعة لين تثبت النتيجة.","en":"Log the butter temperature with each batch until results settle."}},{"id":"emulsion-water","kind":"formula","prior":0,"evidence":"established","src":["S4"],"title":{"ar":"الماء الإضافي أخل بالمستحلب","en":"The extra water upset the emulsion"},"why":{"ar":"في كريمة الزبدة والغاناش، الماء الزايد من الزبدة يقرب الخليط من حد الانفصال، خصوصاً إذا الوصفة أصلاً على الحد.","en":"In buttercream and ganache the extra water from the butter pushes the mix closer to splitting, especially if the recipe was already at the limit."},"answers":{"change":{"emul":3}},"fixes":[{"type":"process","evidence":"consensus","src":["S4"],"ar":"افتح تشخيص «كريمة الزبدة تقطّعت» أو «الغاناش انفصل» على وصفتك، وقلّل السائل المضاف (عصير، كريمة) قليلاً.","en":"Open the “Buttercream split” or “Ganache split” diagnosis on your recipe, and slightly reduce the added liquid (juice, cream).","tradeoff":{"ar":"طعم الفاكهة أو الكريمة أخف قليلاً.","en":"Slightly milder fruit or cream flavour."}}],"verify":{"ar":"إذا ثبت المستحلب بعد تقليل السائل، فالسبب كان الماء.","en":"If the emulsion holds after reducing the liquid, water was the cause."}}],"rescue":{"ar":["كمّل حسب المشكلة: افتح تشخيص المنتج نفسه (عجينة، كريمة زبدة، غاناش)."],"en":["Continue by product: open that product's own diagnosis (dough, buttercream, ganache)."]},"prevent":{"ar":["سجّل كل زبدة في المنصة بنسبة دهنها من الملصق.","جرّب أي زبدة جديدة على دفعة صغيرة قبل الإنتاج.","قِس حرارة الزبدة دائماً."],"en":["Record every butter in the platform with its label fat.","Trial any new butter on a small batch before production.","Always measure butter temperature."]},"notFormula":{"ar":"إذا الزبدتين بنفس نسبة الدهن، فالفرق غالباً في ليونتها وحرارتها.","en":"If both butters have the same fat, the difference is most likely firmness and temperature."},"unsure":{"ar":"سجّل نسبة دهن الزبدة الجديدة من الملصق عشان أقدر أقارن.","en":"Record the new butter's fat from the label so I can compare."}},{"id":"chocolate-bloom","category":"chocolate","status":"draft","reviewedBy":null,"severity":"low","rescuable":true,"symptom":{"ar":"الشوكولاتة طلع عليها أبيض أو صارت باهتة","en":"Chocolate turned white or dull","syn":{"ar":["الشوكولاتة بيضاء","خطوط بيضاء على الشوكولاتة","الشوكولاتة باهتة","البونبون صار رمادي","الشوكولاتة مغبرة"],"en":["chocolate bloom","white streaks on chocolate","dull chocolate","grey bonbons"]}},"see":{"ar":"طبقة بيضاء أو رمادية على السطح، أو خطوط ولمعة ضايعة.","en":"A white or grey film on the surface, or streaks and lost shine."},"questions":[{"id":"feel","ar":"إذا مسحت السطح بإصبعك؟","en":"If you rub the surface with a finger?","options":[{"id":"greasy","ar":"يذوب ويحس دهني","en":"It melts and feels greasy"},{"id":"dry","ar":"ناشف ورملي، وما يذوب","en":"Dry and sandy, does not melt"}]},{"id":"store","ar":"كيف كان التخزين؟","en":"How was it stored?","options":[{"id":"fridge","ar":"من الثلاجة للجو مباشرة","en":"Straight from the fridge to the room"},{"id":"warm","ar":"حرارة متغيرة أو فوق 22°م","en":"Changing, or above 22 °C"},{"id":"stable","ar":"ثابت 15 إلى 18°م","en":"Steady 15–18 °C"}]},{"id":"temper","ar":"هل الشوكولاتة متمبّرة صح؟","en":"Was the chocolate properly tempered?","options":[{"id":"yes","ar":"نعم: لمّاعة وتنكسر بصوت","en":"Yes: glossy with a snap"},{"id":"no","ar":"لا أو ما أعرف","en":"No, or not sure"}]}],"causes":[{"id":"sugar-bloom","kind":"process","prior":0,"evidence":"established","src":["S5","S8"],"title":{"ar":"تزهّر السكر من التكثّف","en":"Sugar bloom from condensation"},"why":{"ar":"لما تطلع الشوكولاتة الباردة لجو حار ورطب، يتكثف الماء على سطحها فيذوّب السكر، ولما يجف يترك بلورات بيضاء. هذا شائع جداً في الخليج.","en":"When cold chocolate meets warm, humid air, water condenses on it and dissolves sugar; as it dries it leaves white crystals. Very common in the Gulf."},"answers":{"feel":{"dry":3,"greasy":-2},"store":{"fridge":3,"stable":-1}},"fixes":[{"type":"process","evidence":"established","src":["S5"],"ar":"خزّن على 15 إلى 18°م ورطوبة أقل من 60%. إذا لازم الثلاجة، خلّها في علبة مقفلة وخلّها تدفى داخل العلبة لحرارة الغرفة قبل ما تفتحها.","en":"Store at 15–18 °C and below 60% humidity. If you must refrigerate, keep it in a sealed box and let it warm to room temperature inside the box before opening.","tradeoff":{"ar":"يحتاج مكان مضبوط الحرارة والرطوبة.","en":"Needs a temperature- and humidity-controlled space."}}],"verify":{"ar":"امسح السطح: البقع الناشفة اللي ما تذوب هي سكر.","en":"Rub the surface: dry spots that do not melt are sugar."}},{"id":"fat-bloom","kind":"process","prior":1,"evidence":"established","src":["S5"],"title":{"ar":"تزهّر الدهن","en":"Fat bloom"},"why":{"ar":"إذا الشوكولاتة مو متمبّرة صح، أو تعرّضت لحرارة متغيرة، تتبلور زبدة الكاكاو بشكل خشن وتطلع على السطح بلون أبيض دهني.","en":"If the chocolate is not well tempered or meets changing temperatures, cocoa butter recrystallises coarsely and surfaces as a greasy white film."},"answers":{"feel":{"greasy":3,"dry":-2},"store":{"warm":3,"stable":-1},"temper":{"no":2,"yes":-1}},"fixes":[{"type":"process","evidence":"consensus","src":["S5","S4"],"ar":"تمبر صح (للداكنة: ذوبان 45 إلى 50°م، تبريد 27 إلى 28°م، شغل 31 إلى 32°م)، وخزّن على حرارة ثابتة 15 إلى 18°م.","en":"Temper properly (dark: melt 45–50 °C, cool 27–28 °C, work 31–32 °C), and store at a steady 15–18 °C.","tradeoff":{"ar":"يحتاج ميزان حرارة وتخزين مضبوط.","en":"Needs a thermometer and controlled storage."}}],"verify":{"ar":"سوّ اختبار التمبير: ورقة صغيرة تتماسك لامعة خلال 5 دقائق على حرارة الغرفة.","en":"Tempering test: a small strip sets glossy within 5 minutes at room temperature."}},{"id":"fat-migration","kind":"formula","prior":0,"evidence":"established","src":["S5"],"title":{"ar":"دهن الحشوة يهاجر للقشرة","en":"Fat migrating from the filling"},"why":{"ar":"الحشوات الغنية بدهون المكسرات (براليني، جياندوجا) تنتقل دهونها لقشرة الشوكولاتة مع الوقت فتليّنها وتسبب تزهّر.","en":"Fillings rich in nut fats (praline, gianduja) move their oil into the chocolate shell over time, softening it and causing bloom."},"rule":{"feat":"fat","when":"above","range":{"default":[20,40]},"evidence":"estimate","src":["S5"],"note":{"ar":"طبّق هذا على وصفة الحشوة. حد تقديري؛ هجرة الدهن تعتمد أكثر على نوع الدهن من كميته.","en":"Apply this to the filling recipe. A working limit; migration depends more on the type of fat than the amount."}},"answers":{"temper":{"yes":1}},"fixes":[{"type":"process","evidence":"consensus","src":["S5"],"ar":"استعمل قشرة أسمك، أو طبقة عازلة رقيقة من زبدة كاكاو، أو أضف زبدة كاكاو للحشوة لتثبيت دهونها، وخزّن على حرارة باردة ثابتة.","en":"Use a thicker shell, a thin cocoa-butter barrier, or add cocoa butter to the filling to firm its fats, and store cool and steady.","tradeoff":{"ar":"القشرة الأسمك تغيّر الإحساس في الفم والتكلفة.","en":"A thicker shell changes mouthfeel and cost."}}],"verify":{"ar":"خزّن بونبون من نفس الدفعة على 16 و24°م وراقب التزهّر أسبوعياً.","en":"Store bonbons from one batch at 16 and 24 °C and check bloom weekly."}}],"rescue":{"ar":["الشوكولاتة المتزهّرة آمنة للأكل. تقدر تذوّبها وتعيد تمبيرها واستعمالها.","البونبون المتزهّر: استعمله للتذوق الداخلي أو أعد تقديمه مقطّع."],"en":["Bloomed chocolate is safe to eat. You can melt, re-temper and reuse it.","Bloomed bonbons: use for internal tasting or re-present them cut."]},"prevent":{"ar":["تمبير صحيح.","تخزين ثابت 15 إلى 18°م ورطوبة أقل من 60%.","دفّي العلب المقفلة قبل فتحها بعد الثلاجة.","قشرة كافية حول حشوات المكسرات."],"en":["Proper tempering.","Steady 15–18 °C and below 60% humidity.","Warm sealed boxes before opening after the fridge.","Enough shell around nut fillings."]},"notFormula":{"ar":"أغلب التزهّر من التمبير أو التخزين؛ الوصفة تأثر فقط في حشوات المكسرات.","en":"Most bloom is tempering or storage; the recipe matters only for nut fillings."},"unsure":{"ar":"سوّ اختبار الإصبع: دهني يعني دهن، رملي يعني سكر.","en":"Do the finger test: greasy means fat, sandy means sugar."}},{"id":"temper-fail","category":"chocolate","status":"draft","reviewedBy":null,"severity":"medium","rescuable":true,"symptom":{"ar":"الشوكولاتة ما تتماسك أو ما تطلع من القالب أو بدون لمعة","en":"Chocolate will not set, release from the mould or shine","syn":{"ar":["التمبير ما ضبط","الشوكولاتة ما تجمد","الشوكولاتة لاصقة في القالب","الشوكولاتة ما تلمع","الشوكولاتة ما تنكسر بصوت"],"en":["tempering failed","chocolate will not set","sticks to the mould","no snap","streaky chocolate"]}},"see":{"ar":"الشوكولاتة تبقى طرية أو تتماسك ببطء، ما تنفصل عن القالب، باهتة أو فيها خطوط، وما تنكسر بصوت.","en":"The chocolate stays soft or sets slowly, sticks in the mould, is dull or streaky, and does not snap."},"questions":[{"id":"method","ar":"كيف تمبّرت؟","en":"How did you temper?","options":[{"id":"curve","ar":"منحنى حرارة بالميزان (ذوبان، تبريد، رفع)","en":"A temperature curve with a thermometer"},{"id":"eye","ar":"بالعين أو بدون قياس","en":"By eye or without measuring"}]},{"id":"work","ar":"حرارة الشوكولاتة وقت الصب؟","en":"Chocolate temperature when using it?","options":[{"id":"hot","ar":"أعلى من حرارة الشغل (فوق 33°م للداكنة)","en":"Above working temperature (over 33 °C for dark)"},{"id":"ok","ar":"حسب الجدول","en":"As specified"},{"id":"nk","ar":"ما قستها","en":"Did not measure"}]},{"id":"room","ar":"حرارة المكان؟","en":"Room temperature?","options":[{"id":"hot","ar":"فوق 24°م","en":"Above 24 °C"},{"id":"ok","ar":"20 إلى 22°م","en":"20–22 °C"}]}],"causes":[{"id":"not-tempered","kind":"process","prior":1,"evidence":"established","src":["S5","S4"],"title":{"ar":"ما انتمبّرت صح","en":"Not properly tempered"},"why":{"ar":"زبدة الكاكاو تتبلور بأشكال مختلفة. التمبير يطلع الشكل الصحيح اللي يعطي لمعة وصوت وانكماش من القالب. بدونه تتماسك ببطء وتلزق وتطلع باهتة.","en":"Cocoa butter crystallises in several forms. Tempering makes the right one, which gives shine, snap and shrinkage from the mould. Without it chocolate sets slowly, sticks and is dull."},"answers":{"method":{"eye":3,"curve":-1},"work":{"nk":1}},"fixes":[{"type":"process","evidence":"consensus","src":["S4","S5"],"ar":"اتبع منحنى الحرارة من المصنّع (مثال الداكنة: 45 إلى 50 ثم 27 إلى 28 ثم 31 إلى 32°م)، أو استعمل طريقة البذر بشوكولاتة متمبّرة مفرومة.","en":"Follow the maker's temperature curve (dark example: 45–50, then 27–28, then 31–32 °C), or use the seeding method with chopped tempered chocolate.","tradeoff":{"ar":"يحتاج ميزان حرارة دقيق ووقت.","en":"Needs an accurate thermometer and time."}}],"verify":{"ar":"اختبار الورقة: شريحة تتماسك لامعة خلال 5 دقائق على 20°م.","en":"Strip test: a sample sets glossy within 5 minutes at 20 °C."}},{"id":"lost-temper","kind":"process","prior":0,"evidence":"established","src":["S5"],"title":{"ar":"التمبير ضاع من الحرارة","en":"Temper lost to heat"},"why":{"ar":"إذا سخنت الشوكولاتة المتمبّرة فوق حرارة الشغل، تذوب البلورات الصحيحة ويضيع التمبير. والمكان الحار يبطئ التماسك.","en":"If tempered chocolate warms above working temperature, the good crystals melt and the temper is lost. A hot room also slows setting."},"answers":{"work":{"hot":3,"ok":-1},"room":{"hot":2,"ok":-1}},"fixes":[{"type":"process","evidence":"consensus","src":["S5"],"ar":"حافظ على حرارة الشغل بدون زيادة، واشتغل في مكان 20 إلى 22°م، وبرّد القوالب بعد الصب في مكان 15 إلى 18°م (مو فريزر).","en":"Hold working temperature without going over, work in a 20–22 °C room, and cool moulds after casting at 15–18 °C (not the freezer).","tradeoff":{"ar":"تكييف المكان في الصيف.","en":"Air-conditioning the room in summer."}}],"verify":{"ar":"قِس حرارة الشوكولاتة كل 10 دقائق أثناء الشغل وسجّلها.","en":"Measure the chocolate every 10 minutes while working and log it."}},{"id":"foreign-fat","kind":"formula","prior":0,"evidence":"established","src":["S5"],"title":{"ar":"دهن غريب مضاف للشوكولاتة","en":"A foreign fat added to the chocolate"},"why":{"ar":"الزبدة أو الزيت المضاف لشوكولاتة التغطية يخلط مع زبدة الكاكاو ويضعف تبلورها، فتصير أطرى وما تنفصل عن القالب.","en":"Butter or oil added to coating chocolate mixes with the cocoa butter and weakens its crystallisation, so it turns softer and will not release."},"rule":{"feat":"butterPct","when":"above","range":{"default":[0,2]},"evidence":"estimate","src":["S5"],"note":{"ar":"لوصفات التغطية والقوالب فقط. في الغاناش الزبدة طبيعية.","en":"For coating and moulding recipes only. In ganache, butter is normal."}},"answers":{"method":{"curve":1}},"fixes":[{"type":"process","evidence":"established","src":["S5"],"ar":"لا تضيف زبدة أو زيت لشوكولاتة القوالب. إذا تبيها أسيل، أضف زبدة كاكاو (حتى 5 إلى 10%).","en":"Do not add butter or oil to moulding chocolate. To make it more fluid, add cocoa butter (up to 5–10%).","tradeoff":{"ar":"زبدة الكاكاو أغلى.","en":"Cocoa butter costs more."}}],"verify":{"ar":"اصبب قالبين: شوكولاتة صافية ومخلوطة، وقارن الانفصال.","en":"Cast two moulds, pure and blended chocolate, and compare release."}}],"rescue":{"ar":["الشوكولاتة اللي ما انتمبّرت ما تخرب: ذوّبها كاملاً (45 إلى 50°م للداكنة) وأعد التمبير.","القطع اللاصقة: حطها في مكان بارد 15°م وانتظر قبل ما تفصلها."],"en":["Untempered chocolate is not ruined: melt it fully (45–50 °C for dark) and temper again.","Stuck pieces: put them somewhere cool at 15 °C and wait before releasing."]},"prevent":{"ar":["ميزان حرارة دقيق.","اتبع منحنى المصنّع.","مكان شغل 20 إلى 22°م.","بدون دهون غريبة في شوكولاتة القوالب."],"en":["An accurate thermometer.","Follow the maker's curve.","A 20–22 °C work room.","No foreign fats in moulding chocolate."]},"notFormula":{"ar":"إذا الشوكولاتة صافية، فالمشكلة من التمبير أو الحرارة.","en":"If the chocolate is pure, the problem is tempering or heat."},"unsure":{"ar":"سوّ اختبار الورقة، وجاوب سؤال الطريقة.","en":"Do the strip test and answer the method question."}},{"id":"chocolate-seize","category":"chocolate","status":"draft","reviewedBy":null,"severity":"medium","rescuable":true,"symptom":{"ar":"الشوكولاتة تكتلت وصارت ثقيلة وقت الذوبان","en":"Chocolate seized into a thick lump while melting","syn":{"ar":["الشوكولاتة تكتلت","الشوكولاتة صارت عجينة","الشوكولاتة احترقت","الشوكولاتة البيضاء تحببت","الشوكولاتة ثقلت فجأة"],"en":["chocolate seized","chocolate turned grainy","burnt chocolate","white chocolate seized"]}},"see":{"ar":"الشوكولاتة اللامعة صارت فجأة كتلة ثقيلة محببة، أو صار لونها غامق وريحتها محروقة.","en":"Glossy chocolate suddenly turns into a thick, grainy mass, or darkens and smells burnt."},"questions":[{"id":"water","ar":"لمسها ماء أو بخار؟","en":"Did water or steam touch it?","options":[{"id":"yes","ar":"نعم أو ممكن (حمام مائي، ملعقة مبللة)","en":"Yes or maybe (water bath, wet spoon)"},{"id":"no","ar":"لا","en":"No"}]},{"id":"heat","ar":"كيف ذوّبتها؟","en":"How did you melt it?","options":[{"id":"strong","ar":"مايكرويف لفترات طويلة أو نار مباشرة","en":"Long microwave bursts or direct heat"},{"id":"gentle","ar":"حمام مائي هادئ أو مايكرويف على دفعات قصيرة","en":"Gentle water bath or short microwave bursts"}]}],"causes":[{"id":"water-contact","kind":"process","prior":1,"evidence":"established","src":["S2","S4"],"title":{"ar":"قطرات ماء أو بخار","en":"Drops of water or steam"},"why":{"ar":"قطرة ماء صغيرة تبلل حبيبات السكر والكاكاو فتلصق ببعض وتتحول الشوكولاتة لكتلة. الماء الكثير (مثل الغاناش) يعطي سائل، لكن القليل يكتّلها.","en":"A little water wets the sugar and cocoa particles so they stick and the chocolate clumps. A lot of water (as in ganache) gives a fluid, but a little seizes it."},"answers":{"water":{"yes":3,"no":-2}},"fixes":[{"type":"process","evidence":"established","src":["S4"],"ar":"استعمل أدوات ناشفة تماماً، ولا تخلّ بخار الحمام المائي يوصل (الوعاء أكبر من القدر والماء ما يغلي).","en":"Use completely dry tools and keep water-bath steam away (bowl wider than the pan, water not boiling).","tradeoff":{"ar":"ما في.","en":"None."}}],"verify":{"ar":"ذوّب دفعة بأدوات ناشفة وبدون بخار وقارن.","en":"Melt a batch with dry tools and no steam and compare."}},{"id":"overheated","kind":"process","prior":0,"evidence":"established","src":["S5"],"title":{"ar":"سخنت زيادة","en":"Overheated"},"why":{"ar":"الشوكولاتة تحترق بسهولة، خصوصاً البيضاء والحليب لأن فيها حليب يتكتل. فوق حوالي 50°م للداكنة و45°م للحليب والبيضاء تثخن وتتغير.","en":"Chocolate scorches easily, especially white and milk, whose milk solids clump. Above about 50 °C for dark and 45 °C for milk and white it thickens and changes."},"answers":{"heat":{"strong":3,"gentle":-2},"water":{"no":1}},"fixes":[{"type":"process","evidence":"consensus","src":["S5"],"ar":"ذوّب على دفعات قصيرة في المايكرويف (20 إلى 30 ثانية) مع التحريك، أو على حمام مائي هادئ، وقِس الحرارة.","en":"Melt in short microwave bursts (20–30 seconds) with stirring, or over a gentle water bath, and measure.","tradeoff":{"ar":"أبطأ.","en":"Slower."}}],"verify":{"ar":"قِس الحرارة أثناء الذوبان ولا تتجاوز الحد.","en":"Measure while melting and never exceed the limit."}},{"id":"little-liquid","kind":"formula","prior":0,"evidence":"established","src":["S2","S4"],"title":{"ar":"سائل قليل مضاف للشوكولاتة","en":"A small amount of liquid added"},"why":{"ar":"إذا الوصفة تضيف سائل قليل للشوكولاتة (مثل ليكير أو قليل كريمة)، يكون في المنطقة اللي تكتّل فيها. زد السائل لين يصير غاناش، أو امنعه.","en":"A recipe that adds only a little liquid to chocolate (a liqueur or a splash of cream) sits in the seizing zone. Either add enough to make a ganache or leave it out."},"rule":{"feat":"water","when":"above","range":{"default":[0,1]},"evidence":"estimate","src":["S4"],"note":{"ar":"لوصفات الشوكولاتة المذوّبة. إذا الماء كثير (غاناش، 15% فما فوق) هذا طبيعي ومو سبب.","en":"For melted-chocolate recipes. If water is high (ganache, 15% and above), that is normal and not a cause."}},"answers":{"water":{"yes":1}},"fixes":[{"type":"process","evidence":"established","src":["S4"],"ar":"أضف السائل الدافئ مرة وحدة بكمية كافية لعمل غاناش، أو استعمل نكهات زيتية بدل المائية.","en":"Add the warm liquid all at once in enough quantity to make a ganache, or use oil-based flavours instead of water-based ones.","tradeoff":{"ar":"يتغير القوام إلى غاناش.","en":"The texture becomes a ganache."}}],"verify":{"ar":"قارن الإضافة القليلة بالإضافة الكافية على عيّنتين صغيرتين.","en":"Compare a small and an ample addition on two small samples."}}],"rescue":{"ar":["المتكتلة من الماء: أضف كريمة أو حليب دافئ تدريجياً واخلط حتى تصير صوص أو غاناش؛ ما تصلح للتمبير بعدها.","المحروقة: ما ترجع؛ استعملها في عجائن أو تخلّص منها إذا الطعم محروق."],"en":["Seized by water: add warm cream or milk gradually and blend into a sauce or ganache; it can no longer be tempered.","Burnt: it does not recover; use it in doughs or discard if it tastes burnt."]},"prevent":{"ar":["أدوات ناشفة.","ذوبان هادئ مع القياس.","لا تضيف سائل قليل للشوكولاتة."],"en":["Dry tools.","Gentle melting with measuring.","Do not add a little liquid to chocolate."]},"notFormula":{"ar":"التكتل غالباً من ماء عرضي أو حرارة زايدة.","en":"Seizing is usually accidental water or overheating."},"unsure":{"ar":"جاوب سؤال الماء أول.","en":"Answer the water question first."}},{"id":"mousse-dense","category":"mousse","status":"draft","reviewedBy":null,"severity":"low","rescuable":false,"symptom":{"ar":"الموس ثقيل وفيه هواء قليل","en":"Mousse is heavy with little air","syn":{"ar":["الموس ثقيل","الموس كثيف","الموس مو خفيف","الموس مثل الكريمة","الموس ما فيه هواء"],"en":["dense mousse","heavy mousse","mousse not airy","flat mousse"]}},"see":{"ar":"قوام كثيف مثل الكريمة بدل ما يكون خفيف وهوائي.","en":"A dense, creamy texture instead of light and airy."},"questions":[{"id":"whip","ar":"الكريمة المخفوقة كانت؟","en":"The whipped cream was?","options":[{"id":"soft","ar":"قمم ناعمة (تميل)","en":"Soft peaks (bending)"},{"id":"stiff","ar":"قاسية ومحببة","en":"Stiff and grainy"},{"id":"liquid","ar":"ما انخفقت كفاية","en":"Under-whipped"}]},{"id":"fold","ar":"كيف خلطت؟","en":"How did you combine?","options":[{"id":"gentle","ar":"طيّ بالسباتولا على دفعات","en":"Folded by spatula in stages"},{"id":"rough","ar":"مضرب أو خلط قوي","en":"Whisk or vigorous mixing"}]}],"causes":[{"id":"whip-state","kind":"process","prior":1,"evidence":"established","src":["S2","S1"],"title":{"ar":"الكريمة مو مخفوقة صح","en":"Cream not whipped correctly"},"why":{"ar":"الكريمة الناقصة الخفق فيها هواء قليل، والزايدة تتكتل وما تختلط بنعومة فتطير الهواء وقت الخلط. القمم الناعمة هي الأنسب للموس.","en":"Under-whipped cream holds little air, and over-whipped cream clumps and will not fold smoothly, losing air as you mix. Soft peaks suit mousse best."},"answers":{"whip":{"liquid":3,"stiff":3,"soft":-2}},"fixes":[{"type":"process","evidence":"consensus","src":["S1"],"ar":"اخفق الكريمة باردة حتى قمم ناعمة تميل، ولا تكمّل لقمم قاسية.","en":"Whip the cream cold to soft, bending peaks; do not go to stiff peaks.","tradeoff":{"ar":"يحتاج مراقبة.","en":"Needs watching."}}],"verify":{"ar":"زِن كوب من الموس قبل وبعد التعديل: الأخف فيه هواء أكثر.","en":"Weigh a cup of mousse before and after: lighter means more air."}},{"id":"deflated","kind":"process","prior":0,"evidence":"established","src":["S1"],"title":{"ar":"الهواء طار وقت الخلط","en":"Air knocked out while combining"},"why":{"ar":"الخلط القوي أو بالمضرب يكسّر فقاعات الكريمة المخفوقة.","en":"Vigorous mixing or whisking breaks the bubbles in the whipped cream."},"answers":{"fold":{"rough":3,"gentle":-2}},"fixes":[{"type":"process","evidence":"consensus","src":["S1"],"ar":"أضف ثلث الكريمة أولاً لتخفيف الخليط، ثم اطوِ الباقي بالسباتولا على دفعات بحركة من الأسفل للأعلى.","en":"Stir in a third of the cream to lighten the base, then fold in the rest with a spatula in stages, from bottom to top.","tradeoff":{"ar":"أبطأ.","en":"Slower."}}],"verify":{"ar":"قارن وزن الكوب بين خلط قوي وطيّ هادئ.","en":"Compare cup weight between vigorous mixing and gentle folding."}},{"id":"cream-low","kind":"formula","prior":0,"evidence":"consensus","src":["S1"],"title":{"ar":"الكريمة المخفوقة قليلة في الوصفة","en":"Too little whipped cream in the recipe"},"why":{"ar":"الهواء في الموس يجي من الكريمة المخفوقة (أو الميرنغ). إذا حصتها قليلة، يطلع الموس ثقيل.","en":"The air in mousse comes from whipped cream (or meringue). With too little of it the mousse is heavy."},"rule":{"feat":"creamPct","when":"below","range":{"default":[35,65]},"evidence":"estimate","src":["S1"],"note":{"ar":"للموس اللي يعتمد على الكريمة المخفوقة؛ الموس بالميرنغ يختلف.","en":"For mousses aerated with whipped cream; meringue-based mousses differ."}},"answers":{"whip":{"soft":1},"fold":{"gentle":1}},"fixes":[{"type":"recipe","evidence":"estimate","src":["S1"],"ar":"زد الكريمة حتى تصير حوالي 45% من الوزن.","en":"Increase the cream to about 45% of the weight.","op":{"op":"reach","role":"cream","feat":"creamPct","target":45},"tradeoff":{"ar":"طعم أخف للنكهة الأساسية، وتحتاج جيلاتين أكثر قليلاً.","en":"Milder base flavour, and it may need a little more gelatine."}}],"verify":{"ar":"اعمل كوب بالنسبة الجديدة وقارن الخفة.","en":"Make a cup at the new ratio and compare lightness."}}],"rescue":{"ar":["الموس الثقيل صالح كحشوة أو كريمة طبقات."],"en":["A heavy mousse works as a filling or layer cream."]},"prevent":{"ar":["كريمة باردة لقمم ناعمة.","طيّ هادئ على دفعات.","خليط الأساس 25 إلى 30°م قبل الكريمة."],"en":["Cold cream to soft peaks.","Gentle folding in stages.","Base at 25–30 °C before the cream."]},"notFormula":{"ar":"إذا الكريمة كافية في الوصفة، فالسبب غالباً الخفق أو الطيّ.","en":"If there is enough cream, the cause is most likely whipping or folding."},"unsure":{"ar":"جاوب سؤال الكريمة المخفوقة.","en":"Answer the whipped cream question."}},{"id":"meringue-weep","category":"meringue","status":"draft","reviewedBy":null,"severity":"low","rescuable":false,"symptom":{"ar":"الميرنغ يطلع قطرات شراب أو يعرق","en":"Meringue weeps syrup beads or sweats","syn":{"ar":["الميرنغ يعرق","قطرات على الميرنغ","الميرنغ يطلع شراب","الميرنغ صار لزج","الميرنغ ذاب"],"en":["weeping meringue","beading meringue","sticky meringue","meringue sweating"]}},"see":{"ar":"قطرات ذهبية لزجة على السطح أو سائل تحت الميرنغ، أو صار لزج بعد ساعات.","en":"Sticky golden beads on the surface or liquid under the meringue, or it turns sticky after hours."},"questions":[{"id":"sugar","ar":"كيف أضفت السكر؟","en":"How did you add the sugar?","options":[{"id":"slow","ar":"تدريجياً وذاب كاملاً (ما يحس محبب بين الأصابع)","en":"Gradually until dissolved (not gritty between fingers)"},{"id":"fast","ar":"مرة وحدة أو بقي محبب","en":"All at once, or it stayed gritty"}]},{"id":"air","ar":"رطوبة المكان؟","en":"Room humidity?","options":[{"id":"humid","ar":"رطب (صيف، قريب من البحر)","en":"Humid (summer, near the sea)"},{"id":"dry","ar":"مكيّف وناشف","en":"Air-conditioned and dry"}]},{"id":"bake","ar":"الخبز؟","en":"Baking?","options":[{"id":"short","ar":"قصير أو حرارة عالية","en":"Short or a hot oven"},{"id":"dry","ar":"طويل على حرارة منخفضة حتى نشف","en":"Long and low until dry"}]}],"causes":[{"id":"undissolved","kind":"process","prior":1,"evidence":"established","src":["S2"],"title":{"ar":"السكر ما ذاب كاملاً","en":"Sugar not fully dissolved"},"why":{"ar":"حبيبات السكر اللي ما ذابت تسحب الرطوبة وتذوب بعدين على شكل قطرات شراب.","en":"Undissolved sugar grains draw moisture and later melt into syrup beads."},"answers":{"sugar":{"fast":3,"slow":-2}},"fixes":[{"type":"process","evidence":"consensus","src":["S2"],"ar":"أضف السكر ملعقة ملعقة بعد ما يرغي البياض، أو استعمل ميرنغ سويسري (تسخين البياض والسكر لين يذوب) أو إيطالي (شراب 118 إلى 121°م).","en":"Add the sugar a spoonful at a time once the whites foam, or use a Swiss meringue (warm whites and sugar until dissolved) or an Italian one (syrup at 118–121 °C).","tradeoff":{"ar":"وقت أطول.","en":"Takes longer."}}],"verify":{"ar":"افرك قليل من الميرنغ بين أصابعك: لازم يكون ناعم بدون حبيبات.","en":"Rub a little meringue between your fingers: it should feel smooth, not gritty."}},{"id":"sugar-low","kind":"formula","prior":0,"evidence":"consensus","src":["S2","S1"],"title":{"ar":"السكر قليل مقابل البياض","en":"Too little sugar for the whites"},"why":{"ar":"السكر يثبّت الرغوة ويمسك الماء. إذا قليل، الرغوة تفقد ماءها وتطلع سائل.","en":"Sugar stabilises the foam and holds water. With too little, the foam loses water and leaks."},"rule":{"feat":"sugarWhite","when":"below","range":{"default":[0.8,2]},"evidence":"consensus","src":["S1"],"note":{"ar":"نفس الحد المستعمل في قواعد المنصة (المعتاد 1:1 إلى 2:1).","en":"The same limit as the platform's rules (usual 1:1 to 2:1)."}},"answers":{"sugar":{"slow":1}},"fixes":[{"type":"recipe","evidence":"consensus","src":["S1"],"ar":"ارفع السكر إلى وزن البياض على الأقل.","en":"Raise the sugar to at least the weight of the whites.","op":{"op":"ratio","role":["sugar"],"base":"white","target":1},"tradeoff":{"ar":"أحلى وأثقل قليلاً.","en":"Sweeter and slightly denser."}}],"verify":{"ar":"قارن الميرنغ بعد 6 ساعات بين النسبتين.","en":"Compare the meringues after 6 hours at both ratios."}},{"id":"humidity","kind":"process","prior":0,"evidence":"established","src":["S8"],"title":{"ar":"رطوبة الجو","en":"Air humidity"},"why":{"ar":"السكر يمتص الرطوبة من الجو، فالميرنغ في الجو الرطب يلين ويعرق. هذا شائع في صيف الخليج والمدن الساحلية.","en":"Sugar absorbs moisture from the air, so meringue softens and sweats in humid weather. Common in Gulf summers and coastal cities."},"answers":{"air":{"humid":3,"dry":-2}},"fixes":[{"type":"process","evidence":"consensus","src":["S8"],"ar":"اخبز في مكان مكيّف وناشف، وخزّن الميرنغ الناشف في علب محكمة مع مادة ماصة للرطوبة.","en":"Bake in a dry, air-conditioned space, and store dry meringue in airtight boxes with a desiccant.","tradeoff":{"ar":"تكلفة علب ومواد ماصة.","en":"Cost of boxes and desiccant."}}],"verify":{"ar":"خزّن قطعتين: علبة محكمة ومكشوفة، وقارن بعد يوم.","en":"Store two pieces, airtight and open, and compare after a day."}},{"id":"underbaked","kind":"process","prior":0,"evidence":"consensus","src":["S1"],"title":{"ar":"ما نشف كفاية في الفرن","en":"Not dried enough in the oven"},"why":{"ar":"الميرنغ الناشف يحتاج خبز طويل على حرارة منخفضة. الخبز القصير أو الحار يترك رطوبة في الداخل تطلع بعدين.","en":"Dry meringue needs a long, low bake. A short or hot bake leaves moisture inside that seeps out later."},"answers":{"bake":{"short":3,"dry":-2}},"fixes":[{"type":"process","evidence":"consensus","src":["S1"],"ar":"اخبز على حرارة منخفضة (حوالي 90 إلى 100°م) لين ينشف كامل، وخلّه يبرد داخل الفرن.","en":"Bake low (about 90–100 °C) until fully dry, and let it cool in the oven.","tradeoff":{"ar":"يشغل الفرن ساعات.","en":"Ties up the oven for hours."}}],"verify":{"ar":"اكسر قطعة: الداخل ناشف وهش.","en":"Break one: the inside is dry and crisp."}}],"rescue":{"ar":["الميرنغ اللي عرق: إذا ناشف، أرجعه للفرن المنخفض ينشف. إذا لزج كثير، استعمله مكسّر في طبقات أو إيتون ميس."],"en":["Sweating meringue: if dry, return it to a low oven to dry out. If very sticky, crumble it into layers or Eton mess."]},"prevent":{"ar":["سكر ذايب كاملاً.","السكر بوزن البياض أو أكثر.","خبز طويل منخفض.","تخزين محكم ومكان ناشف."],"en":["Fully dissolved sugar.","Sugar at least the weight of the whites.","Long, low baking.","Airtight storage in a dry place."]},"notFormula":{"ar":"إذا السكر بوزن البياض أو أكثر، فالسبب غالباً الذوبان أو الرطوبة أو الخبز.","en":"If the sugar is at least the weight of the whites, the cause is most likely dissolving, humidity or baking."},"unsure":{"ar":"جاوب سؤال السكر أول.","en":"Answer the sugar question first."}},{"id":"meringue-wont-whip","category":"meringue","status":"draft","reviewedBy":null,"severity":"low","rescuable":true,"symptom":{"ar":"البياض ما ينخفق أو الرغوة نزلت","en":"Egg whites will not whip or the foam collapsed","syn":{"ar":["البياض ما يتخفق","البيض ما يصير ميرنغ","الميرنغ نزل","الميرنغ سايل","البياض ما يمسك قمم"],"en":["whites won't whip","meringue collapsed","runny meringue","no peaks"]}},"see":{"ar":"البياض يبقى سائل ورغوي وما يمسك قمم، أو انخفق ثم نزل وصار محبب.","en":"The whites stay liquid and foamy without peaks, or whipped then fell and turned grainy."},"questions":[{"id":"fat","ar":"احتمال دهن أو صفار؟","en":"Any chance of fat or yolk?","options":[{"id":"yes","ar":"نعم: قطرة صفار أو وعاء بلاستيك أو دهني","en":"Yes: a drop of yolk, or a plastic or greasy bowl"},{"id":"no","ar":"لا، وعاء ستيل نظيف","en":"No, a clean steel bowl"}]},{"id":"sugar","ar":"متى أضفت السكر؟","en":"When did you add the sugar?","options":[{"id":"start","ar":"من البداية كله","en":"All at the start"},{"id":"foam","ar":"بعد ما رغى البياض، تدريجياً","en":"After the whites foamed, gradually"}]},{"id":"how","ar":"وش صار بالضبط؟","en":"What exactly happened?","options":[{"id":"never","ar":"ما انخفق أبداً","en":"It never whipped"},{"id":"over","ar":"انخفق ثم صار محبب ونزل","en":"It whipped, then went grainy and fell"}]}],"causes":[{"id":"fat","kind":"process","prior":1,"evidence":"established","src":["S2"],"title":{"ar":"دهن أو صفار في البياض","en":"Fat or yolk in the whites"},"why":{"ar":"حتى أثر بسيط من الدهن أو الصفار يمنع بروتينات البياض من تكوين الرغوة.","en":"Even a trace of fat or yolk stops egg-white proteins from forming a foam."},"answers":{"fat":{"yes":4,"no":-2},"how":{"never":2,"over":-1}},"fixes":[{"type":"process","evidence":"established","src":["S2"],"ar":"افصل البيض واحدة واحدة في وعاء صغير، واستعمل وعاء ستيل أو زجاج نظيف ومسحه بقليل خل أو ليمون.","en":"Separate eggs one at a time into a small bowl, and use a clean steel or glass bowl wiped with a little vinegar or lemon.","tradeoff":{"ar":"خطوة إضافية.","en":"An extra step."}}],"verify":{"ar":"اخفق بياض نظيف في وعاء جديد: إذا انخفق، فالسبب كان الدهن.","en":"Whip clean whites in a fresh bowl; if they whip, fat was the cause."}},{"id":"sugar-early","kind":"process","prior":0,"evidence":"established","src":["S2"],"title":{"ar":"السكر انضاف بدري","en":"Sugar added too early"},"why":{"ar":"السكر من البداية يبطئ تكوّن الرغوة ويقلل حجمها، لكنه يثبّتها بعدين. الأفضل تضيفه بعد ما يرغي البياض.","en":"Sugar at the start slows foaming and lowers volume, though it stabilises later. Add it once the whites are foamy."},"answers":{"sugar":{"start":3,"foam":-2},"how":{"never":1}},"fixes":[{"type":"process","evidence":"established","src":["S2"],"ar":"اخفق البياض لين يصير رغوي ثم أضف السكر تدريجياً.","en":"Whip the whites until foamy, then add the sugar gradually.","tradeoff":{"ar":"ما في.","en":"None."}}],"verify":{"ar":"قارن الحجم بين الطريقتين.","en":"Compare the volume between the two ways."}},{"id":"overwhipped","kind":"process","prior":0,"evidence":"established","src":["S2"],"title":{"ar":"خفق زايد","en":"Over-whipped"},"why":{"ar":"الخفق الزايد (خصوصاً بدون سكر كافي) يشد البروتينات زيادة فتتكتل وتطرد الماء والرغوة تنزل.","en":"Over-whipping (especially with little sugar) over-tightens the proteins so they clump, squeeze out water and the foam collapses."},"answers":{"how":{"over":3,"never":-2}},"fixes":[{"type":"process","evidence":"consensus","src":["S2"],"ar":"توقف أول ما تمسك قمم لامعة ثابتة، وأضف السكر لأنه يحمي من الخفق الزايد.","en":"Stop as soon as it holds glossy, firm peaks, and add sugar, which protects against over-whipping.","tradeoff":{"ar":"يحتاج مراقبة.","en":"Needs watching."}}],"verify":{"ar":"إذا الميرنغ لامع وناعم عند التوقف المبكر، فالسبب كان الخفق الزايد.","en":"If it is glossy and smooth when you stop earlier, over-whipping was the cause."}},{"id":"sugar-high","kind":"formula","prior":0,"evidence":"consensus","src":["S1"],"title":{"ar":"السكر عالي جداً مقابل البياض","en":"Sugar very high for the whites"},"why":{"ar":"السكر الكثير جداً يثقّل الخليط ويبطئ الخفق كثير، خصوصاً إذا انضاف بدري.","en":"Very high sugar weighs the mix down and slows whipping a lot, especially if added early."},"rule":{"feat":"sugarWhite","when":"above","range":{"default":[0.8,2]},"evidence":"consensus","src":["S1"],"note":{"ar":"المعتاد 1:1 إلى 2:1؛ فوق كذا يصير الخفق بطيء جداً.","en":"Usual 1:1 to 2:1; above that whipping becomes very slow."}},"answers":{"sugar":{"start":1}},"fixes":[{"type":"recipe","evidence":"consensus","src":["S1"],"ar":"خفّض السكر إلى 1.8 من وزن البياض.","en":"Lower the sugar to 1.8 times the whites.","op":{"op":"ratio","role":["sugar"],"base":"white","target":1.8},"tradeoff":{"ar":"أقل ثباتاً وأقل حلاوة.","en":"Less stable and less sweet."}}],"verify":{"ar":"قارن وقت الوصول للقمم بين النسبتين.","en":"Compare the time to reach peaks at both ratios."}}],"rescue":{"ar":["البياض اللي فيه دهن ما ينقذ للميرنغ؛ استعمله في عجائن.","المخفوق زيادة: أضف بياض طازج واخفق ثواني ليرجع ناعم."],"en":["Whites with fat cannot be saved for meringue; use them in batters.","Over-whipped: add a fresh white and whip a few seconds to smooth it."]},"prevent":{"ar":["وعاء ستيل نظيف بدون دهن.","افصل البيض بحذر.","السكر بعد الرغوة وتدريجياً.","توقف عند القمم اللامعة."],"en":["A clean, grease-free steel bowl.","Separate eggs carefully.","Sugar after foaming, gradually.","Stop at glossy peaks."]},"notFormula":{"ar":"أغلب مشاكل خفق البياض من الدهن أو الطريقة، مو من النسبة.","en":"Most whipping problems are fat or method, not the ratio."},"unsure":{"ar":"جاوب سؤال الدهن أول.","en":"Answer the fat question first."}}]};
